window.Q=window.Q||{};Q["세법"]=[{"i":"27회-2차-065","r":27,"y":2016,"c":2,"g":"","n":65,"q":"지방세기본법상 가산세에 관한 내용으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["무신고가산세(사기나 그 밖의 부정한 행위로 인하지 않은 경우): 납부세액의 100분의 20에 상당하는 금액","무신고가산세(사기나 그 밖의 부정행위로 인한 경우): 납부세액의 100분의 50에 상당하는 금액","과소신고가산세(사기나 그 밖의 부정한 행위로 인하지 않은경우): 과소신고분 세액의 100분의 20에 상당하는 금액","과소신고가산세(사기나 그 밖의 부정행위로 인한 경우): 부정과소신고분 세액의 100분의 50에 상당하는 금액","납부지연가산세: 납부하지 아니한 세액의 100분의 20에 상당하는 금액"],"a":[1],"p":31,"L":"세1-1","S":[],"m":"","f":{"판정":"수정","요약":"현행 지방세기본법상 무신고 20%(①정답 유지)·부정무신고 40%·과소신고 10%·부정과소 40%로 ②~④ 여전히 틀림. ⑤ 가산세 명칭 '납부불성실가산세'가 '납부지연가산세'로 바뀌어 명칭만 수정(세액도 일할 이자율+3% 구조라 여전히 틀림)","수정":[{"위치":"선지5","원문":"납부불성실가산세:납부하지 아니한 세액의 100분의 20에 상당하는 금액","수정문":"납부지연가산세: 납부하지 아니한 세액의 100분의 20에 상당하는 금액","근거":"지방세기본법 제55조 제1항","바뀐점":"가산세 명칭 납부불성실가산세→납부지연가산세(2020.12.29 개정)"}],"정답변경사유":""}},{"i":"27회-2차-066","r":27,"y":2016,"c":2,"g":"","n":66,"q":"지방세법상 사실상의 취득가격 또는 연부금액을 취득세의 과세표준으로 하는 경우 취득가격 또는 연부금액에 포함되지 않는 것은?(단, 특수관계인과의 거래가 아니며, 비용 등은 취득시기 이전에 지급되었음)","b":null,"bs":"없음","img":[],"ch":["전기사업법에 따라 전기를 사용하는 자가 분담하는 비용","건설자금에 충당한 차입금의 이자","법인이 연부로 취득하는 경우 연부 계약에 따른 이자상당액","취득에 필요한 용역을 제공받은 대가로 지급하는 용역비","취득대금 외에 당사자의 약정에 따른 취득자 조건 부담액"],"a":[1],"p":29,"L":"세2-1","S":[],"m":"","f":null},{"i":"27회-2차-067","r":27,"y":2016,"c":2,"g":"","n":67,"q":"지방세법상 다음의 재산세 과세표준에 적용되는 표준세율 중 가장 낮은 것은?","b":null,"bs":"없음","img":[],"ch":["과세표준 5천만원인 종합합산과세대상 토지","과세표준 2억원인 별도합산과세대상 토지","과세표준 20억원인 분리과세대상 목장용지","과세표준 6천만원인 주택(「지방세법」 제111조의2에 따른 1세대 1주택 특례세율 적용대상 아님)","과세표준 10억원인 분리과세대상 공장용지"],"a":[3],"p":30,"L":"세2-3","S":[],"m":"","f":{"판정":"수정","요약":"지방세법 제111조 표준세율: 종합합산 5천만원 0.2%, 별도합산 2억 0.2%, 목장용지 분리 0.07%(최저, ③정답 유지), 주택 6천만원 0.1%, 공장용지 0.2%. 별장 세율이 2023.3.14 삭제되어 ④의 '(별장 제외)'가 무의미하고, 1세대1주택 특례세율(0.05%) 혼동을 막기 위해 괄호만 수정","수정":[{"위치":"선지4","원문":"과세표준 6천만원인 주택(별장 제외)","수정문":"과세표준 6천만원인 주택(「지방세법」 제111조의2에 따른 1세대 1주택 특례세율 적용대상 아님)","근거":"지방세법 제111조 제1항 제3호, 제111조의2 제1항","바뀐점":"별장 세율(제111조 제1항 제3호 가목) 삭제, 1세대 1주택 특례세율 신설"}],"정답변경사유":""}},{"i":"27회-2차-068","r":27,"y":2016,"c":2,"g":"","n":68,"q":"지방세법상 재산세 과세대상에 대한 표준세율 적용에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["납세의무자가 해당 지방자치단체 관할구역에 소유하고 있는 종합합산과세대상 토지의 가액을 모두 합한 금액을 과세표준으로 하여 종합합산과세대상의 세율을 적용한다.","납세의무자가 해당 지방자치단체 관할구역에 소유하고 있는 별도 합산과세대상토지의 가액을 모두 합한 금액을 과세표준으로 하여 별도 합산과세대상의 세율을 적용한다.","분리과세대상이 되는 해당 토지의 가액을 과세표준으로 하여 분리과세대상의 세율을 적용한다.","납세의무자가 해당 지방자치단체 관할구역에 2개 이상의 주택을 소유하고 있는 경우 그 주택의 가액을 모두 합한 금액을 과세표준으로 하여 주택의 세율을 적용한다.","주택에 대한 토지와 건물의 소유자가 다를 경우 해당 주택의 토지와 건물의 가액을 합산한 과세표준에 주택의 세율을 적용한다."],"a":[4],"p":27,"L":"세2-3","S":[],"m":"","f":null},{"i":"27회-2차-069","r":27,"y":2016,"c":2,"g":"","n":69,"q":"소득세법상 국외자산의 양도에 대한 양도소득세 과세에 있어서 국내자산의 양도에 대한 양도소득세 규정 중 준용하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["비과세 양도소득","양도소득과세표준의 계산","기준시가의 산정","양도소득의 부당행위계산","양도 또는 취득의 시기"],"a":[3],"p":26,"L":"세3-2","S":[],"m":"","f":null},{"i":"27회-2차-070","r":27,"y":2016,"c":2,"g":"","n":70,"q":"소득세법상 거주자의 양도소득세 비과세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["국내에 1주택만을 보유하고 있는 1세대가 해외이주로 세대전원이 출국하는 경우 출국일로부터 3년이 되는날 해당주택을 양도하면 비과세 된다.","법원의 결정에 의하여 양도 당시 취득에 관한 등기가 불가능한 미등기 주택은 양도소득세 비과세가 배제되는 미등기 양도자산에 해당하지 않는다.","직장의 변경으로 세대전원이 다른 시로 주거를 이전하는 경우 6개월간 거주한 1주택을 양도하면 비과세된다.","양도 당시 실지거래가액이 13억원인 1세대 1주택의 양도로 발생하는 양도차익 전부가 비과세된다.","농지를 교환할 때 쌍방 토지가액의 차액이 가액이 큰 편의 3분의 1인 경우 발생하는 소득은 비과세된다."],"a":[2],"p":25,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"고가주택 기준이 9억→12억원(소득세법 제89조 제1항 제3호)으로 올라 ④ '실지거래가액 10억원 1세대1주택 양도차익 전부 비과세'가 현행상 옳은 문장이 됨 → 13억원으로 바꿔 다시 틀리게 함. ①해외이주 2년 이내(시행령 제154조 제1항 제2호 나목), ②법원결정 미등기 제외(시행령 제168조 제1항 제2호), ③1년 이상 거주(같은 항 제3호), ⑤4분의 1 이하(시행령 제153조 제1항) 현행 일치","수정":[{"위치":"선지4","원문":"양도 당시 실지거래가액이 10억원인 1세대 1주택의 양도로 발생하는 양도차익 전부가 비과세된다.","수정문":"양도 당시 실지거래가액이 13억원인 1세대 1주택의 양도로 발생하는 양도차익 전부가 비과세된다.","근거":"소득세법 제89조 제1항 제3호","바뀐점":"고가주택 기준 실지거래가액 9억원 초과→12억원 초과"}],"정답변경사유":""}},{"i":"27회-2차-071","r":27,"y":2016,"c":2,"g":"","n":71,"q":"소득세법상 거주자의 양도소득과세표준의 신고 및 납부에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["2016년 3월 21일에 주택을 양도하고 잔금을 청산한 경우 2016년 6월 30일에 예정신고할 수 있다.","확정신고납부시 납부할 세액이 1천 6백만원인 경우 6백만원을 분납할 수 있다.","예정신고납부시 납부할 세액이 2천만원인 경우 분납할 수 없다.","양도차손이 발생한 경우 예정신고하지 아니한다.","예정신고하지 않은 거주자가 해당 과세기간의 과세표준이 없는 경우 확정신고하지 아니한다."],"a":[2],"p":28,"L":"세3-2","S":[],"m":"","f":null},{"i":"27회-2차-072","r":27,"y":2016,"c":2,"g":"","n":72,"q":"소득세법상 등기된 국내 부동산에 대한 양도소득과세표준의 세율에 관한 내용으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["1년 6개월 보유한 1주택: 100분의 40","2년 1개월 보유한 상가건물: 100분의 40","10개월 보유한 상가건물: 100분의 50","6개월 보유한 1주택: 100분의 30","1년 8개월 보유한 상가건물: 100분의 50"],"a":[3],"p":25,"L":"세3-2","S":[],"m":"","f":null},{"i":"27회-2차-073","r":27,"y":2016,"c":2,"g":"","n":73,"q":"소득세법상 양도소득세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["거주자가 국외 토지를 양도한 경우 양도일까지 계속해서 10년간 국내에 주소를 두었다면 양도소득과세표준을 예정신고하여야 한다.","비거주자가 국외 토지를 양도한 경우 양도소득세 납부의무가 있다.","거주자가 국내 상가건물을 양도한 경우 거주자의 주소지와 상가건물의 소재지가 다르다면 양도소득세 납세지는 상가건물의 소재지이다.","비거주자가 국내 주택을 양도한 경우 양도소득세 납세지는 비거주자의 국외 주소지이다.","거주자가 국외 주택을 양도한 경우 양도일까지 계속해서 5년간 국내에 주소를 두었다면 양도소득금액 계산 시 장기보유특별공제가 적용된다."],"a":[1],"p":28,"L":"세3-2","S":[],"m":"","f":null},{"i":"27회-2차-074","r":27,"y":2016,"c":2,"g":"","n":74,"q":"소득세법상 사업소득이 있는 거주자가 실지거래가액에 의해 부동산의 양도차익을 계산하는 경우 양도가액에서 공제할 자본적지출액 또는 양도비에 포함되지 않는 것은?(단, 자본적지출액에 대해서는 법령에 따른 증명서류가 수취·보관되어 있음)","b":null,"bs":"없음","img":[],"ch":["자산을 양도하기 위하여 직접 지출한 양도소득세 과세표준신고서 작성 비용","납부의무자와 양도자가 동일한 경우 재건축초과이익 환수에 관한 법률에 따른 재건축부담금","양도자산의 이용편의를 위하여 지출한 비용","양도자산의 취득 후 쟁송이 있는 경우 그 소유권을 확보하기 위하여 직접 소요된 소송비용으로서 그 지출한 연도의 각 사업소득금액계산시 필요경비에 산입된 금액","자산을 양도하기 위하여 직접 지출한 공증비용"],"a":[4],"p":28,"L":"세3-2","S":[],"m":"","f":null},{"i":"27회-2차-075","r":27,"y":2016,"c":2,"g":"","n":75,"q":"종합부동산세법상 납세의무 성립시기가 2016년인 종합부동산세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["과세기준일 현재 주택의 공시가격을 합산한 금액이 5억원인 개인은 납부할 주택분 종합부동산세액이 있다.","과세기준일은 7월 1일이다.","주택에 대한 과세표준이 5억원인 경우 적용될 세율은 1천분의 3이다.","관할세무서장은 납부하여야 할 세액이 1천만원을 초과하면 물납을 허가할 수 있다.","관할세무서장이 종합부동산세를 부과·징수하는 경우 납세고지서에 주택 및 토지로 구분한 과세표준과세액을 기재하여 납부기간 개시 5일전까지 발급하여야 한다."],"a":[5],"p":29,"L":"세3-1","S":[],"m":"","f":{"판정":"수정","요약":"종부세법 제7조 제1항이 '공시가격 합계 6억원 초과자'에서 '주택분 재산세 납세의무자'로 바뀌어 ① '5억원인 자는 납세의무가 있다'가 문언상 옳게 됨 → 공제금액(9억/12억, 제8조 제1항)으로 판단되는 세액 발생 여부로 바꿔 다시 틀리게 함. ⑤ 납부고지서 '발부'→'발급'(제16조 제2항). ②과세기준일 6월1일(제3조), ③3억~6억 구간 150만원+7/1000(제9조 제1항), ④물납 삭제(제19조 삭제) 여전히 틀림. '2016년' 연도 표기는 현행법으로 풀어도 결과 불변이라 그대로 둠","수정":[{"위치":"선지1","원문":"과세기준일 현재 주택의 공시가격을 합산한 금액이 5억원인 자는 납세의무가 있다.","수정문":"과세기준일 현재 주택의 공시가격을 합산한 금액이 5억원인 개인은 납부할 주택분 종합부동산세액이 있다.","근거":"종합부동산세법 제7조 제1항, 제8조 제1항","바뀐점":"납세의무자 요건이 공시가격 합계 기준에서 주택분 재산세 납세의무자로 변경, 공제금액 9억원(1세대1주택 12억원)"},{"위치":"선지5","원문":"관할세무서장이 종합부동산세를 부과·징수하는 경우 납부고지서에 주택 및 토지로 구분한 과세표준과세액을 기재하여 납부기간 개시 5일전까지 발부하여야 한다.","수정문":"관할세무서장이 종합부동산세를 부과·징수하는 경우 납부고지서에 주택 및 토지로 구분한 과세표준과세액을 기재하여 납부기간 개시 5일전까지 발급하여야 한다.","근거":"종합부동산세법 제16조 제2항","바뀐점":"발부→발급(2020.12.29 개정)"}],"정답변경사유":""}},{"i":"27회-2차-076","r":27,"y":2016,"c":2,"g":"","n":76,"q":"지방세법상 거주자의 국내자산 양도소득에 대한 지방소득세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["양도소득에 대한 개인 지방 소득세 과세표준은 종합소득 및 퇴직소득에 대한 개인 지방 소득세 과세표준과 구분하여 계산한다.","양도소득에 대한 개인지방소득세의 세액이 2천원인 경우에는 이를 징수하지 아니한다.","양도소득에 대한 개인지방소득세의 공제세액이 산출세액을 초과하는 경우 그 초과금액은 없는 것으로 한다.","양도소득에 대한 개인지방소득세 과세표준은 소득세법상 양도소득과세표준으로 하는 것이 원칙이다.","소득세법상 보유기간이 8개월인 조합원입주권의 세율은 양도소득에 대한 개인지방소득세 과세표준의 1천분의 70을 적용한다."],"a":[2],"p":25,"L":"세2-3","S":["세3-2"],"m":"","f":{"판정":"수정","요약":"조합원입주권 1년 미만 보유 개인지방소득세율이 1천분의 40→1천분의 70(지방세법 제103조의3 제1항 제3호)으로 올라 옳은 문장이던 ⑤를 70으로 수정. ②는 2천원 '미만'만 징수면제(제103조의60)라 여전히 틀림(정답 유지)","수정":[{"위치":"선지5","원문":"소득세법상 보유기간이 8개월인 조합원입주권의 세율은 양도소득에 대한 개인지방소득세 과세표준의 1천분의 40을 적용한다.","수정문":"소득세법상 보유기간이 8개월인 조합원입주권의 세율은 양도소득에 대한 개인지방소득세 과세표준의 1천분의 70을 적용한다.","근거":"지방세법 제103조의3 제1항 제3호","바뀐점":"1년 미만 보유 조합원입주권 세율 1천분의 40→1천분의 70"}],"정답변경사유":""}},{"i":"27회-2차-077","r":27,"y":2016,"c":2,"g":"","n":77,"q":"지방세법상 공유농지를 분할로 취득하는 경우 자기 소유지분에 대한 취득세 과세표준의 표준세율은?","b":null,"bs":"없음","img":[],"ch":["1천분의 23","1천분의 28","1천분의 30","1천분의 35","1천분의 40"],"a":[1],"p":29,"L":"세2-1","S":[],"m":"","f":null},{"i":"27회-2차-078","r":27,"y":2016,"c":2,"g":"","n":78,"q":"지방세법상 재산세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["과세기준일은 매년 7월 1일이다.","주택의 정기분 납부세액이 50만 원인 경우 세액의 2분의 1은 7월 16일부터 7월 31일까지, 나머지는 10월 16일부터 10월 31일까지를 납기로 한다.","토지의 정기분 납부세액이 9만 원인 경우 조례에 따라 납기를 7월 16일부터 7월 31일까지로 하여 한꺼번에 부과·징수할 수 있다.","과세 기준일 현재 공부상의 소유자가 매매로 소유권이 변동되었는데도 신고하지 아니하여 사실상의 소유자를 알 수 없는 경우 그 공부상의 소유자가 아닌 사용자에게 재산세 납부 의무가 있다.","지방자치단체의 장은 재산세의 납부세액이 250만원을 초과하는 경우 법령에 따라 납부할 세액의 일부를 납부기한이 지난 날부터 3개월 이내에 분할납부하게 할 수 있다."],"a":[5],"p":16,"L":"세2-3","S":[],"m":"","f":{"판정":"수정","요약":"재산세 분할납부 기준이 500만원 초과·45일 이내→250만원 초과·3개월 이내(지방세법 제118조)로 바뀌어 옳은 문장이던 ⑤를 현행으로 수정. ①6월1일(제114조), ②9.16~9.30(제115조), ③토지는 일괄징수 불가(제115조 제1항 제3호 단서는 주택만), ④공부상 소유자(제107조 제2항 제1호) 여전히 틀림","수정":[{"위치":"선지5","원문":"지방자치단체의 장은 재산세의 납부세액이 500만원을 초과하는 경우 법령에 따라 납부할 세액의 일부를 납부기한이 지난 날부터 45일 이내에 분납하게 할 수 있다.","수정문":"지방자치단체의 장은 재산세의 납부세액이 250만원을 초과하는 경우 법령에 따라 납부할 세액의 일부를 납부기한이 지난 날부터 3개월 이내에 분할납부하게 할 수 있다.","근거":"지방세법 제118조","바뀐점":"분납 기준 500만원 초과→250만원 초과, 기간 45일→3개월, 명칭 분납→분할납부"}],"정답변경사유":""}},{"i":"27회-2차-079","r":27,"y":2016,"c":2,"g":"","n":79,"q":"지방세법상 취득세의 납세의무에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산의 취득은 민법 등 관계 법령에 따른 등기를 하지 아니한 경우라도 사실상 취득하면 취득한 것으로 본다.","주택법에 따른 주택조합이 해당 조합원용으로 취득하는 조합주택용부동산(조합원에게 귀속되지 아니하는 부동산은 제외)은 그 조합원이 취득한 것으로 본다.","직계비속이 직계존속의 부동산을 매매로 취득하는 때에 해당 직계비속의 다른 재산으로 그 대가를 지급한 사실이 입증되는 경우 유상으로 취득한 것으로 본다.","직계비속이 권리의 이전에 등기가 필요한 직계존속의 부동산을 서로 교환한 경우 무상으로 취득한 것으로 본다.","직계비속이 공매를 통하여 직계존속의 부동산을 취득하는 경우 유상으로 취득한 것으로 본다."],"a":[4],"p":30,"L":"세2-1","S":[],"m":"","f":null},{"i":"27회-2차-080","r":27,"y":2016,"c":2,"g":"","n":80,"q":"지방세법상 취득세 및 등록면허세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["취득세 과세물건을 취득한 후 중과세 세율 적용 대상이 되었을 경우 60일 이내에 산출 세액에서 이미 납부한 세액(가산세 포함)을 공제하여 신고·납부하여야 한다.","취득세 과세물건을 취득한 자가 재산권의 취득에 관한사항을 등기하는 경우 등기한 후 30일 내에 취득세를 신고·납부하여야 한다.","부동산 거래신고 등에 관한 법률에 따른 신고서를 제출하여 같은 법에 따라 검증이 이루어진 취득에 대하여는 취득세의 과세표준을 시가표준액으로 한다.","부동산 가압류에 대한 등록면허세의 세율은 부동산가액의 1천 분의 2로 한다.","등록하려는 자가 신고의무를 다하지 아니하고 등록면허세 산출 세액을 등록하기 전까지(신고기한이 있는 경우 신고기한까지) 납부하였을 때에는 신고·납부한 것으로 본다."],"a":[5],"p":28,"L":"세2-1","S":["세2-2"],"m":"","f":null},{"i":"28회-2차-105","r":28,"y":2017,"c":2,"g":"2교시","n":25,"q":"지방세법상 재산세의 물납에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["「지방세법」 상 물납의 신청 및 허가 요건을 충족하고 재산세(재산세 도시지역분 포함)의 납부세액이 1천만원 초과하는 경우 물납이 가능하다.","서울특별시 강남구와 경기도 성남시에 부동산을 소유하고 있는 자의 성남시 소재 부동산에 대하여 부과된 재산세의 물납은 성남시 내에 소재하는 부동산만 가능하다.","물납허가를 받은 부동산을 행정안전부령으로 정하는 바에 따라 물납하였을 때에는 납부기한 내에 납부한 것으로 본다.","물납하려는 자는 행정안전부령으로 정하는 서류를 갖추어 그 납부기한 10일 전까지 납세지를 관할하는 시장·군수·구청장에게 신청하여야 한다.","물납 신청 후 불허가 통지를 받은 경우에 해당 시·군·구의 다른 부동산으로의 변경신청은 허용되지 않으며 금전으로만 납부하여야 한다."],"a":[5],"p":38,"L":"세2-3","S":[],"m":"","f":null},{"i":"28회-2차-106","r":28,"y":2017,"c":2,"g":"2교시","n":26,"q":"지방세법상 재산세의 과세기준일 현재 납세의무자에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["공유재산인 경우 그 지분에 해당하는 부분(지분의 표시가 없는 경우에는 지분이 균등한 것으로 봄)에 대해서는 그 지분권자를 납세의무자로 본다.","소유권의 귀속이 분명하지 아니하여 사실상의 소유자를 확인할 수 없는 경우에는 그 사용자가 납부할 의무가 있다.","지방자치단체와 재산세 과세대상 재산을 연부로 매매계약을 체결하고 그 재산의 사용권을 무상으로 받은 경우에는 그 매수계약자를 납세의무자로 본다.","공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 때에는 공부상 소유자를 납세의무자로 본다.","상속이 개시된 재산으로서 상속등기가 이행되지 아니하고 사실상의 소유자를 신고하지 아니하였을 때에는 공동상속인 각자가 받았거나 받을 재산에 따라 납부할 의무를 진다."],"a":[5],"p":37,"L":"세2-3","S":[],"m":"","f":null},{"i":"28회-2차-107","r":28,"y":2017,"c":2,"g":"2교시","n":27,"q":"종합부동산세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["종합부동산세는 부과·징수가 원칙이며 납세의무자의 선택에 의하여 신고납부도 가능하다.","관할세무서장이 종합부동산세를 징수하고자 하는 때에는 납부고지서에 주택 및 토지로 구분한 과세표준과 세액을 기재하여 납부기간 개시 5일 전까지 발급하여야 한다.","주택에 대한 세부담 상한의 기준이 되는 직전 연도에 해당 주택에 부과된 주택에 대한 총세액상당액은 납세의무자가 해당 연도의 과세표준합산주택을 직전 연도 과세기준일에 실제로 소유하였는지의 여부를 불문하고 직전 연도 과세기준일 현재 소유한 것으로 보아 계산한다.","주택분 종합부동산세액에서 공제되는 재산세액은 재산세 표준세율의 100분의 50의 범위에서 가감된 세율이 적용된 경우에는 그 세율이 적용되기 전의 세액으로 하고, 재산세 세부담 상한을 적용받은 경우에는 그 상한을 적용받기 전의 세액으로 한다.","과세기준일 현재 토지분 재산세의 납세의무자로서 국내에 소재하는 별도합산과세대상 토지의 공시가격을 합한 금액이 80억원을 초과하는 자는 토지에 대한 종합부동산세의 납세의무자이다."],"a":[4],"p":32,"L":"세3-1","S":[],"m":"","f":{"판정":"수정","요약":"④는 가감조정·세부담상한 적용 '후' 세액을 공제(종부세법 제9조 제3항)하므로 여전히 틀림(정답 유지). ②의 '납세고지서…발부'를 현행 용어 '납부고지서…발급'(제16조 제2항)으로 수정. ③ 시행령 제5조 제2항, ⑤ 제12조 제1항 제2호 80억원 현행 일치","수정":[{"위치":"선지2","원문":"관할세무서장이 종합부동산세를 징수하고자 하는 때에는 납세고지서에 주택 및 토지로 구분한 과세표준과 세액을 기재하여 납부기간 개시 5일 전까지 발부하여야 한다.","수정문":"관할세무서장이 종합부동산세를 징수하고자 하는 때에는 납부고지서에 주택 및 토지로 구분한 과세표준과 세액을 기재하여 납부기간 개시 5일 전까지 발급하여야 한다.","근거":"종합부동산세법 제16조 제2항","바뀐점":"납세고지서→납부고지서, 발부→발급(2020.12.29 개정)"}],"정답변경사유":""}},{"i":"28회-2차-108","r":28,"y":2017,"c":2,"g":"2교시","n":28,"q":"지방세법상 재산세의 비과세 대상이 아닌 것은? (단, 아래의 답항별로 주어진 자료 외의 비과세요건은 충족된 것으로 가정함)","b":null,"bs":"없음","img":[],"ch":["임시로 사용하기 위하여 건축된 건축물로서 재산세 과세기준일 현재 1년 미만의 것","재산세를 부과하는 해당 연도에 철거하기로 계획이 확정되어 재산세 과세기준일 현재 행정관청으로부터 철거명령을 받은 주택과 그 부속토지인 대지","농업용 구거와 자연유수의 배수처리에 제공하는 구거","「군사기지 및 군사시설 보호법」 에 따른 군사기지 및 군사시설 보호구역 중 통제보호구역에 있는 토지(전·답·과수원 및 대지는 제외)","「도로법」 에 따른 도로와 그밖에 일반인의 자유로운 통행을 위하여 제공할 목적으로 개설한 사설도로(「건축법 시행령」 제 80조의 2에 따른 대지 안의 공지는 제외)"],"a":[2],"p":30,"L":"세2-3","S":[],"m":"","f":null},{"i":"28회-2차-109","r":28,"y":2017,"c":2,"g":"2교시","n":29,"q":"소득세법상 거주자의 양도소득세 과세대상에 관한 설명으로 틀린 것은? (단, 양도자산은 국내자산임)","b":null,"bs":"없음","img":[],"ch":["무상이전에 따라 자산의 소유권이 변경된 경우에는 과세대상이 되지 아니한다.","부동산에 관한 권리 중 지상권의 양도는 과세대상이다.","사업용 건물과 함께 양도하는 영업권은 과세대상이다.","법인의 주식을 소유하는 것만으로 시설물을 배타적으로 이용하게 되는 경우 그 주식의 양도는 과세대상이다.","등기되지 않은 부동산임차권의 양도는 과세대상이다."],"a":[5],"p":34,"L":"세3-2","S":[],"m":"","f":null},{"i":"28회-2차-110","r":28,"y":2017,"c":2,"g":"2교시","n":30,"q":"다음은 거주자가 국내소재 1세대 1주택을 양도한 내용이다. 양도차익은 얼마인가?","b":"(1) 취득 및 양도 내역(등기됨) 가 액 구분 거래일자 실지거래가액 기준시가 양도 15 억원 5 억원 2017. 3. 2. 취득 확인 불가능 3 억 5천만원 2013. 2. 4.\n(2) 자본적 지출 및 양도비용은 1천 7백만원이다.\n(3) 주어진 자료 외는 고려하지 않는다.","bs":"글자","img":[],"ch":["85,800,000원","86,600,000원","87,900,000원","433,000,000원","439,500,000원"],"a":[3],"p":17,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"고가주택 기준 9억→12억원(소득세법 제89조 제1항 제3호, 시행령 제160조)으로 양도가액 10억원 1세대1주택은 전액 비과세가 되어 계산 불성립 → 양도 실지거래가액을 15억원으로 조정. 재계산: 환산취득가액 15억×3.5억/5억=10.5억, 개산공제 3.5억×3%=1,050만원(시행령 제163조 제6항), 필요경비 10억6,050만원(자본적지출·양도비 1,700만원보다 커서 소득세법 제97조 제2항 제2호 본문 적용), 양도차익 4억3,950만원 × (15억-12억)/15억 = 87,900,000원. 선지는 원 문항의 오답 구조(자본적지출 사용, 이중공제, 안분 전 금액)를 그대로 옮김. 거래일자는 결과에 영향 없어 그대로 둠","수정":[{"위치":"보기","원문":"(1) 취득 및 양도 내역(등기됨) 가 액 구분 거래일자 실지거래가액 기준시가 양도 10 억원 5 억원 2017. 3. 2. 취득 확인 불가능 3 억 5천만원 2013. 2. 4.","수정문":"(1) 취득 및 양도 내역(등기됨) 가 액 구분 거래일자 실지거래가액 기준시가 양도 15 억원 5 억원 2017. 3. 2. 취득 확인 불가능 3 억 5천만원 2013. 2. 4.","근거":"소득세법 제89조 제1항 제3호, 제97조 제2항 제2호, 소득세법 시행령 제160조 제1항, 제163조 제6항, 제176조의2 제2항","바뀐점":"고가주택 기준 12억원 반영해 양도 실지거래가액 10억→15억원"},{"위치":"선지1","원문":"27,900,000원","수정문":"85,800,000원","근거":"계산 조정","바뀐점":"27,900,000원→85,800,000원(오답: (15억-10.5억-1,050만-1,050만)×0.2)"},{"위치":"선지2","원문":"28,300,000원","수정문":"86,600,000원","근거":"계산 조정","바뀐점":"28,300,000원→86,600,000원(오답: 자본적지출 1,700만원 공제 후 안분)"},{"위치":"선지3","원문":"28,950,000원","수정문":"87,900,000원","근거":"소득세법 시행령 제160조 제1항 제1호","바뀐점":"28,950,000원→87,900,000원(현행 정답)"},{"위치":"선지4","원문":"283,000,000원","수정문":"433,000,000원","근거":"계산 조정","바뀐점":"283,000,000원→433,000,000원(오답: 자본적지출 사용·안분 전)"},{"위치":"선지5","원문":"289,500,000원","수정문":"439,500,000원","근거":"계산 조정","바뀐점":"289,500,000원→439,500,000원(오답: 안분 전 전체 양도차익)"}],"정답변경사유":""}},{"i":"28회-2차-111","r":28,"y":2017,"c":2,"g":"2교시","n":31,"q":"소득세법상 양도에 해당하는 것은? (단, 거주자의 국내자산으로 가정함)","b":null,"bs":"없음","img":[],"ch":["「도시개발법」 이나 그 밖의 법률에 따른 환지처분으로 지목이 변경되는 경우","부담부증여 시 그 증여가액 중 채무액에 해당하는 부분을 제외한 부분","「소득세법 시행령」 제 151조 제1항에 따른 양도담보계약을 체결한 후 채무불이행으로 인하여 당해 자산을 변제에 충당한 때","매매원인 무효의 소에 의하여 그 매매사실이 원인무효로 판시되어 소유권이 환원되는 경우","본인 소유 자산을 경매로 인하여 본인이 재취득한 경우"],"a":[3],"p":35,"L":"세3-2","S":[],"m":"","f":null},{"i":"28회-2차-112","r":28,"y":2017,"c":2,"g":"2교시","n":32,"q":"소득세법상 거주자의 양도소득세에 관한 설명으로 틀린 것은? (단, 국내소재 부동산의 양도임)","b":null,"bs":"없음","img":[],"ch":["같은 해에 여러 개의 자산(모두 등기됨)을 양도한 경우 양도소득기본공제는 해당 과세기간에 먼저 양도한 자산의 양도소득금액에서부터 순서대로 공제한다. 단, 감면 소득금액은 없다.","「소득세법」 제104조 제3항에 따른 미등기 양도자산에 대하여는 장기보유특별공제를 적용하지 아니한다.","「소득세법」 제97조의 2 제1항에 따라 이월과세를 적용받는 경우 장기보유특별공제의 보유기간은 증여자가 해당 자산을 취득한 날부터 기산한다.","A법인과 특수관계에 있는 주주가 시가 3억원(「법인세법」 제52조에 따른 시가임)의 토지를 A법인에게 5억원에 양도한 경우 양도가액은 3억원으로 본다. 단, A법인은 이 거래에 대하여 세법에 따른 처리를 적절하게 하였다.","특수관계인 간의 거래가 아닌 경우로서 취득가액인 실지거래가액을 인정 또는 확인할 수 없어 그 가액을 추계결정 또는 경정하는 경우에는 매매사례가액, 감정가액, 기준시가의 순서에 따라 적용한 가액에 의한다."],"a":[5],"p":31,"L":"세3-2","S":[],"m":"","f":null},{"i":"28회-2차-113","r":28,"y":2017,"c":2,"g":"2교시","n":33,"q":"소득세법상 거주자가 국내소재 부동산 등을 임대하여 발생하는 소득에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」에 따른 공익사업과 관련된 지상권의 대여로 인한 소득은 부동산임대업에서 발생한 소득에서 제외한다.","부동산임대업에서 발생한 소득은 사업소득에 해당한다.","주거용 건물 임대업에서 발생한 결손금은 종합소득 과세표준을 계산할 때 공제한다.","부부가 합산하여 1주택(기준시가 12억원 이하)만을 보유한 상태에서 그 주택을 임대하고 연간 1,800만원의 임대료를 받았을 경우 주택임대에 따른 과세소득은 없다.","임대보증금의 간주임대료를 계산하는 과정에서 금융수익을 차감할 때 그 금융수익은 수입이자와 할인료, 수입배당금, 유가증권처분이익으로 한다."],"a":[5],"p":20,"L":"세3-3","S":[],"m":"","f":{"판정":"수정","요약":"④: 2천만원 이하 주택임대소득 비과세가 2018년 귀속까지만(소득세법 제12조 제2호 나목) 적용되고 부부 주택 수는 합산(시행령 제8조의2 제3항 제4호)해 2주택이면 과세 → 옳은 문장이던 ④가 틀리게 되어 1주택 비과세 사례로 수정. ①: 부동산업 소득에서 빠지는 것은 공익사업 관련 지상권 대여만(제19조 제1항 제12호 단서, 제21조 제1항 제9호)이라 패킷 문언대로면 틀린 문장 → 공익사업 한정어 보완(원 시험지 문언 대조 필요). ⑤ 금융수익은 수입이자·할인료·배당금만(시행령 제53조 제3항)이라 여전히 틀림","수정":[{"위치":"선지1","원문":"지상권의 대여로 인한 소득은 부동산임대업에서 발생한 소득에서 제외한다.","수정문":"「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」에 따른 공익사업과 관련된 지상권의 대여로 인한 소득은 부동산임대업에서 발생한 소득에서 제외한다.","근거":"소득세법 제19조 제1항 제12호 단서, 제21조 제1항 제9호","바뀐점":"공익사업 관련 지역권·지상권 대여소득만 기타소득으로 제외됨을 문언에 반영"},{"위치":"선지4","원문":"부부가 각각 주택을 1채씩 보유한 상태에서 그 중 1주택을 임대하고 연간 1,800만원의 임대료를 받았을 경우 주택임대에 따른 과세소득은 없다.","수정문":"부부가 합산하여 1주택(기준시가 12억원 이하)만을 보유한 상태에서 그 주택을 임대하고 연간 1,800만원의 임대료를 받았을 경우 주택임대에 따른 과세소득은 없다.","근거":"소득세법 제12조 제2호 나목, 소득세법 시행령 제8조의2 제3항 제4호","바뀐점":"총수입금액 2천만원 이하 비과세 종료(2018년 귀속까지), 이후 분리과세(제64조의2) — 1주택 비과세만 남음"}],"정답변경사유":""}},{"i":"28회-2차-114","r":28,"y":2017,"c":2,"g":"2교시","n":34,"q":"소득세법상 거주자가 국내자산을 양도한 경우 양도소득의 필요경비에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["취득가액을 실지거래가액에 의하는 경우 당초 약정에 의한 지급기일의 지연으로 인하여 추가로 발생하는 이자상당액은 취득원가에 포함하지 아니한다.","취득가액을 실지거래가액에 의하는 경우 자본적지출액도 실지로 지출된 가액에 의하므로 「소득세법」 제160조의 2 제2항에 따른 증명서류를 수취·보관하지 않고 금융거래 증명서류로도 실제 지출사실이 확인되지 않더라도 지출사실이 입증되면 이를 필요경비로 인정한다.","「소득세법」 제 97조 제3항에 따른 취득가액을 계산할 때 감가상각비를 공제하는 것은 취득가액을 실지거래가액으로 하는 경우에만 적용하므로 취득가액을 환산가액으로 하는 때에는 적용하지 아니한다.","토지를 취득함에 있어서 부수적으로 매입한 채권을 만기 전에 양도함으로써 발생하는 매각차손은 채권의 매매상대방과 관계없이 전액 양도비용으로 인정된다.","취득세는 납부영수증이 없으면 필요경비로 인정되지 아니한다."],"a":[1],"p":26,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"자본적지출·양도비는 증명서류 수취·보관 외에 '금융거래 증명서류로 실제 지출사실 확인'되는 경우도 인정(소득세법 시행령 제163조 제3항, 2018.2.13 개정)되어 ② '지출사실이 입증되면 인정'이 옳은 문장으로 읽힐 수 있음 → 금융거래 증명으로도 확인 안 되는 경우로 한정해 다시 틀리게 함. ①지급기일 지연 이자 불포함(시행령 제163조 제1항 제3호 단서, 정답 유지), ③감가상각비 공제는 환산가액에도 적용(법 제97조 제3항), ④금융기관 외 양도 시 한도(시행령 제163조 제5항 제2호) 여전히 틀림","수정":[{"위치":"선지2","원문":"취득가액을 실지거래가액에 의하는 경우 자본적지출액도 실지로 지출된 가액에 의하므로 「소득세법」 제160조의 2 제2항에 따른 증명서류를 수취·보관하지 않더라도 지출사실이 입증되면 이를 필요경비로 인정한다.","수정문":"취득가액을 실지거래가액에 의하는 경우 자본적지출액도 실지로 지출된 가액에 의하므로 「소득세법」 제160조의 2 제2항에 따른 증명서류를 수취·보관하지 않고 금융거래 증명서류로도 실제 지출사실이 확인되지 않더라도 지출사실이 입증되면 이를 필요경비로 인정한다.","근거":"소득세법 시행령 제163조 제3항","바뀐점":"필요경비 인정요건에 금융거래 증명서류에 의한 지출사실 확인 추가"}],"정답변경사유":""}},{"i":"28회-2차-115","r":28,"y":2017,"c":2,"g":"2교시","n":35,"q":"지방세법상 부동산등기에 대한 등록면허세의 표준세율로 틀린 것은? (단, 표준세율을 적용하여 산출한 세액이 부동산등기에 대한 그 밖의 등기 또는 등록세율보다 크다고 가정함)","b":null,"bs":"없음","img":[],"ch":["전세권 설정등기: 전세금액의 1천분의 2","상속으로 인한 소유권 이전등기: 부동산가액의 1천분의 8","지역권 설정 및 이전등기: 요역지 가액의 1천분의 2","임차권 설정 및 이전등기: 임차보증금의 1천분의 2","저당권 설정 및 이전등기: 채권금액의 1천분의 2"],"a":[4],"p":34,"L":"세2-2","S":[],"m":"","f":null},{"i":"28회-2차-116","r":28,"y":2017,"c":2,"g":"2교시","n":36,"q":"지방세법상 취득의 시기 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["연부로 취득하는 것(취득가액의 총액이 50만원 이하인 것은 제외)은 그 사실상의 연부금 지급일을 취득일로 본다. 단, 취득일 전에 등기 또는 등록한 경우에는 그 등기일 또는 등록일에 취득한 것으로 본다.","관계법령에 따라 매립·간척 등으로 토지를 원시취득하는 경우로서 공사준공인가일 전에 사실상 사용하는 경우에는 그 사실상 사용일을 취득일로 본다.","「주택법」 제11조에 따른 주택조합이 주택건설사업을 하면서 조합원으로부터 최득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 「주택법」 제49조에 따른 사용검사를 받은 날에 그 토지를 취득한 것으로 본다.","「도시 및 주거환경정비법」 제35조 제3항에 따른 재건축조합이 재건축사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 「도시 및 주거환경정비법」 제86조 제2항에 따른 소유권이전 고시일에 그 토지를 취득한 것으로 본다.","토지의 지목변경에 따른 취득은 토지의 지목이 사실상 변경된 날과 공부상 변경된 날 중 빠른 날을 취득일로 본다. 다만, 토지의 지목변경일 이전에 사용하는 부분에 대해서는 그 사실상의 사용일을 취득일로 본다."],"a":[4],"p":31,"L":"세2-1","S":[],"m":"","f":{"판정":"수정","요약":"재건축조합 비조합원용 토지 취득시기가 '소유권이전 고시일의 다음 날'(지방세법 시행령 제20조 제7항)이라 ④ 여전히 틀림(정답 유지). 다만 인용 조문·명칭이 옛 도시정비법(제16조 제2항 주택재건축조합, 제54조 제2항)이라 현행(제35조 제3항 재건축조합, 제86조 제2항)으로 교체. ①(제20조 제5항·제14항, 면세점 50만원 제17조), ②(제8항), ③(제7항), ⑤(제10항) 현행 일치","수정":[{"위치":"선지4","원문":"「도시 및 주거환경정비법」 제16조 제2항에 따른 주택재건축조합이 주택재건축사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 「도시 및 주거환경정비법」 제54조 제2항에 따른 소유권이전 고시일에 그 토지를 취득한 것으로 본다.","수정문":"「도시 및 주거환경정비법」 제35조 제3항에 따른 재건축조합이 재건축사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 「도시 및 주거환경정비법」 제86조 제2항에 따른 소유권이전 고시일에 그 토지를 취득한 것으로 본다.","근거":"지방세법 시행령 제20조 제7항, 도시 및 주거환경정비법 제35조 제3항·제86조 제2항","바뀐점":"도시정비법 전부개정에 따른 조문 번호·명칭(주택재건축조합→재건축조합) 교체"}],"정답변경사유":""}},{"i":"28회-2차-117","r":28,"y":2017,"c":2,"g":"2교시","n":37,"q":"지방세기본법상 지방자치단체의 징수금을 납부할 의무가 소멸되는 것은 모두 몇 개 인가?","b":"ㄱ. 납부ㆍ충당되었을 때\nㄴ. 지방세징수권의 소멸시효가 완성되었을 때\nㄷ. 법인이 합병한 때\nㄹ. 지방세부과의 제척기간이 만료되었을 때\nㅁ. 납세의무자의 사망으로 상속이 개시된 때","bs":"글자","img":[],"ch":["1개","2개","3개","4개","5개"],"a":[3],"p":42,"L":"세1-1","S":[],"m":"","f":null},{"i":"28회-2차-118","r":28,"y":2017,"c":2,"g":"2교시","n":38,"q":"지방세법상 등록면허세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["같은 등록에 관계되는 재산이 둘 이상의 지방자치단체에 걸쳐 있어 등록면허세를 지방자치단체별로 부과할 수 없을 때에는 등록관청 소재지를 납세지로 한다.","「여신전문금융업법」 제2조 제12호에 따른 할부금융업을 영위하기 위하여 대도시에서 법인을 설립함에 따른 등기를 할 때에는 그 세율을 해당 표준세율의 100분의 300으로 한다. 단, 그 등기일로부터 2년 이내에 업종변경이나 업종추가는 없다.","무덤과 이에 접속된 부속시설물의 부지로 사용되는 토지로서 지적공부상 지목이 묘지인 토지에 관한 등기에 대하여는 등록면허세를 부과하지 아니한다.","재산권 기타 권리의 설정·변경 또는 소멸에 관한 사항을 공부에 등기 또는 등록을 받는 등기·등록부상에 기재된 명의자는 등록면허세를 납부할 의무를 진다.","지방자치단체의 장은 조례로 정하는 바에 따라 등록면허세의 세율을 부동산 등기에 대한 표준세율의 100분의 50의 범위에서 가감할 수 있다."],"a":[2],"p":33,"L":"세2-2","S":[],"m":"","f":null},{"i":"28회-2차-119","r":28,"y":2017,"c":2,"g":"2교시","n":39,"q":"지방세법상 취득세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지방자치단체에 기부채납을 조건으로 부동산을 취득하는 경우라도 그 반대급부로 기부채납 대상물의 무상사용권을 제공받는 때에는 그 해당 부분에 대해서는 취득세를 부과한다.","상속(피상속인이 상속인에게 한 유증 및 포괄유증과 신탁재산의 상속 포함)으로 인하여 취득하는 경우에는 상속인 각자가 상속받는 취득물건(지분을 취득하는 경우에는 그 지분에 해당하는 취득물건을 말함)을 취득한 것으로 본다.","국가로부터 유상취득하는 경우에는 신고 또는 신고가액의 표시가 없거나 그 신고가액이 시가표준액보다 적을 때에도 사실상의 취득가격 또는 연부금액을 과세표준으로 한다.","무상승계취득한 취득물건을 취득일에 등기·등록한 후 화해조서·인낙조서에 의하여 취득일이 속하는 달의 말일부터 3개월 이내에 계약이 해제된 사실을 입증하는 경우에는 취득한 것으로 보지 아니한다.","「주택법」 제2조 제3호에 따른 공동주택의 개수(「건축법」 제2조 제1항 제9호에 따른 대수선은 제외함)로 인한 취득 중 개수로 인한 취득 당시 「지방세법」 제4조에 따른 주택의 시가표준액이 9억원 이하인 주택과 관련된 개수로 인한 취득에 대해서는 취득세를 부과하지 아니한다."],"a":[4],"p":28,"L":"세2-1","S":[],"m":"","f":{"판정":"수정","요약":"무상취득 계약해제 입증기간이 60일→'취득일이 속하는 달의 말일부터 3개월'(지방세법 시행령 제20조 제1항)로 바뀜. ④는 '등기·등록한 후'라 여전히 틀린 문장이지만 기간 수치만 현행으로 교체. ①제9조 제2항 제2호, ②제7조 제7항, ③유상승계는 사실상취득가격(제10조의3 제1항), ⑤제9조 제6항·시행령 제12조의2 9억원 현행 일치","수정":[{"위치":"선지4","원문":"무상승계취득한 취득물건을 취득일에 등기·등록한 후 화해조서·인낙조서에 의하여 취득일로부터 60일 이내에 계약이 해제된 사실을 입증하는 경우에는 취득한 것으로 보지 아니한다.","수정문":"무상승계취득한 취득물건을 취득일에 등기·등록한 후 화해조서·인낙조서에 의하여 취득일이 속하는 달의 말일부터 3개월 이내에 계약이 해제된 사실을 입증하는 경우에는 취득한 것으로 보지 아니한다.","근거":"지방세법 시행령 제20조 제1항 제1호","바뀐점":"무상취득 해제 입증기간 60일→취득일이 속하는 달의 말일부터 3개월"}],"정답변경사유":""}},{"i":"28회-2차-120","r":28,"y":2017,"c":2,"g":"2교시","n":40,"q":"지방세법상 취득세 표준세율에서 중과기준세율을 뺀 세율로 산출한 금액을 그 세액으로 하는 것으로만 모두 묶은 것은? (단, 취득물건은 「지방세법」 제11조 제1항 제8호에 따른 주택 외의 부동산이며 취득세 중과대상이 아님)","b":"ㄱ. 환매등기를 병행하는 부동산의 매매로서 환매기간 내에 매도자가 환매한 경우의 그 매도자와 매수자의 취득\nㄴ. 존속기간이 1년을 초과하는 임시건축물의 취득\nㄷ. 「민법」제839조의 2에 따라 이혼시 재산분할로 인한 취득\nㄹ. 등기부등본상 본인 지분을 초과하지 않는 공유물의 분할로 인한 취득","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄴ, ㄹ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄱ, ㄷ, ㄹ"],"a":[5],"p":31,"L":"세2-1","S":[],"m":"","f":null},{"i":"29회-2차-105","r":29,"y":2018,"c":2,"g":"2교시","n":25,"q":"국세기본법 및 지방세기본법상 조세채권과 일반채권의 관계에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["납세담보물 매각 시 압류에 관계되는 조세채권은 담보 있는 조세채권보다 우선한다.","재산의 매각대금 배분 시 당해 재산에 부과된 종합부동산세는 당해 재산에 설정된 저당권에 따라 담보된 채권보다 우선한다.","취득세 신고서를 납세지 관할 지방자치단체장에게 제출한 날 전에 저당권 설정 등기 사실이 증명되는 재산을 매각하여 그 매각금액에서 취득세를 징수하는 경우, 저당권에 따라 담보된 채권은 취득세에 우선한다.","강제집행으로 부동산을 매각할 때 그 매각금액 중에 국세를 징수하는 경우, 강제집행 비용은 국세에 우선한다.","재산의 매각대금 배분 시 당해 재산에 부과된 재산세는 당해 재산에 설정된 저당권에 따라 담보된 채권보다 우선한다."],"a":[1],"p":24,"L":"세1-1","S":[],"m":"","f":{"판정":"수정","요약":"①은 담보 있는 국세가 우선(국세기본법 제37조)이라 여전히 틀림(정답 유지). ②: 확정일자 임차권·주거용 건물 전세권 채권은 법정기일이 늦은 당해세(종부세)의 배분순서에 대신 변제될 수 있게(제35조 제7항, 2022.12.31 개정) 되어 '전세권 채권보다 우선'이 항상 참이 아님 → 해당 특례가 없는 저당권으로 바꿔 옳은 문장 유지. ③지방세기본법 제71조 제1항 제3호 가목, ④국세기본법 제35조 제1항 제2호, ⑤지방세기본법 제71조 제5항 제1호 현행 일치","수정":[{"위치":"선지2","원문":"재산의 매각대금 배분 시 당해 재산에 부과된 종합부동산세는 당해 재산에 설정된 전세권에 따라 담보된 채권보다 우선한다.","수정문":"재산의 매각대금 배분 시 당해 재산에 부과된 종합부동산세는 당해 재산에 설정된 저당권에 따라 담보된 채권보다 우선한다.","근거":"국세기본법 제35조 제3항·제7항","바뀐점":"주거용 건물 전세권·확정일자 임차권 보증금채권의 당해세 대신변제 특례 신설"}],"정답변경사유":""}},{"i":"29회-2차-106","r":29,"y":2018,"c":2,"g":"2교시","n":26,"q":"거주자 甲은 A주택을 3년간 소유하며 직접 거주하고 있다. 甲이 A주택에 대하여 납부하게 되는 재산세와 종합부동산세에 관한 설명으로 틀린 것은? (단, 甲은 종합부동산세법상 납세의무자로서 만 61세이며 1세대 1주택자라 가정함)","b":null,"bs":"없음","img":[],"ch":["재산세 및 종합부동산세의 과세기준일은 매년 6월 1일이다.","甲의 고령자 세액공제액은 종합부동산세법에 따라 산출된 세액에 100분의 20을 곱한 금액으로 한다.","재산세 납부세액이 600만원인 경우, 100만원은 납부기한이 지난 날부터 3개월 이내에 분납할 수 있다.","재산세 산출세액은 지방세법령에 따라 계산한 직전 연도 해당 재산에 대한 재산세액 상당액의 100분의 150에 해당하는 금액을 한도로 한다.","만약 甲이 A주택을 「신탁법」에 따라 수탁자 명의로 신탁등기하게 하는 경우로서 A주택이 위탁자별로 구분된 재산이라면, 위탁자를 재산세 납세의무자로 본다."],"a":[4],"p":20,"L":"세2-3","S":["세3-1"],"m":"","f":{"판정":"수정","요약":"현행 기준 ②고령자공제 만60~65세 100분의 20(종부세법 제9조 제6항), ③분할납부 3개월 이내(지방세법 제118조), ⑤신탁재산 재산세 납세의무자는 위탁자(제107조 제2항 제5호)로 바뀌어 옳은 문장이던 ②③⑤를 현행으로 수정. ④는 주택에 재산세 세부담상한이 적용되지 않아(제122조 단서) 여전히 틀림(정답 유지). 발문의 '2918년 귀속'(오기) 연도와 '개정전 문제' 안내문구는 현행 기준으로 수정되어 불필요하므로 삭제","수정":[{"위치":"발문","원문":"거주자 甲은 A주택을 3년간 소유하며 직접 거주하고 있다. 甲이 A주택에 대하여 납부하게 되는 2918년 귀속 재산세와 종합부동산세에 관한 설명으로 틀린 것은? (단, 甲은 종합부동산세법상 납세의무자로서 만 61세이며 1세대 1주택자라 가정함)","수정문":"거주자 甲은 A주택을 3년간 소유하며 직접 거주하고 있다. 甲이 A주택에 대하여 납부하게 되는 재산세와 종합부동산세에 관한 설명으로 틀린 것은? (단, 甲은 종합부동산세법상 납세의무자로서 만 61세이며 1세대 1주택자라 가정함)","근거":"종합부동산세법 제9조, 지방세법 제107조·제118조·제122조","바뀐점":"연도 표기(오기 2918) 및 개정전 안내 삭제 — 현행 법령 기준 문항으로 전환"},{"위치":"선지2","원문":"甲의 고령자 세액공제액은 종합부동산세법에 따라 산출된 세액에 100분의 10을 곱한 금액으로 한다.","수정문":"甲의 고령자 세액공제액은 종합부동산세법에 따라 산출된 세액에 100분의 20을 곱한 금액으로 한다.","근거":"종합부동산세법 제9조 제6항","바뀐점":"만60세 이상 65세 미만 공제율 100분의 10→100분의 20"},{"위치":"선지3","원문":"재산세 납부세액이 600만원인 겨우, 100만원은 납부기한이 지난 날부터 2개월 이내에 분납할 수 있다.","수정문":"재산세 납부세액이 600만원인 겨우, 100만원은 납부기한이 지난 날부터 3개월 이내에 분납할 수 있다.","근거":"지방세법 제118조, 지방세법 시행령 제116조 제1항 제2호","바뀐점":"분할납부 기간 2개월→3개월"},{"위치":"선지5","원문":"만약 甲이 A주택을 「신탁법」에 따라 수탁자 명의로 신탁등기하게 하는 경우로서 A주택이 위탁자별로 구분된 재산이라면, 수탁자를 재산세 납세의무자로 본다.","수정문":"만약 甲이 A주택을 「신탁법」에 따라 수탁자 명의로 신탁등기하게 하는 경우로서 A주택이 위탁자별로 구분된 재산이라면, 위탁자를 재산세 납세의무자로 본다.","근거":"지방세법 제107조 제2항 제5호","바뀐점":"신탁재산 재산세 납세의무자 수탁자→위탁자(2020.12.29 개정)"}],"정답변경사유":""}},{"i":"29회-2차-107","r":29,"y":2018,"c":2,"g":"2교시","n":27,"q":"2018년 귀속 종합부동산세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["과세대상 토지가 매매로 유상이전 되는 경우로서 매매계약서 작성일이 2018년 6월 1일이고, 잔금지급 및 소유권이전등기일이 2018년 6월 29일인 경우, 종합부동산세의 납세의무자는 매도인이다.","납세의무자가 국내에 주소를 두고 있는 개인의 경우 납세지는 주소지이다.","납세자에게 부정행위가 없으며 특례제척기간에 해당하지 않는 경우, 원칙적으로 납세의무 성립일부터 5년이 지나면 종합부동산세를 부과할 수 없다.","납세의무자는 선택에 따라 신고·납부할 수 있으나, 신고를 함에 있어 납부세액을 과소하게 신고한 경우라도 과소신고가산세가 적용되지 않는다.","종합부동산세는 물납이 허용되지 않는다."],"a":[4],"p":35,"L":"세3-1","S":[],"m":"","f":null},{"i":"29회-2차-108","r":29,"y":2018,"c":2,"g":"2교시","n":28,"q":"지방세법상 재산세 종합합산과세대상 토지는?","b":null,"bs":"없음","img":[],"ch":["「문화유산의 보존 및 활용에 관한 법률」에 따른 지정문화유산 안의 임야","국가가 국방상의 목적 외에는 그 사용 및 처분 등을 제한하는 공장 구내의 토지","「건축법」 등 관계 법령에 따라 허가 등을 받아야 할 건축물로서 허가 등을 받지 아니한 공장용 건축물의 부속토지","「자연공원법」에 따라 지정된 공원자연환경지구의 임야","「개발제한구역의 지정 및 관리에 관한 특별조치법」에 따른 개발제한구역의 임야"],"a":[3],"p":37,"L":"세2-3","S":[],"m":"","f":{"판정":"수정","요약":"①의 법령명·용어가 「문화재보호법」 지정문화재→「문화유산의 보존 및 활용에 관한 법률」 지정문화유산(지방세법 시행령 제102조 제2항 제2호 가목)으로 바뀌어 수정. 현행 시행령 제102조 제2항 제5호 가목이 개발제한구역 임야를 분리과세로 명시하므로 ⑤는 종합합산 아님 → 무허가 공장용 건축물 부속토지(시행령 제101조 제1항 단서·제102조 제1항 제1호 단서로 별도합산·분리과세 모두 제외)인 ③ 단일정답. 발문의 복수정답 안내문구 삭제. ②시행령 제102조 제5항 제1호, ④제102조 제2항 제3호 분리과세","수정":[{"위치":"발문","원문":"지방세법상 재산세 종합합산과세대상 토지는?","수정문":"지방세법상 재산세 종합합산과세대상 토지는?","근거":"지방세법 시행령 제102조 제2항 제5호 가목","바뀐점":"복수정답 안내문구 삭제(현행 조문으로 단일정답)"},{"위치":"선지1","원문":"「문화재보호법」제2조 제2항에 따른 지정문화재 안의 임야","수정문":"「문화유산의 보존 및 활용에 관한 법률」에 따른 지정문화유산 안의 임야","근거":"지방세법 시행령 제102조 제2항 제2호 가목","바뀐점":"문화재보호법 제2조 제2항 지정문화재→문화유산의 보존 및 활용에 관한 법률 지정문화유산"}],"정답변경사유":"공식 복수정답 ③⑤. 현행 지방세법 시행령 제102조 제2항 제5호 가목상 개발제한구역의 임야는 분리과세대상이 명백하므로 ⑤는 종합합산과세대상이 아님 → ③ 단일정답(출제 당시 ⑤가 인정된 구체적 사유는 확인 못 함)"}},{"i":"29회-2차-109","r":29,"y":2018,"c":2,"g":"2교시","n":29,"q":"지방세법상 2018년도 귀속 재산세의 부과·징수에 관한 설명으로 틀린 것은? (단, 세액변경이나 수시부과사유는 없음)","b":null,"bs":"없음","img":[],"ch":["토지분 재산세 납기는 매년 9월 16일부터 9월 30일까지이다.","선박분 재산세 납기는 매년 7월 16일부터 7월 31일까지이다.","재산세를 징수하려면 재산세 납세고지서를 납기개시 5일 전까지 발급하여야 한다.","주택분 재산세로서 해당 연도에 부과할 세액이 20만원 이하인 경우 9월 30일 납기로 한꺼번에 부과·징수한다.","재산세를 물납하려는 자는 납부기한 10일 전까지 납세지를 관할하는 시장·군수·구청장에게 물납을 신청하여야 한다."],"a":[4],"p":38,"L":"세2-3","S":[],"m":"","f":null},{"i":"29회-2차-110","r":29,"y":2018,"c":2,"g":"2교시","n":30,"q":"甲은 특수관계 없는 乙로부터 다음과 같은 내용으로 주택을 취득하였다. 취득세 과세표준 금액으로 옳은 것은?","b":"○ 아래의 계약내용은 「부동산 거래신고 등에 관한 법률」제3조에 따른 신고서를 제출하여 같은 법 제5조에 따라 검증이 이루어짐\n○ 계약내용\n- 총매매대금 500,000,000원 2018년 7월 2일 계약금 50,000,000원 2018년 8월 2일 중도금 150,000,000원 2018년 9월 3일 잔금 300,000,000원\n○ 甲이 주택 취득과 관련하여 지출한 비용\n- 총매매대금 외에 당사자약정에 의하여 乙의 은행 채무를 甲이 대신 변제한 금액 10,000,000원\n- 법령에 따라 매입한 국민주택채권을 해당 주택의 취득 이전에 금융회사에 양도함으로써 발생하는 매각차손 1,000,000원","bs":"글자","img":[],"ch":["500,000,000원","501,000,000원","509,000,000원","510,000,000원","511,000,000원"],"a":[5],"p":30,"L":"세2-1","S":[],"m":"","f":null},{"i":"29회-2차-111","r":29,"y":2018,"c":2,"g":"2교시","n":31,"q":"국세 및 지방세의 납세의무 성립시기에 관한 내용으로 옳은 것은? (단, 특별징수 및 수시부과와 무관함)","b":null,"bs":"없음","img":[],"ch":["사업소분 주민세: 매년 7월 1일","거주자의 양도소득에 대한 지방소득세: 매년 3월 31일","재산세에 부가되는 지방교육세: 매년 8월 1일","중간예납 하는 소득세: 매년 12월 31일","자동차 소유에 대한 자동차세: 납기가 있는 달의 10일"],"a":[1],"p":38,"L":"세1-1","S":[],"m":"","f":{"판정":"수정","요약":"주민세 재산분이 사업소분으로 개편되어 명칭 수정. 사업소분 과세기준일 7월1일(지방세법 제83조 제2항)=성립시기(지방세기본법 제34조 제1항 제6호 가목)라 ① 정답 유지. ②~⑤(지방소득세·지방교육세·중간예납·자동차세 1일) 여전히 틀림","수정":[{"위치":"선지1","원문":"재산분 주민세: 매년 7월 1일","수정문":"사업소분 주민세: 매년 7월 1일","근거":"지방세기본법 제34조 제1항 제6호 가목, 지방세법 제83조 제2항","바뀐점":"주민세 재산분→사업소분(2020.12.29 개정)"}],"정답변경사유":""}},{"i":"29회-2차-112","r":29,"y":2018,"c":2,"g":"2교시","n":32,"q":"지방세법상 과점주주의 간주취득세가 과세되는 경우가 아닌 것은 모두 몇 개인가? (단, 주식발행법인은 「자본시장과 금융투자업에 관한 법률 시행령」 제176조의 9 제1항에 따른 유가증권시장에 상장한 법인이 아니며, 「지방세특례제한법」은 고려하지 않음)","b":"ㄱ. 법인설립 시에 발행하는 주식을 취득함으로써 과점주주가 된 경우\nㄴ. 과점주주가 아닌 주주가 다른 주주로부터 주식을 취득함으로써 최초로 과점주주가 된 경우\nㄷ. 이미 과점주주가 된 주주가 해당 법인의 주식을 취득하여 해당 법인의 주식의 총액에 대한 과점주주가 가진 주식의 비율이 증가된 경우\nㄹ. 과점주주 집단 내부에서 주식이 이전되었으나 과점주주 집단이 소유한 총주식의 비율에 변동이 없는 경우","bs":"글자","img":[],"ch":["0개","1개","2개","3개","4개"],"a":[3],"p":37,"L":"세2-1","S":[],"m":"","f":null},{"i":"29회-2차-113","r":29,"y":2018,"c":2,"g":"2교시","n":33,"q":"지방세법상 신탁(「신탁법」에 따른 신탁으로서 신탁등기가 병행되는 것임)으로 인한 신탁재산의 취득으로서 취득세를 부과하는 경우는 모두 몇 개인가?","b":"ㄱ. 위탁자로부터 수탁자에게 신탁재산을 이전하는 경우\nㄴ. 신탁의 종료로 인하여 수탁자로부터 위탁자에게 신탁재산을 이전하는 경우\nㄷ. 수탁자가 변경되어 신수탁자에게 신탁재산을 이전하는 경우\nㄹ.「주택법」에 따른 주택조합이 비조합원용 부동산을 취득하는 경우","bs":"글자","img":[],"ch":["0개","1개","2개","3개","4개"],"a":[2],"p":29,"L":"세2-1","S":[],"m":"","f":null},{"i":"29회-2차-114","r":29,"y":2018,"c":2,"g":"2교시","n":34,"q":"소득세법상 거주자의 양도소득과세표준 계산에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["양도소득금액을 계산할 때 부동산을 취득할 수 있는 권리에서 발생한 양도차손은 토지에서 발생한 양도소득금액에서 공제할 수 없다.","양도차익을 실지거래가액에 의하는 경우 양도가액에서 공제할 취득가액은 그 자산에 대한 감가상각비로서 각 과세 기간의 사업소득금액을 계산하는 경우 필요경비에 산입한 금액이 있을 때에는 이를 공제하지 않은 금액으로 한다.","양도소득에 대한 과세표준은 종합소득 및 퇴직소득에 대한 과세표준과 구분하여 계산한다.","1세대 1주택 비과세 요건을 충족하는 고가주택의 양도 가액이 24억원이고 양도차익이 4억원인 경우 양도소득세가 과세되는 양도차익은 3억원이다.","2018년 4월 1일 이후 지출한 자본적지출액은 그 지출에 관한 증명서류를 수취·보관하지 않고 실제 지출 사실이 금융거래 증명서류에 의하여 확인되지 않는 경우에도 양도차익 계산 시 양도가액에서 공제할 수 있다."],"a":[3],"p":35,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"고가주택 기준 12억원(실지거래가액 합계) 반영 — 양도가액 12억원은 현행 고가주택이 아니므로 수치 조정(현행 계산 4억×12/24=2억 → 선지 여전히 틀림). ①②⑤ 틀림(제102조, 제97조제3항, 시행령 제163조제3항) 현행 동일","수정":[{"위치":"선지4","원문":"1세대 1주택 비과세 요건을 충족하는 고가주택의 양도 가액이 12억원이고 양도차익이 4억원인 경우 양도소득세가 과세되는 양도차익은 3억원이다.","수정문":"1세대 1주택 비과세 요건을 충족하는 고가주택의 양도 가액이 24억원이고 양도차익이 4억원인 경우 양도소득세가 과세되는 양도차익은 3억원이다.","근거":"소득세법 제89조제1항제3호, 제95조제3항, 시행령 제160조","바뀐점":"고가주택 기준 9억원→12억원(실지거래가액 합계). 양도가액 12억원은 고가주택에 해당하지 않아 전제가 성립하지 않으므로 24억원으로 조정(과세 양도차익 2억원 → 여전히 틀린 선지)"}],"정답변경사유":""}},{"i":"29회-2차-115","r":29,"y":2018,"c":2,"g":"2교시","n":35,"q":"소득세법상 거주자의 양도소득세 신고 및 납부에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지 또는 건물을 양도한 경우에는 그 양도일에 속하는 분기의 말일부터 2개월 이내에 양도소득과세표준을 신고해야 한다.","양도차익이 없거나 양도차손이 발생한 경우에는 양도소득과세표준 예정신고 의무가 없다.","건물을 신축하고 그 신축한 건물의 취득일부터 5년 이내에 해당 건물을 양도하는 경우로서 취득 당시의 실지 거래가액을 확인할 수 없어 환산가액을 그 취득가액으로 하는 경우에는 양도소득세 산출세액의 100분의 5에 해당하는 금액을 양도소득 결정세액에 더한다.","양도소득과세표준 예정신고 시에는 납부할 세액이 1천만원을 초과하더라도 그 납부할 세액의 일부를 분할납부할 수 없다.","당해 연도에 누진세율의 적용대상 자산에 대한 예정신고를 2회 이상 한 자가 법령에 따라 이미 신고한 양도소득금액과 합산하여 신고하지 아니한 경우 양도소득세 확정신고를 해야 한다."],"a":[5],"p":28,"L":"세3-2","S":[],"m":"","f":null},{"i":"29회-2차-116","r":29,"y":2018,"c":2,"g":"2교시","n":36,"q":"소득세법상 미등기양도자산에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["미등기양도자산도 양도소득에 대한 소득세의 비과세에 관한 규정을 적용할 수 있다.","건설사업자가 「도시개발법」에 따라 공사용역 대가로 취득한 체비지를 토지구획환지처분공고 전에 양도하는 토지는 미등기양도자산에 해당하지 않는다.","미등기양도자산의 양도소득금액 계산 시 양도소득 기본 공제를 적용할 수 있다.","미등기양도자산은 양도소득세 산출세액에 100분의 70을 곱한 금액을 양도소득 결정세액에 더한다.","미등기양도자산의 양도소득금액 계산 시 장기보유 특별공제를 적용할 수 있다."],"a":[2],"p":27,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"미등기양도제외 자산 시행령 제168조제1항제7호 용어 '건설업자'→'건설사업자' 반영, 참거짓 동일","수정":[{"위치":"선지2","원문":"건설업자가 「도시개발법」에 따라 공사용역 대가로 취득한 체비지를 토지구획환지처분공고 전에 양도하는 토지는 미등기양도자산에 해당하지 않는다.","수정문":"건설사업자가 「도시개발법」에 따라 공사용역 대가로 취득한 체비지를 토지구획환지처분공고 전에 양도하는 토지는 미등기양도자산에 해당하지 않는다.","근거":"소득세법 시행령 제168조제1항제7호","바뀐점":"법령 용어 '건설업자'→'건설사업자'"}],"정답변경사유":""}},{"i":"29회-2차-117","r":29,"y":2018,"c":2,"g":"2교시","n":37,"q":"소득세법 시행령 제162조에서 규정하는 양도 또는 취득의 시기에 관한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["제1항 제4호: 자기가 건설한 건축물에 있어서 건축허가를 받지 아니하고 건축하는 건축물은 추후 사용승인 또는 임시사용승인을 받는 날","제1항 제3호: 재정경제부령이 정하는 장기할부조건의 경우에는 소유권이전등기(등록 및 명의개서를 포함)접수일·인도일 또는 사용수익일 중 빠른 날","제1항 제2호: 대금을 청산하기 전에 소유권이전등기(등록 및 명의개서를 포함)를 한 경우에는 등기부·등록부 또는 명부 등에 기재된 등기접수일","제1항 제5호: 상속에 의하여 취득한 자산에 대하여는 그 상속이 개시된 날","제1항 제9호: 「도시개발법」에 따른 환지처분으로 교부 받은 토지의 면적이 환지처분에 의한 권리면적보다 증가한 경우 그 증가된 면적의 토지에 대한 취득시기는 환지처분의 공고가 있은 날의 다음날"],"a":[1],"p":29,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"시행령 제162조제1항제3호 위임 부령 명칭 '기획재정부령'→'재정경제부령'(정부조직 개편) 반영. ①(무허가 건축물=사실상 사용일) 틀림 현행 동일","수정":[{"위치":"선지2","원문":"제1항 제3호: 기획재정부령이 정하는 장기할부조건의 경우에는 소유권이전등기(등록 및 명의개서를 포함)접수일·인도일 또는 사용수익일 중 빠른 날","수정문":"제1항 제3호: 재정경제부령이 정하는 장기할부조건의 경우에는 소유권이전등기(등록 및 명의개서를 포함)접수일·인도일 또는 사용수익일 중 빠른 날","근거":"소득세법 시행령 제162조제1항제3호","바뀐점":"부령 명칭 기획재정부령→재정경제부령"}],"정답변경사유":""}},{"i":"29회-2차-118","r":29,"y":2018,"c":2,"g":"2교시","n":38,"q":"다음은 소득세법 시행령 제155조 '1세대 1주택의 특례'에 관한 조문의 내용이다. 괄호 안에 들어갈 법령상의 숫자를 순서대로 옳게 나열한 것은?","b":"· 1주택을 보유하는 자가 1주택을 보유하는 자와 혼인함으로써 1세대가 2주택을 보유하게 되는 경우 혼인한 날부터 ( )년 이내에 먼저 양도하는 주택은 이를 1세대 1주택으로 보아 제154조 제1항을 적용한다.\n· 1주택을 보유하고 1세대를 구성하는 자가 1주택을 보유하고 있는 ( )세 이상의 직계존속(배우자의 직계존속을 포함하며, 직계존속 중 어느 한 사람이 ( )세 미만인 경우를 포함)을 동거봉양하기 위하여 세대를 합침으로써 1세대가 2주택을 보유하게 되는 경우 합친 날부터 ( )년 이내에 먼저 양도하는 주택은 이를 1세대 1주택으로 보아 제154조 제1항을 적용한다.","bs":"글자","img":[],"ch":["3, 55, 55, 5","3, 60, 60, 5","3, 60, 55, 10","5, 55, 55, 10","10, 60, 60, 10"],"a":[5],"p":35,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"혼인합가 특례기간 5년→10년(시행령 제155조제5항, 2024.11.12 개정) 반영. 동거봉양 60세·10년은 현행 동일","수정":[{"위치":"선지5","원문":"5, 60, 60, 10","수정문":"10, 60, 60, 10","근거":"소득세법 시행령 제155조제4항·제5항","바뀐점":"혼인한 날부터 5년→10년 이내 양도"}],"정답변경사유":""}},{"i":"29회-2차-119","r":29,"y":2018,"c":2,"g":"2교시","n":39,"q":"지방세법상 등록면허세가 과세되는 등록 또는 등기가 아닌 것은? (단, 2018년 1월 1일 이후 등록 또는 등기한 것으로 가정함)","b":null,"bs":"없음","img":[],"ch":["광업권의 취득에 따른 등록","외국인 소유의 선박을 직접 사용하기 위하여 연부취득 조건으로 수입하는 선박의 등록","취득세 부과제척기간이 경과한 주택의 등기","취득가액이 50만원 이하인 차량의 등록","계약상의 잔금지급일을 2017년 12월 1일로 하는 부동산(취득가액 1억원)의 소유권이전등기"],"a":[5],"p":25,"L":"세2-2","S":[],"m":"","f":null},{"i":"29회-2차-120","r":29,"y":2018,"c":2,"g":"2교시","n":40,"q":"甲이 乙소유 부동산에 관해 전세권설정등기를 하는 경우 지방세법상 등록에 대한 등록면허세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["등록면허세의 납세의무자는 전세권자인 甲이다.","부동산소재지와 乙의 주소지가 다른 경우 등록면허세의 납세지는 乙의 주소지로 한다.","전세권설정등기에 대한 등록면허세의 표준세율은 전세 금액의 1,000분의 2이다.","전세권설정등기에 대한 등록면허세의 산출세액이 건당 6천원보다 적을 때에는 등록면허세의 세액은 6천원으로 한다.","만약 丙이 甲으로부터 전세권을 이전받아 등기하는 경우라면 등록면허세의 납세의무자는 丙이다."],"a":[2],"p":33,"L":"세2-2","S":[],"m":"","f":null},{"i":"30회-2차-105","r":30,"y":2019,"c":2,"g":"2교시","n":25,"q":"국내 소재 부동산의 보유단계에서 부담할 수 있는 세목은 모두 몇 개인가?","b":"- 농어촌특별세  - 지방교육세\n- 개인지방소득세\n- 소방분 지역자원시설세","bs":"글자","img":[],"ch":["0개","1개","2개","3개","4개"],"a":[5],"p":24,"L":"세1-1","S":[],"m":"","f":{"판정":"수정","요약":"지역자원시설세 명칭 '특정부동산'→'소방분'(지방세법 제142조) 반영, 4개 결론 동일","수정":[{"위치":"보기","원문":"- 특정부동산에 대한 지역자원시설세","수정문":"- 소방분 지역자원시설세","근거":"지방세법 제142조제1항·제2항제3호","바뀐점":"특정부동산분 지역자원시설세 → 소방분 지역자원시설세로 명칭 변경"}],"정답변경사유":""}},{"i":"30회-2차-106","r":30,"y":2019,"c":2,"g":"2교시","n":26,"q":"지방세기본법상 이의신청·심판청구에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["「지방세기본법」에 따른 과태료의 부과처분을 받은 자는 이의신청, 심사청구 또는 심판청구를 할 수 없다.","심판청구는 그 처분의 집행에 효력이 미치지 아니하지만 압류한 재산에 대하여는 심판청구의 결정이 있는 날부터 30일까지 그 공매처분을 보류할 수 있다.","지방세에 관한 불복시 불복청구인은 이의신청을 거치지 아니하면 행정소송을 제기할 수 없다.","이의신청인은 신청금액이 2천만원 미만인 경우에는 그의 배우자, 4촌 이내의 혈족 또는 그의 배우자의 4촌 이내 혈족을 대리인으로 선임할 수 있다.","이의신청이 이유 없다고 인정될 때에는 신청을 기각하는 결정을 한다."],"a":[3],"p":20,"L":"세1-1","S":[],"m":"","f":{"판정":"수정","요약":"지방세기본법상 심사청구 폐지(이의신청 → 심판청구 체계, 행정소송은 심판청구 전치 제98조제3항), 가족 대리인 선임 기준 1천만원→2천만원(제93조제2항) 반영","수정":[{"위치":"발문","원문":"지방세기본법상 이의신청·심사청구·심판청구에 관한 설명으로 틀린 것은?","수정문":"지방세기본법상 이의신청·심판청구에 관한 설명으로 틀린 것은?","근거":"지방세기본법 제89조","바뀐점":"지방세기본법상 심사청구 제도 폐지"},{"위치":"선지3","원문":"지방세에 관한 불복시 불복청구인은 심사청구를 거치지 아니하면 행정소송을 제기할 수 없다.","수정문":"지방세에 관한 불복시 불복청구인은 이의신청을 거치지 아니하면 행정소송을 제기할 수 없다.","근거":"지방세기본법 제91조제3항, 제98조제3항","바뀐점":"심사청구 폐지. 이의신청은 임의절차(바로 심판청구 가능), 행정소송은 심판청구 전치 → 여전히 틀린 선지"},{"위치":"선지4","원문":"이의신청인은 신청금액이 1천만원 미만인 경우에는 그의 배우자, 4촌 이내의 혈족 또는 그의 배우자의 4촌 이내 혈족을 대리인으로 선임할 수 있다.","수정문":"이의신청인은 신청금액이 2천만원 미만인 경우에는 그의 배우자, 4촌 이내의 혈족 또는 그의 배우자의 4촌 이내 혈족을 대리인으로 선임할 수 있다.","근거":"지방세기본법 제93조제2항","바뀐점":"1천만원 미만→2천만원 미만"},{"위치":"선지5","원문":"심사청구가 이유 없다고 인정될 때에는 청구를 기각하는 결정을 한다.","수정문":"이의신청이 이유 없다고 인정될 때에는 신청을 기각하는 결정을 한다.","근거":"지방세기본법 제96조제1항제2호","바뀐점":"심사청구 폐지 → 이의신청 기각결정으로 대체"}],"정답변경사유":""}},{"i":"30회-2차-107","r":30,"y":2019,"c":2,"g":"2교시","n":27,"q":"법정기일 전에 저당권의 설정을 등기한 사실이 등기사항증명서(부동산등기부 등본)에 따라 증명되는 재산을 매각하여 그 매각금액에서 국세 또는 지방세를 징수하는 경우, 그 재산에 대하여 부과되는 다음의 국세 또는 지방세 중 저당권에 따라 담보된 채권에 우선하여 징수하는 것은 모두 몇 개인가? (단, 가산세는 고려하지 않음)","b":"○ 종합부동산세 ○ 취득세에 부가되는 지방교육세\n○ 등록면허세 ○ 부동산임대에 따른 종합소득세\n○ 소방분 지역자원시설세","bs":"글자","img":[],"ch":["1개","2개","3개","4개","5개"],"a":[2],"p":23,"L":"세1-1","S":[],"m":"","f":{"판정":"수정","요약":"당해세 범위 지방세기본법 제71조제5항(소방분 지역자원시설세·재산세 부가 지방교육세), 국세기본법 제35조제3항(종부세) — 2개 결론 동일. 명칭(소방분)과 폐지된 가산금 표현 정리","수정":[{"위치":"발문","원문":"(단, 가산금은 고려하지 않음)","수정문":"(단, 가산세는 고려하지 않음)","근거":"지방세기본법 제2조제1항제22호, 국세기본법 제35조","바뀐점":"가산금 제도 폐지(납부지연가산세로 통합)"},{"위치":"보기","원문":"○ 특정부동산에 대한 지역자원시설세","수정문":"○ 소방분 지역자원시설세","근거":"지방세기본법 제71조제5항제3호","바뀐점":"특정부동산분→소방분 명칭 변경"}],"정답변경사유":""}},{"i":"30회-2차-108","r":30,"y":2019,"c":2,"g":"2교시","n":28,"q":"지방세법상 취득의 시기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["상속으로 인한 취득의 경우: 상속개시일","공매방법에 의한 취득의 경우: 그 사실상의 잔금지급일과 등기일 또는 등록일 중 빠른 날","건축물(주택 아님)을 건축하여 취득하는 경우로서 사용승인서를 내주기 전에 임시사용승인을 받은 경우: 그 임시사용승인일과 사실상의 사용일 중 빠른 날","「민법」제839조의 2에 따른 재산분할로 인한 취득의 경우: 취득물건의 등기일 또는 등록일","관계 법령에 따라 매립으로 토지를 원시취득하는 경우: 취득물건의 등기일"],"a":[5],"p":33,"L":"세2-1","S":[],"m":"","f":null},{"i":"30회-2차-109","r":30,"y":2019,"c":2,"g":"2교시","n":29,"q":"지방세법상 취득세가 부과되지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["「주택법」에 따른 공동주택의 개수(「건축법」에 따른 대수선 제외)로 인한 취득 중 개수로 인한 취득 당시 주택의 시가표준액이 9억원 이하인 경우","형제간에 부동산을 상호교환한 경우","직계존속으로부터 거주하는 주택을 증여받은 경우","파산신고로 인하여 처분되는 부동산을 취득한 경우","「주택법」에 따른 주택조합이 해당 조합원용으로 조합주택용 부동산을 취득한 경우"],"a":[1],"p":32,"L":"세2-1","S":[],"m":"","f":null},{"i":"30회-2차-110","r":30,"y":2019,"c":2,"g":"2교시","n":30,"q":"지방세법상 취득세의 표준세율이 가장 높은 것은? (단, 「지방세특례제한법」은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["상속으로 건물(주택 아님)을 취득한 경우","「사회복지사업법」에 따라 설립된 사회복지법인이 독지가의 기부에 의하여 건물을 취득한 경우","영리법인이 공유수면을 매립하여 농지를 취득한 경우","유상거래를 원인으로 「지방세법」제10조에 따른 취득 당시의 가액이 6억원인 주택(「주택법」에 의한 주택으로서 등기부에 주택으로 기재된 주거용 건축물과 그 부속토지)을 취득한 경우","유상거래를 원인으로 농지를 취득한 경우"],"a":[5],"p":24,"L":"세2-1","S":[],"m":"","f":{"판정":"수정","요약":"유상 주택 세율이 6억~9억 구간 산식으로 바뀌어 9억원 주택은 3%(=⑤ 농지 3%)로 동률이 되므로 ④ 가액 조정","수정":[{"위치":"선지4","원문":"유상거래를 원인으로 「지방세법」제10조에 따른 취득 당시의 가액이 9억원인 주택(「주택법」에 의한 주택으로서 등기부에 주택으로 기재된 주거용 건축물과 그 부속토지)을 취득한 경우","수정문":"유상거래를 원인으로 「지방세법」제10조에 따른 취득 당시의 가액이 6억원인 주택(「주택법」에 의한 주택으로서 등기부에 주택으로 기재된 주거용 건축물과 그 부속토지)을 취득한 경우","근거":"지방세법 제11조제1항제8호","바뀐점":"9억원 주택 = (9억×2/3억−3)/100 = 1천분의 30으로 ⑤(1천분의 30)와 같아짐 → 6억원(1천분의 10)으로 조정해 ⑤ 단독 최고 유지"}],"정답변경사유":""}},{"i":"30회-2차-111","r":30,"y":2019,"c":2,"g":"2교시","n":31,"q":"지방세법상 재산세 표준세율이 초과누진세율로 되어 있는 재산세 과세대상을 모두 고른 것은?","b":"ㄱ. 별도합산과세대상 토지\nㄴ. 분리과세대상 토지\nㄷ. 광역시(군 지역은 제외) 지역에서 「국토의 계획 및 이용에 관한 법률」과 그 밖의 관계 법령에 따라 지정된 주거지역의 대통령령으로 정하는 공장용 건축물\nㄹ. 주택(「지방세법」에 따른 별장 제외)","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":[3],"p":28,"L":"세2-3","S":[],"m":"","f":null},{"i":"30회-2차-112","r":30,"y":2019,"c":2,"g":"2교시","n":32,"q":"지방세법상 재산세 비과세 대상에 해당하는 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["지방자치단체가 1년 이상 공용으로 사용하는 재산으로서 유료로 사용하는 재산","「한국농어촌공사 및 농지관리기금법」에 따라 설립된 한국농어촌공사가 같은 법에 따라 공급하기 위하여 소유하는 농지","「공간정보의 구축 및 관리 등에 관한 법률」에 따른 제방으로서 특정인이 전용하는 제방","「군사기지 및 군사시설 보호법」에 따른 군사기지 및 군사시설 보호구역 중 통제보호구역에 있는 전·답","「산림자원의 조성 및 관리에 관한 법률」에 따라 지정된 채종림·시험림"],"a":[5],"p":34,"L":"세2-3","S":[],"m":"","f":null},{"i":"30회-2차-113","r":30,"y":2019,"c":2,"g":"2교시","n":33,"q":"지방세법상 재산세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["건축물에 대한 재산세의 납기는 매년 9월 16일에서 9월 30일이다.","재산세의 과세대상 물건이 공부상 등재 현황과 사실상의 현황이 다른 경우에는 공부상 현황에 따라 재산세를 부과한다.","주택에 대한 재산세는 납세의무자별로 해당 지방자치단체의 관할구역에 있는 주택의 과세표준을 합산하여 주택의 세율을 적용한다.","지방자치단체의 장은 재산세의 납부세액(재산세 도시지역분 포함)이 1천만원을 초과하는 경우에는 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 대통령령으로 정하는 바에 따라 물납을 허가할 수 있다.","주택에 대한 재산세의 과세표준은 시가표준액의 100분의 70으로 한다."],"a":[4],"p":29,"L":"세2-3","S":[],"m":"","f":null},{"i":"30회-2차-114","r":30,"y":2019,"c":2,"g":"2교시","n":34,"q":"지방세법상 등록면허세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산 등기에 대한 등록면허세의 납세는 부동산 소재지이다.","등록을 하려는 자가 법정신고기한까지 등록면허세 산출세액을 신고하지 않은 경우로서 등록 전까지 그 산출세액을 납부한 때에도 「지방세기본법」에 따른 무신고가산세가 부과된다.","등기 담당 공무원의 착오로 인한 지번의 오기에 대한 경정 등기에 대해서는 등록면허세를 부과하지 아니한다.","채권금액으로 과세액을 정하는 경우에 일정한 채권금액이 없을 때에는 채권의 목적이 된것의 가액 또는 처분의 제한의 목적이 된 금액을 그 채권금액으로 본다.","「한국은행법」및「한국수출입은행법」에 따른 은행업을 영위하기 위하여 대도시에서 법인을 설립함에 따른 등기를 한 법인이 그 등기일부터 2년 이내에 업종변경이나 업종 추가가 없는 때에는 등록면허세의 세율을 중과하지 아니한다."],"a":[2],"p":35,"L":"세2-2","S":[],"m":"","f":null},{"i":"30회-2차-115","r":30,"y":2019,"c":2,"g":"2교시","n":35,"q":"소득세법상 거주자가 국내에 있는 자산을 양도한 경우 양도소득과세표준에 적용되는 세율로 틀린 것은? (단, 주어진 자산 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["보유기간이 1년 이상 2년 미만인 등기된 상업용 건물: 100분의 40","보유기간이 1년 미만인 조합원입주권: 100분의 70","거주자가 조정대상지역의 공고가 있은 날 이전에 주택의 입주자로 선정된 지위를 양도하기 위한 매매계약을 체결하고 계약금을 지급받은 사실이 증빙서류에 의하여 확인되는 경우 그 조정대상지역 내 주택의 입주자로 선정된 지위: 100분의 50","양도소득과세표준이 1,400만원 이하인 등기된 비사업용 토지(지정지역에 있지 않음): 100분의 16","미등기건물(미등기양도제외 자산 아님): 100분의 70"],"a":[3],"p":35,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"공식 전항정답 문항. 현행 기준 ②(1년 미만 조합원입주권 100분의 70으로 인상)가 개정으로 틀리게 되어 현행 수치로 바꾸면 ③(분양권 100분의 60·70, 조정대상지역 예외 폐지 → 100분의 50 틀림)만 틀린 선지로 남음. ④ 기본세율 구간 1,400만원 반영","수정":[{"위치":"선지2","원문":"보유기간이 1년 미만인 조합원입주권: 100분의 40","수정문":"보유기간이 1년 미만인 조합원입주권: 100분의 70","근거":"소득세법 제104조제1항제3호","바뀐점":"1년 미만 조합원입주권 100분의 40→100분의 70"},{"위치":"선지4","원문":"양도소득과세표준이 1,200만원 이하인 등기된 비사업용 토지(지정지역에 있지 않음): 100분의 16","수정문":"양도소득과세표준이 1,400만원 이하인 등기된 비사업용 토지(지정지역에 있지 않음): 100분의 16","근거":"소득세법 제104조제1항제8호","바뀐점":"기본세율 최저구간 1,200만원 이하→1,400만원 이하(16% = 6%+10%p)"}],"정답변경사유":"공식 전항정답이었으나 현행 조문 기준 ②를 현행 세율(100분의 70)로 맞추면 ③(분양권 세율 100분의 60·70, 조정대상지역 공고 전 계약 예외 폐지)만 틀린 선지가 되어 단일정답 ③"}},{"i":"30회-2차-116","r":30,"y":2019,"c":2,"g":"2교시","n":36,"q":"소득세법상 국내에 있는 자산의 기준시가 산정에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개발사업 등으로 지가가 급등하거나 급등우려가 있는 지역으로서 국세청장이 지정한 지역에 있는 토지의 기준시가가는 배율방법에 따라 평가한 가액으로 한다.","상업용 건물에 대한 새로운 기준시가가 고시되기 전에 취득 또는 양도하는 경우에는 직전의 기준시가에 의한다.","「민사집행법」에 의한 저당권실행을 위하여 토지가 경매되는 경우의 그 경락가액이 개별공시지가 보다 낮은 경우에는 그 차액을 개별공시지가에서 차감하여 양도 당시 기준시가를 계산한다.(단, 지가 급등 지역 아님)","부동산을 취득할 수 있는 권리에 대한 기준시가는 양도 자산의 종류를 고려하여 취득일 또는 양도일까지 납입한 금액으로 한다.","국세청장이 지정하는 지역에 있는 오피스텔의 기준시가는 건물의 종류, 규모, 거래상황, 위치 등을 고려하여 매년 1회 이상 국세청장이 토지와 건물에 대하여 일괄하여 산정·고시하는 가액으로 한다."],"a":[4],"p":18,"L":"세3-2","S":[],"m":"","f":null},{"i":"30회-2차-117","r":30,"y":2019,"c":2,"g":"2교시","n":37,"q":"거주자 甲은 국내에 있는 양도소득세 과세대상 X토지를 2010년 시가 1억원에 매수하여 배우자 乙에게 증여하였다. X토지에는 甲의 금융기관 차입금 5천만원에 대한 저당권이ㅣ 설정되어 있으며 乙이 이를 인수한 사실은 채무부담계약서에 의하여 확인되었다. X 토지의 증여가액과 증여시 「상속세 및 증여세법」에 따라 평가한 가액(시가)은 각각 2억원이었다. 다음 중 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["배우자 간 부담부증여로서 수증자에게 인수되지 아니한 것으로 추정되는 채무액은 부담부증여의 채무액에 해당하는 부분에서 제외한다.","乙이 인수한 채무 5천만원에 해당하는 부분은 양도로 본다.","양도로 보는 부분의 취득가액은 2천5백만원이다.","양도로 보는 부분의 양도가액은 5천만원이다.","甲이 X토지와 증여가액(시가) 2억원인 양도소득세 과세 대상에 해당하지 않는 Y자산을 함께 乙에게 부담부증여하였다면 乙이 인수한 채무 5천만원에 해당하는 부분은 모두 X토지에 대한 양도로 본다."],"a":[5],"p":21,"L":"세3-2","S":[],"m":"","f":null},{"i":"30회-2차-118","r":30,"y":2019,"c":2,"g":"2교시","n":38,"q":"소득세법상 농지에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["농지란 논밭이나 과수원으로서 지적공부의 지목과 관계없이 실제로 경작에 사용되는 토지를 말하며, 농지의 경영에 직접 필요한 농막, 퇴비사, 양수장, 지소(池沼), 농도(農道), 및 수로(水路) 등에 사용되는 토지를 포함한다.","「국토의 계획 및 이용에 관한 법률」에 따른 주거지역·상업지역·공업지역 외에 있는 농지(환지예정지 아님)를 경작상 필요에 의하여 교환함으로써 발생한 소득은 쌍방 토지가액의 차액이 가액이 큰 편의 4분의 1이하이고 새로이 취득한 농지를 3년 이상 농지소재지에 거주하면서 경작하는 경우 비과세한다.","농지로부터 직선거리 30킬로미터 이내에 있는 지역에 사실상 거주하는 자가 그 소유농지에서 농작업의 2분의 1이상을 자기의 노동력에 의하여 경작하는 경우 비사업용 토지에서 제외한다.(단, 농지는 도시지역 외에 있으며, 소유기간 중 재촌과 자경에 변동이 없고 농업에서 발생한 소득 이외에 다른 소득은 없음)","「국토의 계획 및 이용에 관한 법률」에 따른 개발제한 구역에 있는 농지는 비사업용 토지에 해당한다.(단, 소유기간 중 개발제한구역 지정·변경은 없음)","비사업용 토지에 해당하는지 여부를 판단함에 있어 농지의 판정은 소득세법령상 규정이 있는 경우를 제외하고 사실상의 현황에 의하며 사실상의 현황이 분명하지 아니한 경우에는 공부상의 등재현황에 의한다."],"a":[4],"p":23,"L":"세3-2","S":[],"m":"","f":null},{"i":"30회-2차-119","r":30,"y":2019,"c":2,"g":"2교시","n":39,"q":"거주자 甲이 국외에 있는 양도소득세 과세대상 X토지를 양도함으로써 소득이 발생하였다. 다음 중 틀린 것은?(단, 해당 과세기간에 다른 자산의 양도는 없음)","b":null,"bs":"없음","img":[],"ch":["甲이 X토지의 양도일까지 계속 5년 이상 국내에 주소 또는 거소를 둔 경우에만 해당 양도소득에 대한 납세의무가 있다.","甲이 국외에서 외화를 차입하여 X토지를 취득한 경우 환율변동으로 인하여 외화차입금으로부터 발생한 환차익은 양도소득의 범위에서 제외한다.","X토지의 양도가액은 양도 당시의 실지거래가액으로 하는 것이 원칙이다.","X토지에 대한 양도차익에서 장기보유특별공제액을 공제한다.","X토지에 대한 양도소득금액에서 양도소득 기본공제로 250만원을 공제한다."],"a":[4],"p":34,"L":"세3-2","S":[],"m":"","f":null},{"i":"30회-2차-120","r":30,"y":2019,"c":2,"g":"2교시","n":40,"q":"종합부동산세법상 종합부동산세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["과세기준일 현재 토지분 재산세의 납세의무자로서 「자연공원법」에 따라 지정된 공원자연환경지구의 임야를 소유하는 자는 토지에 대한 종합부동산세를 납부할 의무가 있다.","주택분 종합부동산세 납세의무자가 1세대 1주택자에 해당하는 경우의 주택분 종합부동산세액 계산시 연령에 따른 세액공제와 보유기간에 따른 세액공제는 공제율 합계 100분의 80의 범위에서 중복하여 적용할 수 있다.","「근현대문화유산의 보존 및 활용에 관한 법률」에 따른 등록문화유산에 해당하는 주택은 과세표준 합산의 대상이 되는 주택의 범위에 포함되지 않는 것으로 본다.","관할세무서장은 종합부동산세로 납부하여야 할 세액이 400만원인 경우 최대 150만원의 세액을 납부기한이 경과한 날부터 6개월 이내에 분납하게 할 수 있다.","주택분 종합부동산세액을 계산할 때 1주택을 여러 사람이 공동으로 매수하여 소유한 경우 공동 소유자 각자가 그 주택을 소유한 것으로 본다."],"a":[1],"p":20,"L":"세3-1","S":[],"m":"","f":{"판정":"수정","요약":"1세대1주택 연령·보유 공제 합계 한도 100분의 70→80(종부세법 제9조제5항), 문화재→문화유산 명칭, 귀속연도 표기 삭제. ①(공원자연환경지구 임야=분리과세, 종부세 대상 아님) 틀림 동일, ④ 제20조 250만원 초과·6개월 동일","수정":[{"위치":"발문","원문":"2019년 귀속 종합부동산에 관한 설명으로 틀린 것은?","수정문":"종합부동산세법상 종합부동산세에 관한 설명으로 틀린 것은?","근거":"종합부동산세법","바뀐점":"귀속연도(2019년) 표기 삭제, 현행 법령 기준 문항으로 전환"},{"위치":"선지2","원문":"주택분 종합부동산세 납세의무자가 1세대 1주택자에 해당하는 경우의 주택분 종합부동산세액 계산시 연령에 따른 세액공제와 보유기간에 따른 세액공제는 공제율 합계 100분의 70의 범위에서 중복하여 적용할 수 있다.","수정문":"주택분 종합부동산세 납세의무자가 1세대 1주택자에 해당하는 경우의 주택분 종합부동산세액 계산시 연령에 따른 세액공제와 보유기간에 따른 세액공제는 공제율 합계 100분의 80의 범위에서 중복하여 적용할 수 있다.","근거":"종합부동산세법 제9조제5항","바뀐점":"공제율 합계 한도 100분의 70→100분의 80"},{"위치":"선지3","원문":"「문화재보호법」에 따른 등록문화재에 해당하는 주택은 과세표준 합산의 대상이 되는 주택의 범위에 포함되지 않는 것으로 본다.","수정문":"「근현대문화유산의 보존 및 활용에 관한 법률」에 따른 등록문화유산에 해당하는 주택은 과세표준 합산의 대상이 되는 주택의 범위에 포함되지 않는 것으로 본다.","근거":"종합부동산세법 제8조제2항, 시행령 제4조제1항제8호","바뀐점":"「문화재보호법」 등록문화재 → 「근현대문화유산의 보존 및 활용에 관한 법률」 등록문화유산"}],"정답변경사유":""}},{"i":"31회-2차-105","r":31,"y":2020,"c":2,"g":"2교시","n":25,"q":"지방세법상 재산세의 과세표준과 세율에 관한 설명으로 옳은 것을 모두 고른 것은?(단, 법령에 따른 재산세의 경감은 고려하지 않음)","b":"ㄱ. 지방자치단체의 장은 조례로 정하는 바에 따라 표준세율의 100분의 50의 범위에서 가감할 수 있으며, 가감한 세율은 해당 연도부터 3년간 적용한다.\nㄴ. 법령이 정한 고급오락장용 토지의 표준세율은 1천분의 40이다.\nㄷ. 주택의 과세표준은 법령에 따른 시가표준액에 공정시장가액비율(시가표준액의 100분의 60) 을 곱하여 산정한 가액으로 한다.","bs":"글자","img":[],"ch":["ㄱ","ㄷ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[4],"p":32,"L":"세2-3","S":[],"m":"","f":null},{"i":"31회-2차-106","r":31,"y":2020,"c":2,"g":"2교시","n":26,"q":"지방세법상 재산세의 과세대상 및 납세의무자에 관한 설명으로 옳은 것은?(단, 비과세는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["신탁법에 따른 신탁재산에 속하는 종합합산과세대상 토지는 위탁자가 소유한 것으로 보아 위탁자의 다른 종합합산과세대상 토지와 합산한다.","토지와 주택에 대한 재산세 과세대상은 종합합산과세대상, 별도합산과세대상 및 분리과세대상으로 구분한다.","국가가 선수금을 받아 조성하는 매매용 토지로서 사실상 조성이 완료된 토지의 사용권을 무상으로 받은 자는 재산세를 납부할 의무가 없다.","주택 부속토지의 경계가 명백하지 아니한 경우 그 주택의 바닥면적의 20배에 해당하는 토지를 주택의 부속토지로 한다.","재산세 과세대상인 건축물의 범위에는 주택을 포함한다."],"a":[1],"p":28,"L":"세2-3","S":[],"m":"","f":{"판정":"수정","요약":"신탁재산 재산세 납세의무자가 수탁자→위탁자로 바뀌고(지방세법 제107조제2항제5호) '수탁자 고유재산과 합산하지 않는다'는 옛 규정이 삭제됨 → 현행 규정(위탁자 소유로 보아 위탁자의 다른 토지와 합산)으로 옳은 문장 유지. ②~⑤ 틀림 동일(주택 부속토지 10배)","수정":[{"위치":"선지1","원문":"신탁법에 따른 신탁재산에 속하는 종합합산과세대상 토지는 수탁자의 고유재산에 속하는 토지와 합산하지 아니한다.","수정문":"신탁법에 따른 신탁재산에 속하는 종합합산과세대상 토지는 위탁자가 소유한 것으로 보아 위탁자의 다른 종합합산과세대상 토지와 합산한다.","근거":"지방세법 제107조제2항제5호, 제113조제1항제1호, 제119조의2제1항제1호 단서","바뀐점":"신탁재산 납세의무자 수탁자→위탁자(위탁자가 소유한 것으로 봄), 수탁자 고유재산 비합산 규정 삭제"}],"정답변경사유":""}},{"i":"31회-2차-107","r":31,"y":2020,"c":2,"g":"2교시","n":27,"q":"지방세법상 재산세의 부과ㆍ징수에 관한 설명으로 은 것은 모두 몇 개인가?(단, 비과세는 고려하지 않음)","b":"○ 재산세의 과세기준일은 매년 6월 1일로 한다.\n○ 토지의 재산세 납기는 매년 7월 16일부터 7월 31일까지이다.\n○ 지방자치단체의 장은 재산세의 납부할 세액이 500만원 이하인 경우 250만원을 초과하는 금액은 납부기한이 지난 날부터 3개월 이내 분할납부하게 할 수 있다.\n○ 재산세는 관할지방자치단체의 장이 세액을 산정하여 특별징수의 방법으로 부과ㆍ징수한다.","bs":"글자","img":[],"ch":["0개","1개","2개","3개","4개"],"a":[3],"p":32,"L":"세2-3","S":[],"m":"","f":{"판정":"수정","요약":"재산세 분할납부기간 2개월→3개월(지방세법 제118조, 2023.12.29 개정) 반영 — 옳은 것 2개 유지","수정":[{"위치":"보기","원문":"○ 지방자치단체의 장은 재산세의 납부할 세액이 500만원 이하인 경우 250만원을 초과하는 금액은 납부기한이 지난 날부터 2개월 이내 분할납부하게 할 수 있다.","수정문":"○ 지방자치단체의 장은 재산세의 납부할 세액이 500만원 이하인 경우 250만원을 초과하는 금액은 납부기한이 지난 날부터 3개월 이내 분할납부하게 할 수 있다.","근거":"지방세법 제118조, 시행령 제116조제1항제1호","바뀐점":"분할납부기간 2개월→3개월"}],"정답변경사유":""}},{"i":"31회-2차-108","r":31,"y":2020,"c":2,"g":"2교시","n":28,"q":"소득세법상 거주자의 국내자산 양도소득세 계산에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["부동산에 관한 권리의 양도로 발생한 양도차손은 토지의 양도에서 발생한 양도소득금액에서 공제할 수 없다.","양도일부터 소급하여 10년 이내에 그 배우자로부터 증여받은 토지의 양도차익을 계산할 때 그 증여받은 토지에 대하여 납부한 증여세는 양도가액에서 공제할 필요경비에 산입하지 아니한다.","취득원가에 현재가치할인차금이 포함된 양도자산의 보유기간 중 사업소득금액 계산시 필요경비로 산입한 현재가치할인차금상각액은 양도차익을 계산할 때 양도가액에서 공제할 필요경비로 본다.","특수관계인에게 증여한 자산에 대해 증여자인 거주자에게 양도소득세가 과세되는 경우 수증자가 부담한 증여세 상당액은 양도가액에서 공제할 필요경비에 산입한다.","거주자가 특수관계인과의 거래(시가와 거래가액의 차액이 5억원임)에 있어서 토지를 시가에 미달하게 양도함으로써 조세의 부담을 부당히 감소시킨 것으로 인정되는 때에는 그 양도가액을 시가에 의하여 계산한다."],"a":[5],"p":20,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"배우자 등 이월과세 기간 5년→10년(소득세법 제97조의2제1항) 반영. ②는 증여세 필요경비 산입이므로 여전히 틀림, ⑤ 시행령 제167조(3억원 또는 5%) 옳음 동일","수정":[{"위치":"선지2","원문":"양도일부터 소급하여 5년 이내에 그 배우자로부터 증여받은 토지의 양도차익을 계산할 때 그 증여받은 토지에 대하여 납부한 증여세는 양도가액에서 공제할 필요경비에 산입하지 아니한다.","수정문":"양도일부터 소급하여 10년 이내에 그 배우자로부터 증여받은 토지의 양도차익을 계산할 때 그 증여받은 토지에 대하여 납부한 증여세는 양도가액에서 공제할 필요경비에 산입하지 아니한다.","근거":"소득세법 제97조의2제1항","바뀐점":"이월과세 적용기간 5년→10년"}],"정답변경사유":""}},{"i":"31회-2차-109","r":31,"y":2020,"c":2,"g":"2교시","n":29,"q":"소득세법상 거주자의 양도소득과 관련된 다음 자료에 의한 양도소득세 감면액은?(단, 조세특례제한법은 고려하지 않음)","b":"○ 양도소득 과세표준 | 20,000,000원\n○ 감면대상 양도소득금액 | 7,500,000원\n○ 양도소득 기본공제 | 2,500,000원\n○ 양도소득 산출세액 | 10,000,000원\n○ 감면율 | 50%","bs":"글자","img":[],"ch":["1,250,000원","1,750,000원","2,500,000원","3,750,000원","5,000,000원"],"a":[1,2,3,4,5],"p":30,"L":"세3-2","S":[],"m":"공식 최종정답: 전항 정답 처리","f":null},{"i":"31회-2차-110","r":31,"y":2020,"c":2,"g":"2교시","n":30,"q":"소득세법상 거주자의 국내 토지에 대한 양도소득과세표준 및 세액의 신고ㆍ납부에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법령에 따른 부담부증여의 채무액에 해당하는 부분으로서 양도로 보는 경우 그 양도일이 속하는 달의 말일부터 3개월 이내에 양도소득과세표준을 납세지 관할 세무서장에게 신고하여야 한다.","예정신고납부를 하는 경우 예정신고 산출세액에서 감면세액을 빼고 수시부과세액이 있을 때에는 이를 공제하지 아니한 세액을 납부한다.","예정신고납부할 세액이 2천만원을 초과하는 때에는 그 세액의 100분의 50 이하의 금액을 납부기한이 지난 후 2개월 이내에 분할납부할 수 있다.","당해연도에 누진세율의 적용대상 자산에 대한 예정신고를 2회 이상 한 자가 법령에 따라 이미 신고한 양도소득금액과 합산하여 신고하지 아니한 경우에는 양도소득과세표준의 확정신고를 하여야 한다.","양도차익이 없거나 양도차손이 발생한 경우에도 양도소득과세표준의 예정신고를 하여야 한다."],"a":[2],"p":25,"L":"세3-2","S":[],"m":"","f":null},{"i":"31회-2차-111","r":31,"y":2020,"c":2,"g":"2교시","n":31,"q":"지방세기본법 및 지방세법상 용어의 정의에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["\"보통징수\"란 지방세를 징수할 때 편의상 징수할 여건이 좋은 자로 하여금 징수하게 하고 그 징수한 세금을 납부하게 하는 것을 말한다.","취득세에서 사용하는 용어 중 \"부동산\"이란 토지 및 건축물을 말한다.","\"세무공무원\"이란 지방자치단체의 장 또는 지방세의 부과ㆍ징수 등에 관한 사무를 위임받은 공무원을 말한다.","\"납세자\"란 납세의무자(연대납세의무자와 제2차 납세의무자 및 보증인 포함)와 특별징수의무자를 말한다.","\"지방자치단체의 징수금\"이란 지방세 및 체납처분비를 말한다."],"a":[1],"p":33,"L":"세1-1","S":[],"m":"","f":{"판정":"수정","요약":"'지방자치단체의 징수금' 정의에서 가산금 삭제(지방세기본법 제2조제1항제22호) → ⑤가 틀린 문장이 되어 현행 정의로 수정. ①은 특별징수 정의라 틀림 동일","수정":[{"위치":"선지5","원문":"\"지방자치단체의 징수금\"이란 지방세와 가산금 및 체납처분비를 말한다.","수정문":"\"지방자치단체의 징수금\"이란 지방세 및 체납처분비를 말한다.","근거":"지방세기본법 제2조제1항제22호","바뀐점":"가산금 삭제(납부지연가산세로 통합)"}],"정답변경사유":""}},{"i":"31회-2차-112","r":31,"y":2020,"c":2,"g":"2교시","n":32,"q":"소득세법상 거주자(해당 국외자산 양도일까지 계속 5년 이상 국내에 주소를 두고 있음)가 2020년에 양도한 국외자산의 양도소득세에 관한 설명으로 틀린 것은?(단, 국외 외화차입에 의한 취득은 없음)","b":null,"bs":"없음","img":[],"ch":["국외에 있는 부동산에 관한 권리로서 미등기 양도자산의 양도로 발생하는 소득은 양도소득의 범위에 포함된다.","국외토지의 양도에 대한 양도소득세를 계산하는 경우에는 장기보유특별공제액은 공제하지 아니한다.","양도 당시의 실지거래가액이 확인되더라도 외국정부의 평가가액을 양도가액으로 먼저 적용한다.","해당 과세기간에 다른 자산의 양도가 없을 경우 국외토지의 양도에 대한 양도소득이 있는 거주자에 대해서는 해당 과세기간의 양도소득금액에서 연 250만원을 공제한다.","국외토지의 양도소득에 대하여 해당 외국에서 과세를 하는 경우로서 법령이 정한 그 국외자산 양도소득세액을 납부하였거나 납부할 것이 있을 때에는 외국납부세액의 세액공제방법과 필요경비 산입방법 중 하나를 선택하여 적용할 수 있다."],"a":[3],"p":35,"L":"세3-2","S":[],"m":"","f":null},{"i":"31회-2차-113","r":31,"y":2020,"c":2,"g":"2교시","n":33,"q":"지방세법상 지역자원시설세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["소방분 지역자원시설세는 건축물 또는 선박의 가액 또는 시가표준액을 과세표준으로 하여 부과하되, 과세표준이 600만원 이하인 경우 그 표준세율은 1만분의 4로 한다.","소방분 지역자원시설세의 과세대상은 소방시설로 인하여 이익을 받는 자의 건축물 및 선박이다.","주거용이 아닌 4층 이상 10층 이하의 건축물 등 법령으로 정하는 화재위험 건축물에 대해서는 법령에 따른 표준세율에 따라 산출한 금액의 100분의 200을 세액으로 한다.","지방세법에 따라 재산세가 비과세되는 건축물에 대하여도 지역자원시설세는 부과된다.","지하자원이 과세대상인 경우 납세지는 광업권이 등록된 토지의 소재지이다. 다만, 광업권이 등록된 토지가 둘 이상의 지방자치단체에 걸쳐 있는 경우에는 광업권이 등록된 토지의 면적에 따라 안분한다."],"a":[4],"p":23,"L":"세2-3","S":[],"m":"","f":{"판정":"수정","요약":"오물처리시설·수리시설 충당분 폐지, 특정부동산분→소방분(건축물·선박, 토지 제외)으로 개편(지방세법 제142조·제146조) → 옛 제도를 묻던 ①② 현행 규정으로 대체, 연도 한정 삭제. ④(재산세 비과세 건축물에는 소방분 부과 안 함, 제145조제2항) 틀림 동일","수정":[{"위치":"발문","원문":"지방세법상 2020년 납세의무가 성립하는 지역자원시설세에 관한 설명으로 틀린 것은?","수정문":"지방세법상 지역자원시설세에 관한 설명으로 틀린 것은?","근거":"지방세법 제141조~제147조","바뀐점":"연도 한정 삭제, 현행 법령 기준 문항으로 전환"},{"위치":"선지1","원문":"오물처리시설에 충당하는 지역자원시설세는 토지 및 건축물의 전부 또는 일부에 대한 가액을 과세표준으로 하여 부과하되, 그 표준세율은 토지 또는 건축물 가액의 1만분의 2.3으로 한다.","수정문":"소방분 지역자원시설세는 건축물 또는 선박의 가액 또는 시가표준액을 과세표준으로 하여 부과하되, 과세표준이 600만원 이하인 경우 그 표준세율은 1만분의 4로 한다.","근거":"지방세법 제146조제3항제1호","바뀐점":"오물처리시설·수리시설 충당분 지역자원시설세 폐지(삭제 2019.12.31) → 현행 소방분 표준세율로 대체(옳은 문장 유지)"},{"위치":"선지2","원문":"지역자원시설세의 과세대상인 특정부동산은 소방시설, 오물처리시설, 수리시설, 그 밖의 공공시설로 인하여 이익을 받는 자의 건축물, 선박 및 토지이다.","수정문":"소방분 지역자원시설세의 과세대상은 소방시설로 인하여 이익을 받는 자의 건축물 및 선박이다.","근거":"지방세법 제142조제2항제3호","바뀐점":"특정부동산(건축물·선박·토지) → 소방분(건축물·선박)으로 개편(옳은 문장 유지)"}],"정답변경사유":""}},{"i":"31회-2차-114","r":31,"y":2020,"c":2,"g":"2교시","n":34,"q":"소득세법상 거주자의 국내 소재 1세대 1주택인 고가주택과 그 양도소득세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["거주자가 2019년 취득 후 계속 거주한 법령에 따른 고가주택을 2020년 5월에 양도하는 경우 장기보유특별공제의 대상이 되지 않는다.","\"고가주택\"이란 기준시가 12억원을 초과하는 주택을 말한다.","법령에 따른 고가주택에 해당하는 자산의 장기보유특별공제액은 소득세법 제95조 제2항에 따른 장기보유특별공제액에 \"양도가액에서 12억원을 차감한 금액이 양도가액에서 차지하는 비율\"을 곱하여 산출한다.","법령에 따른 고가주택에 해당하는 자산의 양도차익은 소득세법 제95조 제1항에 따른 양도차익에 \"양도가액에서 12억원을 차감한 금액이 양도가액에서 차지하는 비율\"을 곱하여 산출한다.","건축법 시행령 [별표1]에 의한 다가구주택을 구획된 부분별로 양도하지 아니하고 하나의 매매단위로 양도하여 단독주택으로 보는 다가구주택의 경우에는 그 전체를 하나의 주택으로 보아 법령에 따른 고가주택 여부를 판단한다."],"a":[2],"p":18,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"1세대1주택 고가주택 기준 9억원→12억원(실지거래가액 합계, 소득세법 제89조제1항제3호·시행령 제160조) 반영. ②는 '기준시가' 기준이라 여전히 틀림","수정":[{"위치":"선지2","원문":"\"고가주택\"이란 기준시가 9억원을 초과하는 주택을 말한다.","수정문":"\"고가주택\"이란 기준시가 12억원을 초과하는 주택을 말한다.","근거":"소득세법 제89조제1항제3호","바뀐점":"9억원→12억원(판정 기준은 기준시가가 아니라 실지거래가액 합계 → 틀린 선지 유지)"},{"위치":"선지3","원문":"법령에 따른 고가주택에 해당하는 자산의 장기보유특별공제액은 소득세법 제95조 제2항에 따른 장기보유특별공제액에 \"양도가액에서 9억원을 차감한 금액이 양도가액에서 차지하는 비율\"을 곱하여 산출한다.","수정문":"법령에 따른 고가주택에 해당하는 자산의 장기보유특별공제액은 소득세법 제95조 제2항에 따른 장기보유특별공제액에 \"양도가액에서 12억원을 차감한 금액이 양도가액에서 차지하는 비율\"을 곱하여 산출한다.","근거":"소득세법 시행령 제160조제1항제2호","바뀐점":"9억원→12억원"},{"위치":"선지4","원문":"법령에 따른 고가주택에 해당하는 자산의 양도차익은 소득세법 제95조 제1항에 따른 양도차익에 \"양도가액에서 9억원을 차감한 금액이 양도가액에서 차지하는 비율\"을 곱하여 산출한다.","수정문":"법령에 따른 고가주택에 해당하는 자산의 양도차익은 소득세법 제95조 제1항에 따른 양도차익에 \"양도가액에서 12억원을 차감한 금액이 양도가액에서 차지하는 비율\"을 곱하여 산출한다.","근거":"소득세법 시행령 제160조제1항제1호","바뀐점":"9억원→12억원"}],"정답변경사유":""}},{"i":"31회-2차-115","r":31,"y":2020,"c":2,"g":"2교시","n":35,"q":"지방세법상 부동산 등기에 대한 등록면허세의 표준세율로서 틀린 것은?(단, 부동산 등기에 대한 표준세율을 적용하여 산출한 세액이 그 밖의 등기 또는 등록세율보다 크다고 가정하며, 중과세 및 비과세와 지방세특례제한법은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["소유권 보존: 부동산가액의 1천분의 8","가처분: 부동산가액의 1천분의 2","지역권 설정: 요역지가액의 1천분의 2","전세권 이전: 전세금액의 1천분의 2","상속으로 인한 소유권 이전: 부동산가액의 1천분의 8"],"a":[2],"p":26,"L":"세2-2","S":[],"m":"","f":null},{"i":"31회-2차-116","r":31,"y":2020,"c":2,"g":"2교시","n":36,"q":"지방세법상 취득세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["국가및외국정부의 취득에 대해서는 취득세를 부과한다.","토지의 지목변경에 따른 취득은 토지의 지목이 사실상 변경된 날을 취득일로 본다.","국가가 취득세 과세물건을 매각하면 매각일부터 60일 이내에 지방자치단체의 장에게 신고하여야 한다.","법인이 아닌 자가 건축물을 건축하여 취득하는 경우로서 사실상취득가격을 확인할 수 없는 경우에는 취득자가 신고한 가액을 과세표준으로 한다.","토지를 취득한 자가 그 취득한 날부터 1년 이내에 그에 인접한 토지를 취득한 경우 그 전후의 취득에 관한 토지의 취득을 1건의 토지 취득으로 보아 취득세에 대한 면세점을 적용한다."],"a":[5],"p":28,"L":"세2-1","S":[],"m":"","f":{"판정":"수정","요약":"원시취득 과세표준이 사실상취득가격으로 일원화되고(지방세법 제10조의4, 2023 개정) '법인장부 입증 비율' 규정이 없어져 ④의 틀린 근거가 사라짐 → 현행 규정으로 틀린 문장 재구성. ⑤ 제17조제2항 옳음, ②·③ 틀림(시행령 제20조제10항 빠른 날, 제19조 30일) 동일","수정":[{"위치":"선지4","원문":"법인이 아닌 자가 건축물을 건축하여 취득하는 경우 취득가격 중 100분의 80 이상이 법인장부에 따라 입증되는 경우 그 취득가격을 과세표준으로 한다.","수정문":"법인이 아닌 자가 건축물을 건축하여 취득하는 경우로서 사실상취득가격을 확인할 수 없는 경우에는 취득자가 신고한 가액을 과세표준으로 한다.","근거":"지방세법 제10조의4","바뀐점":"법인장부 입증 비율 규정 삭제 → 사실상취득가격 확인 불가 시 시가표준액(신고가액 아님)으로 틀린 선지 재구성"}],"정답변경사유":""}},{"i":"31회-2차-117","r":31,"y":2020,"c":2,"g":"2교시","n":37,"q":"지방세법상 등록면허세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["지방자치단체의 장은 등록면허세의 세율을 표준세율의 100분의 60의 범위에서 가감할 수 있다.","등록 당시에 감가상각의 사유로 가액이 달라진 경우 그 가액에 대한 증명여부에 관계없이 변경전 가액을 과세표준으로 한다.","부동산 등록에 대한 신고가 없는 경우 취득 당시 시가표준액의 100분의 110을 과세표준으로 한다.","지목이 묘지인 토지의 등록에 대하여 등록면허세를 부과한다.","부동산 등기에 대한 등록면허세의 납세지는 부동산 소재지로 하며, 납세지가 분명하지 아니한 경우에는 등록관청 소재지로 한다."],"a":[5],"p":32,"L":"세2-2","S":[],"m":"","f":null},{"i":"31회-2차-118","r":31,"y":2020,"c":2,"g":"2교시","n":38,"q":"소득세법상 거주자의 부동산과 관련된 사업소득에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["국외에 소재하는 주택의 임대소득은 주택 수에 관계없이 과세하지 아니한다.","공익사업을 위한 토지 등의 취득 및 보상에 관한 법률에 따른 공익사업과 관련하여 지역권을 대여함으로써 발생하는 소득은 부동산업에서 발생하는 소득으로 한다.","부동산임대업에서 발생하는 사업소득의 납세지는 부동산소재지로 한다.","국내에 소재하는 논ㆍ밭을 작물 생산에 이용하게 함으로써 발생하는 사업소득은 소득세를 과세하지 아니한다.","주거용 건물 임대업에서 발생한 결손금은 종합소득 과세표준을 계산할 때 공제하지 아니한다."],"a":[4],"p":29,"L":"세3-3","S":[],"m":"","f":null},{"i":"31회-2차-119","r":31,"y":2020,"c":2,"g":"2교시","n":39,"q":"종합부동산세법상 종합부동산세에 관한 설명으로 틀린 것은?(단, 감면 및 비과세와 지방세특례제한법 또는 조세특례제한법은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["종합부동산세의 과세기준일은 매년 6월 1일로 한다.","종합부동산세의 납세의무자가 비거주자인 개인으로서 국내사업장이 없고 국내원천소득이 발생하지 아니하는 1주택을 소유한 경우 그 주택 소재지를 납세지로 정한다.","과세기준일 현재 토지분 재산세의 납세의무자로서 국내에 소재하는 종합합산과세대상 토지의 공시가격을 합한 금액이 5억원을 초과하는 자는 해당 토지에 대한 종합부동산세를 납부할 의무가 있다.","종합합산과세대상 토지의 재산세로 부과된 세액이 세부담 상한을 적용받는 경우 그 상한을 적용받기 전의 세액을 종합합산과세대상 토지분 종합부동산세액에서 공제한다.","관할세무서장은 종합부동산세를 징수하고자 하는 때에는 납세고지서에 주택 및 토지로 구분한 과세표준과 세액을 기재하여 납부기간 개시 5일 전까지 발부하여야 한다."],"a":[4],"p":30,"L":"세3-1","S":[],"m":"","f":null},{"i":"31회-2차-120","r":31,"y":2020,"c":2,"g":"2교시","n":40,"q":"지방세법상 취득세 또는 등록면허세의 신고ㆍ납부에 관한 설명으로 옳은 것은?(단, 비과세 및 지방세특례제한법은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["상속으로 취득세 과세물건을 취득한 자는 상속개시일로부터 6개월 이내에 과세표준과 세액을 신고ㆍ납부하여야 한다.","취득세 과세물건을 취득한 후 중과세 대상이 되었을 때에는 표준세율을 적용하여 산출한 세액에서 이미 납부한 세액(가산세 포함)을 공제한 금액을 세액으로 하여 신고ㆍ납부하여야 한다.","지목변경으로 인한 취득세 납세의무자가 신고를 하지 아니하고 매각하는 경우 산출세액에 100분의 80을 가산한금액을 세액으로 하여 징수한다.","등록을 하려는 자가 등록면허세 신고의무를 다하지 않고 산출세액을 등록 전까지 납부한 경우 지방세기본법에 따른 무신고가산세를 부과한다.","등기ㆍ등록관서의 장은 등기 또는 등록 후에 등록면허세가 납부되지 아니하였거나 납부부족액을 발견한 경우에는 다음 달 10일까지 납세지를 관할하는 시장ㆍ군수ㆍ구청장에게 통보하여야 한다."],"a":[5],"p":22,"L":"세2-1","S":["세2-2"],"m":"","f":null},{"i":"32회-2차-105","r":32,"y":2021,"c":2,"g":"2교시","n":25,"q":"지방세법상 취득세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["｢도시 및 주거환경정비법｣에 따른 재건축조합이 재건축사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 같은 법에 따른 소유권이전 고시일의 다음 날에 그 토지를 취득한 것으로 본다.","취득세 과세물건을 취득한 후에 그 과세물건이 중과세율의 적용대상이 되었을 때에는 취득한 날부터 60일 이내에 중 과세율을 적용하여 산출한 세액에서 이미 납부한 세액(가산세 포함)을 공제한 금액을 신고하고 납부하여야 한다.","대한민국 정부기관의 취득에 대하여 과세하는 외국정부의 취득에 대해서는 취득세를 부과한다.","상속으로 인한 취득의 경우에는 상속개시일에 취득한 것으로 본다.","부동산의 취득은 ｢민법｣등 관계 법령에 따른 등기ㆍ등록 등을 하지 아니한 경우라도 사실상 취득하면 취득한 것으로 본다."],"a":[2],"p":34,"L":"세2-1","S":[],"m":"","f":null},{"i":"32회-2차-106","r":32,"y":2021,"c":2,"g":"2교시","n":26,"q":"소득세법상 미등기양도자산(미등기양도제외자산 아님)인 상가건물의 양도에 관한 내용으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 양도소득세율은 양도소득 과세표준의 100분의 70\nㄴ. 장기보유특별공제 적용 배제\nㄷ. 필요경비개산공제 적용 배제\nㄹ. 양도소득기본공제 적용 배제","bs":"글자","img":[],"ch":["ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":[2],"p":28,"L":"세3-2","S":[],"m":"","f":null},{"i":"32회-2차-107","r":32,"y":2021,"c":2,"g":"2교시","n":27,"q":"지방세법상 취득세 납세의무에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 보지 아니한다.","상속회복청구의 소에 의한 법원의 확정판결에 의하여 특정 상속인이 당초 상속분을 초과하여 취득하게 되는 재산가액은 상속분이 감소한 상속인으로부터 증여받아 취득한 것으로 본다.","권리의 이전이나 행사에 등기 또는 등록이 필요한 부동산을 직계존속과 서로 교환한 경우에는 무상으로 취득한 것으로 본다.","증여로 인한 승계취득의 경우 해당 취득물건을 등기ㆍ등록하더라도 취득일부터 60일 이내에 공증받은 공정증서에 의하여 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 아니한다.","증여자가 배우자 또는 직계존비속이 아닌 경우 증여자의 채무를 인수하는 부담부 증여의 경우에는 그 채무액에 상당하는 부분은 부동산등을 유상으로 취득하는 것으로 본다."],"a":[5],"p":37,"L":"세2-1","S":[],"m":"","f":null},{"i":"32회-2차-108","r":32,"y":2021,"c":2,"g":"2교시","n":28,"q":"지방세법상 다음에 적용되는 재산세의 표준세율이 가장 높은 것은? (단, 재산세 도시지역분은 제외하고, 지방세관계법에 의한 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["과세표준이 5천만원인 종합합산과세대상 토지","과세표준이 2억원인 별도합산과세대상 토지","과세표준이 1억원인 광역시의 군지역에서 ｢농지법｣에 따른 농업법인이 소유하는 농지로서 과세기준일 현재 실제 영농에 사용되고 있는 농지","과세표준이 5억원인 ｢수도권정비계획법｣에 따른 과밀억제권역 외의 읍ㆍ면 지역의 공장용 건축물","과세표준이 1억 5천만원인 주택(별장 제외. 1세대 1주택에 해당되지 않음)"],"a":[4],"p":25,"L":"세2-3","S":[],"m":"","f":null},{"i":"32회-2차-109","r":32,"y":2021,"c":2,"g":"2교시","n":29,"q":"지방세법상 재산세에 관한 설명으로 틀린 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["토지에 대한 재산세의 과세표준은 시가표준액에 공정시장가액비율(100분의 70)을 곱하여 산정한 가액으로 한다.","지방자치단체가 1년 이상 공용으로 사용하는 재산으로서 유료로 사용하는 경우에는 재산세를 부과한다.","재산세 물납신청을 받은 시장ㆍ군수ㆍ구청장이 물납을 허가하는 경우 물납을 허가하는 부동산의 가액은 물납허가일 현재의 시가로 한다.","주택의 토지와 건물 소유자가 다를 경우 해당 주택에 대한 세율을 적용할 때 해당 주택의 토지와 건물의 가액을 합산한 과세표준에 주택의 세율을 적용한다.","토지에 대한 재산세의 산출세액이 직전 연도의 해당 토지에 대한 재산세액 상당액의 100분의 150을 초과하는 경우에는 100분의 150에 해당하는 금액을 해당 연도에 징수할 세액으로 한다."],"a":[3],"p":28,"L":"세2-3","S":[],"m":"","f":{"판정":"수정","요약":"주택 재산세 세부담상한 폐지(지방세법 제122조 단서 '주택의 경우에는 적용하지 아니한다', 2023.3.14) → ⑤가 틀린 문장이 되어 현행 세부담상한 규정(토지·건축물 100분의 150)으로 옳은 문장 유지. ③(물납 부동산 가액은 과세기준일 현재 시가) 틀림 동일","수정":[{"위치":"선지5","원문":"주택공시가격이 6억원인 주택에 대한 재산세의 산출세액이 직전 연도의 해당 주택에 대한 재산세액 상당액의 100분의 110을 초과하는 경우에는 100분의 110에 해당하는 금액을 해당 연도에 징수할 세액으로 한다.","수정문":"토지에 대한 재산세의 산출세액이 직전 연도의 해당 토지에 대한 재산세액 상당액의 100분의 150을 초과하는 경우에는 100분의 150에 해당하는 금액을 해당 연도에 징수할 세액으로 한다.","근거":"지방세법 제122조","바뀐점":"주택 세부담상한(100분의 105·110·130) 삭제, 주택은 과세표준상한액 제도(제110조제3항)로 대체 → 현행 토지 세부담상한 100분의 150으로 교체"}],"정답변경사유":""}},{"i":"32회-2차-110","r":32,"y":2021,"c":2,"g":"2교시","n":30,"q":"지방세법상 시가표준액에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 토지의 시가표준액은 세목별 납세의무의 성립 시기 당시 ｢부동산 가격공시에 관한 법률｣에 따른 개별공시지가가 공시된 경우 개별공시지가로 한다.\nㄴ. 건축물의 시가표준액은 소득세법령에 따라 매년 1회 국세청장이 산정, 고시하는 건물신축가격기준액에 행정안전부장관이 정한 기준을 적용하여 국토교통부장관이 결정한 가액으로 한다.\nㄷ. 공동주택의 시가표준액은 공동주택가격이 공시되지 아니한 경우에는 지역별․단지별․면적별․층별 특성 및 거래가격을 고려하여 행정안전부장관이 정하는 기준에 따라 국토교통부장관이 산정한 가액으로 한다.","bs":"글자","img":[],"ch":["ㄱ","ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[1],"p":24,"L":"세1-1","S":[],"m":"","f":null},{"i":"32회-2차-111","r":32,"y":2021,"c":2,"g":"2교시","n":31,"q":"거주자인 개인 乙은 甲이 소유한 부동산(시가 6억원)에 전세기간 2년, 전세보증금 3억원으로 하는 전세계약을 체결하고, 전세권 설정등기를 하였다. 지방세법상 등록면허세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["과세표준은 6억원이다.","표준세율은 전세보증금의 1천분의 8이다.","납부세액은 6천원이다.","납세의무자는 乙이다.","납세지는 甲의 주소지이다."],"a":[4],"p":37,"L":"세2-2","S":[],"m":"","f":null},{"i":"32회-2차-112","r":32,"y":2021,"c":2,"g":"2교시","n":32,"q":"거주자인 개인 甲이 乙로부터 부동산을 취득하여 보유하고 있다가 丙에게 양도하였다. 甲의 부동산 관련조세의 납세의무에 관한 설명으로 틀린 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["甲이 乙로부터 증여받은 것이라면 그 계약일에 취득세 납세의무가 성립한다.","甲이 乙로부터 부동산을 취득 후 재산세 과세기준일까지 등기하지 않았다면 재산세와 관련하여 乙은 부동산 소재지 관할 지방자치단체의 장에게 소유권변동사실을 신고할 의무가 있다.","甲이 종합부동산세를 신고납부방식으로 납부하고자 하는 경우 과세표준과 세액을 해당 연도 12월 1일부터 12월 15일까지 관할 세무서장에게 신고하는 때에 종합부동산세 납세의무는 확정된다.","甲이 乙로부터 부동산을 40만원에 취득한 경우 등록면허세 납세의무가 있다.","양도소득세의 예정신고만으로 甲의 양도소득세 납세의무가 확정되지 아니한다."],"a":[5],"p":24,"L":"세1-1","S":[],"m":"","f":null},{"i":"32회-2차-113","r":32,"y":2021,"c":2,"g":"2교시","n":33,"q":"거주자인 개인 甲은 국내에 주택 2채(다가구주택 아님) 및 상가건물 1채를 각각 보유하고 있다. 甲의 재산세 및 종합부동산세에 관한 설명으로 틀린 것은? (단, 甲의 주택은 종합부동산세법상 합산배제주택에 해당하지 아니하며, 지방세관계법상 재산세 특례 및 감면은 없음)","b":null,"bs":"없음","img":[],"ch":["甲의 주택에 대한 재산세는 주택별로 표준세율을 적용한다.","甲의 상가건물에 대한 재산세는 시가표준액에 법령이 정하는 공정시장가액비율을 곱하여 산정한 가액을 과세표준으로 하여 비례세율로 과세한다.","甲의 주택분 종합부동산세액의 결정세액은 주택분 종합부동산세액에서 '(주택의 공시가격 합산액 - 9억원) ×종합부동산세 공정시장가액비율 × 재산세 표준세율'의 산식에 따라 산정한 재산세액을 공제하여 계산한다.","甲의 상가건물에 대해서는 종합부동산세를 과세하지 아니한다.","甲의 주택에 대한 종합부동산세는 甲이 보유한 주택의 공시가격을 합산한 금액에서 9억원을 공제한 금액에 공정시장가액비율(100분의 60)을 곱한 금액(영보다 작은 경우는 영)을 과세표준으로 하여 누진세율로 과세한다."],"a":[3],"p":23,"L":"세2-3","S":["세3-1"],"m":"","f":{"판정":"수정","요약":"종부세 주택 공제금액 6억원→9억원(종합부동산세법 제8조제1항제3호), 공정시장가액비율 100분의 95→100분의 60(시행령 제2조의4) 반영해 옳은 선지 ⑤ 수정, ③은 공제금액만 현행화(재산세 공정시장가액비율 누락으로 여전히 틀림, 시행령 제4조의3), 귀속연도 표기 삭제","수정":[{"위치":"발문","원문":"甲의 2021년 귀속 재산세 및 종합부동산세에 관한 설명으로 틀린 것은?","수정문":"甲의 재산세 및 종합부동산세에 관한 설명으로 틀린 것은?","근거":"종합부동산세법 제8조","바뀐점":"귀속연도(2021년) 삭제, 현행 법령 기준 문항으로 전환"},{"위치":"선지3","원문":"甲의 주택분 종합부동산세액의 결정세액은 주택분 종합부동산세액에서 '(주택의 공시가격 합산액 - 6억원) ×종합부동산세 공정시장가액비율 × 재산세 표준세율'의 산식에 따라 산정한 재산세액을 공제하여 계산한다.","수정문":"甲의 주택분 종합부동산세액의 결정세액은 주택분 종합부동산세액에서 '(주택의 공시가격 합산액 - 9억원) ×종합부동산세 공정시장가액비율 × 재산세 표준세율'의 산식에 따라 산정한 재산세액을 공제하여 계산한다.","근거":"종합부동산세법 제8조제1항제3호, 시행령 제4조의3제1항","바뀐점":"공제금액 6억원→9억원(재산세 공정시장가액비율이 빠진 산식이라 틀린 선지 유지)"},{"위치":"선지5","원문":"甲의 주택에 대한 종합부동산세는 甲이 보유한 주택의 공시가격을 합산한 금액에서 6억원을 공제한 금액에 공정시장가액비율(100분의 95)을 곱한 금액(영보다 작은 경우는 영)을 과세표준으로 하여 누진세율로 과세한다.","수정문":"甲의 주택에 대한 종합부동산세는 甲이 보유한 주택의 공시가격을 합산한 금액에서 9억원을 공제한 금액에 공정시장가액비율(100분의 60)을 곱한 금액(영보다 작은 경우는 영)을 과세표준으로 하여 누진세율로 과세한다.","근거":"종합부동산세법 제8조제1항제3호, 제9조제1항제1호, 시행령 제2조의4제1항","바뀐점":"공제 6억원→9억원, 공정시장가액비율 100분의 95(2021년)→100분의 60"}],"정답변경사유":""}},{"i":"32회-2차-114","r":32,"y":2021,"c":2,"g":"2교시","n":34,"q":"종합부동산세법상 1세대 1주택자에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["과세기준일 현재 세대원 중 1인과 그 배우자만이 공동으로 1주택을 소유하고 해당 세대원 및 다른 세대원이 다른 주택을 소유하지 아니한 경우 신청하지 않더라도 공동명의 1주택자를 해당 1주택에 대한 납세의무자로 한다.","합산배제 신고한 ｢근현대문화유산의 보존 및 활용에 관한 법률｣에 따른 등록문화유산에 해당하는 주택은 1세대가 소유한 주택 수에서 제외한다.","1세대가 일반 주택과 합산배제 신고한 임대주택을 각각 1채씩 소유한 경우 해당 일반 주택에 그 주택소유자가 실제 거주하지 않더라도 1세대 1주택자에 해당한다.","1세대 1주택자는 주택의 공시가격을 합산한 금액에서 6억원을 공제한 금액에서 다시 3억원을 공제한 금액에 공정시장가액비율을 곱한 금액을 과세표준으로 한다.","1세대 1주택자에 대하여는 주택분 종합부동산세 산출세액에서 소유자의 연령과 주택 보유기간에 따른 공제액을 공제율 합계 100분의 70의 범위에서 중복하여 공제한다."],"a":[2],"p":32,"L":"세3-1","S":[],"m":"","f":{"판정":"수정","요약":"「문화재보호법」 국가등록문화재 → 「근현대문화유산의 보존 및 활용에 관한 법률」 등록문화유산 명칭 반영(시행령 제2조의3제2항제3호·제4조제1항제8호). ①(공동명의 특례는 신청 필요, 제10조의2), ③(일반주택 실거주 요건), ⑤(한도 100분의 80) 틀림 동일. ④는 옛 공제구조(6억+3억)로 현행(12억)과도 달라 틀림 유지","수정":[{"위치":"선지2","원문":"합산배제 신고한 ｢문화재보호법｣에 따른 국가등록문화재에 해당하는 주택은 1세대가 소유한 주택 수에서 제외한다.","수정문":"합산배제 신고한 ｢근현대문화유산의 보존 및 활용에 관한 법률｣에 따른 등록문화유산에 해당하는 주택은 1세대가 소유한 주택 수에서 제외한다.","근거":"종합부동산세법 시행령 제2조의3제2항제3호, 제4조제1항제8호","바뀐점":"법령명·명칭 변경(문화재보호법 국가등록문화재 → 근현대문화유산법 등록문화유산)"}],"정답변경사유":""}},{"i":"32회-2차-115","r":32,"y":2021,"c":2,"g":"2교시","n":35,"q":"2021년 귀속 토지분 종합부동산세에 관한 설명으로 옳은 것은? (단, 감면과 비과세와 지방세특례제한법 또는 조세특례제한법은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["재산세 과세대상 중 분리과세대상 토지는 종합부동산세 과세대상이다.","종합부동산세의 분납은 허용되지 않는다.","종합부동산세의 물납은 허용되지 않는다.","납세자에게 부정행위가 없으며 특례제척기간에 해당하지 않는 경우 원칙적으로 납세의무 성립일부터 3년이 지나면 종합부동산세를 부과할 수 없다.","별도합산과세대상인 토지의 재산세로 부과된 세액이 세부담 상한을 적용받는 경우 그 상한을 적용받기 전의 세액을 별도합산과세대상 토지분 종합부동산세액에서 공제한다."],"a":[3],"p":40,"L":"세3-1","S":[],"m":"","f":null},{"i":"32회-2차-116","r":32,"y":2021,"c":2,"g":"2교시","n":36,"q":"다음은 거주자 甲의 상가건물 양도소득세 관련 자료이다. 이 경우 양도차익은? (단, 양도차익을 최소화하는 방향으로 필요경비를 선택하고, 부가가치세는 고려하지 않음)","b":"(1) 취득 및 양도 내역 실지거래가액 기준시가 거래일자 양도당시 5억원 4억원 2021. 4. 30. 취득당시 확인 불가능 2억원 2020. 3. 7.\n(2) 자본적지출액 및 소개비: 2억 6천만원(세금계산서 수취함)\n(3) 주어진 자료 외에는 고려하지 않는다.","bs":"글자","img":[],"ch":["2억원","2억 4천만원","2억 4천4백만원","2억 5천만원","2억 6천만원"],"a":[2],"p":25,"L":"세3-2","S":[],"m":"","f":null},{"i":"32회-2차-117","r":32,"y":2021,"c":2,"g":"2교시","n":37,"q":"소득세법상 양도소득세 과세대상 자산의 양도 또는 취득의 시기로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["｢도시개발법｣에 따라 교부받은 토지의 면적이 환지처분에 의한 권리면적보다 증가 또는 감소된 경우: 환지처분의 공고가 있은 날","재정경제부령이 정하는 장기할부조건의 경우: 소유권이 전등기(등록 및 명의개서를 포함) 접수일ㆍ인도일 또는 사용수익일 중 빠른 날","건축허가를 받지 않고 자기가 건설한 건축물의 경우: 그 사실상의 사용일","｢민법｣제245조 제1항의 규정에 의하여 부동산의 소유권을 취득하는 경우: 당해 부동산의 점유를 개시한 날","대금을 청산한 날이 분명하지 아니한 경우: 등기부ㆍ등록부 또는 명부 등에 기재된 등기ㆍ등록접수일 또는 명의개서일"],"a":[1],"p":25,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"시행령 제162조제1항제3호 부령 명칭 '기획재정부령'→'재정경제부령' 반영. ①(증감 면적은 환지처분 공고일의 다음 날) 틀림 동일","수정":[{"위치":"선지2","원문":"기획재정부령이 정하는 장기할부조건의 경우: 소유권이 전등기(등록 및 명의개서를 포함) 접수일ㆍ인도일 또는 사용수익일 중 빠른 날","수정문":"재정경제부령이 정하는 장기할부조건의 경우: 소유권이 전등기(등록 및 명의개서를 포함) 접수일ㆍ인도일 또는 사용수익일 중 빠른 날","근거":"소득세법 시행령 제162조제1항제3호","바뀐점":"부령 명칭 기획재정부령→재정경제부령"}],"정답변경사유":""}},{"i":"32회-2차-118","r":32,"y":2021,"c":2,"g":"2교시","n":38,"q":"거주자 甲은 2015년에 국외에 1채의 주택을 미화 1십만 달러(취득자금 중 일부 외화 차입)에 취득하였고, 2021년에 동 주택을 미화 2십만 달러에 양도하였다. 이 경우 소득세법상 설명으로 틀린 것은? (단, 甲은 해당 자산의 양도일까지 계속 5년 이상 국내에 주소를 둠)","b":null,"bs":"없음","img":[],"ch":["甲의 국외주택에 대한 양도차익은 양도가액에서 취득가액과 필요경비개산공제를 차감하여 계산한다.","甲의 국외주택 양도로 발생하는 소득이 환율변동으로 인하여 외화차입금으로부터 발생하는 환차익을 포함하고 있는 경우에는 해당 환차익을 양도소득의 범위에서 제외한다.","甲의 국외주택 양도에 대해서는 해당 과세기간의 양도소득금액에서 연 250만원을 공제한다.","甲은 국외주택을 3년 이상 보유하였음에도 불구하고 장기보유특별공제액은 공제하지 아니한다.","甲은 국외주택의 양도에 대하여 양도소득세의 납세의무가 있다."],"a":[1],"p":27,"L":"세3-2","S":[],"m":"","f":null},{"i":"32회-2차-119","r":32,"y":2021,"c":2,"g":"2교시","n":39,"q":"소득세법상 미등기양도제외자산을 모두 고른 것은?","b":"ㄱ. 양도소득세 비과세요건을 충족한 1세대 1주택으로서 ｢건축법｣에 따른 건축허가를 받지 아니하여 등기가 불가능한 자산\nㄴ. 법원의 결정에 의하여 양도 당시 그 자산의 취득에 관한 등기가 불가능한 자산\nㄷ. ｢도시개발법｣에 따른 도시개발사업이 종료되지 아니하여 토지 취득등기를 하지 아니하고 양도하는 토지","bs":"글자","img":[],"ch":["ㄱ","ㄴ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[5],"p":31,"L":"세3-2","S":[],"m":"","f":null},{"i":"32회-2차-120","r":32,"y":2021,"c":2,"g":"2교시","n":40,"q":"소득세법상 배우자 간 증여재산의 이월과세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["이월과세를 적용하는 경우 거주자가 배우자로부터 증여받은 자산에 대하여 납부한 증여세를 필요경비에 산입하지 아니한다.","이월과세를 적용받은 자산의 보유기간은 증여한 배우자가 그 자산을 증여한 날을 취득일로 본다.","거주자가 양도일부터 소급하여 10년 이내에 그 배우자(양도 당시 사망으로 혼인관계가 소멸된 경우 포함)로부터 증여받은 토지를 양도할 경우에 이월과세를 적용한다.","거주자가 사업인정고시일부터 소급하여 2년 이전에 배우자로부터 증여받은 경우로서 ｢공익사업을 위한 토지 등의 취득 및 보상에 관한 법률｣에 따라 수용된 경우에는 이월과세를 적용하지 아니한다.","이월과세를 적용하여 계산한 양도소득결정세액이 이월과세를 적용하지 않고 계산한 양도소득결정세액보다 적은 경우에 이월과세를 적용한다."],"a":[4],"p":24,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"이월과세 기간 5년→10년(소득세법 제97조의2제1항) 반영. ③은 '사망으로 혼인관계 소멸 포함'이 틀려 여전히 틀림, ④ 제97조의2제2항제1호 옳음 동일","수정":[{"위치":"선지3","원문":"거주자가 양도일부터 소급하여 5년 이내에 그 배우자(양도 당시 사망으로 혼인관계가 소멸된 경우 포함)로부터 증여받은 토지를 양도할 경우에 이월과세를 적용한다.","수정문":"거주자가 양도일부터 소급하여 10년 이내에 그 배우자(양도 당시 사망으로 혼인관계가 소멸된 경우 포함)로부터 증여받은 토지를 양도할 경우에 이월과세를 적용한다.","근거":"소득세법 제97조의2제1항","바뀐점":"이월과세 적용기간 5년→10년(사망 소멸은 제외되므로 틀린 선지 유지)"}],"정답변경사유":""}},{"i":"33회-2차-105","r":33,"y":2022,"c":2,"g":"2교시","n":25,"q":"지방세기본법상 이의신청과 심판청구에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 통고처분은 이의신청 또는 심판청구의 대상이 되는 처분에 포함된다.\nㄴ. 이의신청인은 신청 또는 청구 금액이 8백만원인 경우에는 그의 배우자를 대리인으로 선임할 수 있다.\nㄷ. 보정기간은 결정기간에 포함하지 아니한다.\nㄹ. 이의신청을 거치지 아니하고 바로 심판청구를 할 수는 없다.","bs":"글자","img":[],"ch":["ㄱ","ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":[4],"p":30,"L":"세1-1","S":[],"m":"","f":null},{"i":"33회-2차-106","r":33,"y":2022,"c":2,"g":"2교시","n":26,"q":"지방세기본법상 서류의 송달에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["연대납세의무자에게 납세의 고지에 관한 서류를 송달할 때에는 연대납세의무자 모두에게 각각 송달하여야 한다.","기한을 정하여 납세고지서를 송달하였더라도 서류가 도달한 날부터 10일이 되는 날에 납부기한이 되는 경우 지방자치단체의 징수금의 납부기한은 해당 서류가 도달한 날부터 14일이 지난 날로 한다.","납세관리인이 있을 때에는 납세의 고지와 독촉에 관한 서류는 그 납세관리인의 주소 또는 영업소에 송달한다.","교부에 의한 서류송달의 경우에 송달할 장소에서 서류를 송달받아야 할 자를 만나지 못하였을 때에는 그의 사용인으로서 사리를 분별할 수 있는 사람에게 서류를 송달할 수 있다.","서류송달을 받아야 할 자의 주소 또는 영업소가 분명하지 아니한 경우에는 서류의 주요 내용을 공고한 날부터 14일이 지나면 서류의 송달이 된 것으로 본다."],"a":[2],"p":33,"L":"세1-1","S":[],"m":"","f":null},{"i":"33회-2차-107","r":33,"y":2022,"c":2,"g":"2교시","n":27,"q":"지방세법상 재산세 과세대상의 구분에 있어 주거용과 주거 외의 용도를 겸하는 건물 등에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 1동(棟)의 건물이 주거와 주거 외의 용도로 사용되고 있는 경우에는 주거용으로 사용되는 부분만을 주택으로 본다.\nㄴ. 1구(構)의 건물이 주거와 주거 외의 용도로 사용되고 있는 경우 주거용으로 사용되는 면적이 전체의 100분의 60인 경우에는 주택으로 본다.\nㄷ. 주택의 부속토지의 경계가 명백하지 아니한 경우에는 그 주택의 바닥면적의 10배에 해당하는 토지를 주택의 부속토지로 한다.","bs":"글자","img":[],"ch":["ㄱ","ㄷ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[5],"p":35,"L":"세2-3","S":[],"m":"","f":null},{"i":"33회-2차-108","r":33,"y":2022,"c":2,"g":"2교시","n":28,"q":"지방세법상 재산세에 관한 설명으로 틀린 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["재산세 과세기준일 현재 공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 때에는 공부상 소유자는 재산세를 납부할 의무가 있다.","지방자치단체가 1년 이상 공용으로 사용하는 재산에 대하여는 소유권의 유상이전을 약정한 경우로서 그 재산을 취득하기 전에 미리 사용하는 경우 재산세를 부과하지 아니한다.","재산세 과세기준일 현재 소유권의 귀속이 분명하지 아니하여 사실상의 소유자를 확인할 수 없는 경우에는 그 사용자가 재산세를 납부할 의무가 있다.","재산세의 납기는 토지의 경우 매년 9월 16일부터 9월 30일까지이며, 건축물의 경우 매년 7월 16일부터 7월 31일까지이다.","재산세의 납기에도 불구하고 지방자치단체의 장은 과세대상 누락, 위법 또는 착오 등으로 인하여 이미 부과한 세액을 변경하거나 수시부과하여야 할 사유가 발생하면 수시로 부과ㆍ징수할 수 있다."],"a":[2],"p":38,"L":"세2-3","S":[],"m":"","f":null},{"i":"33회-2차-109","r":33,"y":2022,"c":2,"g":"2교시","n":29,"q":"종합부동산세법상 주택에 대한 과세 및 납세지에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["납세의무자가 법인이며 3주택 이상을 소유한 경우 소유한 주택 수에 따라 과세표준에 1.2 %∼6 %의 세율을 적용하여 계산한 금액을 주택분 종합부동산세액으로 한다.","납세의무자가 법인으로 보지 않는 단체인 경우 주택에 대한 종합부동산세 납세지는 해당 주택의 소재지로 한다.","과세표준 합산의 대상에 포함되지 않는 주택을 보유한 납세의무자는 해당 연도 10월 16일부터 10월 31일까지 관할세무서장에게 해당 주택의 보유현황을 신고하여야 한다.","종합부동산세 과세대상 1세대 1주택자로서 과세기준일 현재 해당 주택을 12년 보유한 자의 보유기간별 세액공제에 적용되는 공제율은 100분의 50이다.","과세기준일 현재 주택분 재산세의 납세의무자는 종합부동산세를 납부할 의무가 있다."],"a":[5],"p":33,"L":"세3-1","S":[],"m":"","f":null},{"i":"33회-2차-110","r":33,"y":2022,"c":2,"g":"2교시","n":30,"q":"종합부동산세법상 토지 및 주택에 대한 과세와 부과ㆍ징수에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["종합합산과세대상인 토지에 대한 종합부동산세의 세액은 과세표준에 1 %∼5 %의 세율을 적용하여 계산한 금액으로 한다.","종합부동산세로 납부해야 할 세액이 200만원인 경우 관할세무서장은 그 세액의 일부를 납부기한이 지난 날부터 6개월 이내에 분납하게 할 수 있다.","관할세무서장이 종합부동산세를 징수하려면 납부기간 개시 5일 전까지 주택분과 토지분을 합산한 과세표준과 세액을 납부고지서에 기재하여 발급하여야 한다.","종합부동산세를 신고납부방식으로 납부하고자 하는 납세의무자는 종합부동산세의 과세표준과 세액을 해당 연도 12월 1일부터 12월 15일까지 관할세무서장에게 신고하여야 한다.","별도합산과세대상인 토지에 대한 종합부동산세의 세액은 과세표준에 0.5 %∼0.8 %의 세율을 적용하여 계산한 금액으로 한다."],"a":[4],"p":31,"L":"세3-1","S":[],"m":"","f":null},{"i":"33회-2차-111","r":33,"y":2022,"c":2,"g":"2교시","n":31,"q":"다음은 거주자 甲이 소유하고 있는 상가건물 임대에 관한 자료이다. 부동산임대업의 사업소득을 장부에 기장하여 신고하는 경우 2022년도 부동산임대업의 총 수입금액은? (단, 법령에 따른 적격증명서류를 수취ㆍ보관하고 있으며, 주어진 조건 이외에는 고려하지 않음)","b":"○ 임대기간: 2022. 1. 1. ∼ 2023. 12. 31.\n○ 임대계약 내용: 월임대료 1,000,000원 임대보증금 500,000,000원\n○ 임대부동산(취득일자: 2021. 1. 23.)\n- 건물 취득가액: 200,000,000원\n- 토지 취득가액: 300,000,000원\n○ 재정경제부령으로 정하는 이자율: 연 6 %\n○ 임대보증금 운용수익: 수입이자 1,000,000원 유가증권처분이익 2,000,000원","bs":"글자","img":[],"ch":["18,000,000원","29,000,000원","30,000,000원","39,000,000원","40,000,000원"],"a":[2],"p":20,"L":"세3-3","S":[],"m":"","f":{"판정":"수정","요약":"간주임대료 이자율 위임 부령 명칭 '기획재정부령'→'재정경제부령'(소득세법 시행령 제53조제3항) 반영. 계산: 월세 1,200만원 + (5억−건물 2억)×6%−수입이자 100만원 = 2,900만원 현행 동일","수정":[{"위치":"보기","원문":"○ 기획재정부령으로 정하는 이자율: 연 6 %","수정문":"○ 재정경제부령으로 정하는 이자율: 연 6 %","근거":"소득세법 시행령 제53조제3항제2호","바뀐점":"부령 명칭 기획재정부령→재정경제부령"}],"정답변경사유":""}},{"i":"33회-2차-112","r":33,"y":2022,"c":2,"g":"2교시","n":32,"q":"거주자 甲의 매매(양도일: 2022. 5. 1.)에 의한 등기된 토지 취득 및 양도에 관한 다음의 자료를 이용하여 양도소득세 과세표준을 계산하면? (단, 법령에 따른 적격증명서류를 수취ㆍ보관하고 있으며, 주어진 조건 이외에는 고려하지 않음)","b":"항목 기준시가 실지거래가액 양도가액 40,000,000원 67,000,000원 취득가액 35,000,000원 42,000,000원\n○ 양도비용: 4,000,000원 추가사항\n○ 보유기간: 2년","bs":"글자","img":[],"ch":["18,500,000원","19,320,000원","19,740,000원","21,000,000원","22,500,000원"],"a":[1],"p":25,"L":"세3-2","S":[],"m":"","f":null},{"i":"33회-2차-113","r":33,"y":2022,"c":2,"g":"2교시","n":33,"q":"소득세법상 거주자의 양도소득세 신고납부에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["건물을 신축하고 그 취득일부터 3년 이내에 양도하는 경우로서 감정가액을 취득가액으로 하는 경우에는 그 감정가액의 100분의 3에 해당하는 금액을 양도소득 결정세액에 가산한다.","공공사업의 시행자에게 수용되어 발생한 양도소득세액이 2천만원을 초과하는 경우 납세의무자는 물납을 신청할 수 있다.","과세표준 예정신고와 함께 납부하는 때에는 산출세액에서 납부할 세액의 100분의 5에 상당하는 금액을 공제한다.","예정신고납부할 세액이 1천 5백만원인 자는 그 세액의 100분의 50의 금액을 납부기한이 지난 후 2개월 이내에 분할납부할 수 있다.","납세의무자가 법정신고기한까지 양도소득세의 과세표준신고를 하지 아니한 경우(부정행위로 인한 무신고는 제외)에는 그 무신고납부세액에 100분의 20을 곱한 금액을 가산세로 한다."],"a":[5],"p":32,"L":"세3-2","S":[],"m":"","f":null},{"i":"33회-2차-114","r":33,"y":2022,"c":2,"g":"2교시","n":34,"q":"거주자 甲은 2016. 10. 20. 취득한 토지(취득가액 1억원, 등기함)를 동생인 거주자 乙(특수관계인임)에게 2019. 10. 1. 증여(시가 3억원, 등기함)하였다. 乙은 해당 토지를 2022. 6. 30. 특수관계가 없는 丙에게 양도(양도가액 10억원)하였다. 양도소득은 乙에게 실질적으로 귀속되지 아니하고, 乙의 증여세와 양도소득세를 합한 세액이 甲이 직접 양도하는 경우로 보아 계산한 양도소득세보다 적은 경우에 해당한다. 소득세법상 양도소득세 납세의무에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["乙이 납부한 증여세는 양도차익 계산 시 필요경비에 산입한다.","양도차익 계산 시 취득가액은 甲의 취득 당시를 기준으로 한다.","양도소득세에 대해서는 甲과 乙이 연대하여 납세의무를 진다.","甲은 양도소득세 납세의무자이다.","양도소득세 계산 시 보유기간은 甲의 취득일부터 乙의 양도일까지의 기간으로 한다."],"a":[1],"p":29,"L":"세3-2","S":[],"m":"","f":null},{"i":"33회-2차-115","r":33,"y":2022,"c":2,"g":"2교시","n":35,"q":"지방세법상 취득세의 부과ㆍ징수에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["취득세의 징수는 보통징수의 방법으로 한다.","상속으로 취득세 과세물건을 취득한 자는 상속개시일부터 60일 이내에 산출한 세액을 신고하고 납부하여야 한다.","신고ㆍ납부기한 이내에 재산권과 그 밖의 권리의 취득ㆍ이전에 관한 사항을 공부에 등기하거나 등록(등재 포함)하려는 경우에는 등기 또는 등록 신청서를 등기ㆍ등록관서에 접수하는 날까지 취득세를 신고ㆍ납부하여야 한다.","취득세 과세물건을 취득한 후에 그 과세물건이 중과 세율의 적용대상이 되었을 때에는 중과 세율을 적용하여 산출한 세액에서 이미 납부한 세액(가산세 포함)을 공제한 금액을 세액으로 하여 신고ㆍ납부하여야 한다.","법인의 취득당시가액을 증명할 수 있는 장부가 없는 경우 지방자치단체의 장은 그 산출된 세액의 100분의 20을 징수하여야 할 세액에 가산한다."],"a":[3],"p":31,"L":"세2-1","S":[],"m":"","f":null},{"i":"33회-2차-116","r":33,"y":2022,"c":2,"g":"2교시","n":36,"q":"소득세법상 부동산임대업에서 발생한 소득에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["해당 과세기간의 주거용 건물 임대업을 제외한 부동산임대업에서 발생한 결손금은 그 과세기간의 종합소득과세표준을 계산할 때 공제하지 않는다.","사업소득에 부동산임대업에서 발생한 소득이 포함되어 있는 사업자는 그 소득별로 구분하여 회계처리하여야 한다.","3주택(주택 수에 포함되지 않는 주택 제외) 이상을 소유한 거주자가 주택과 주택부수토지를 임대(주택부수토지만 임대하는 경우 제외)한 경우에는 법령으로 정하는 바에따라 계산한 금액(간주임대료)을 총수입금액에 산입한다.","간주임대료 계산 시 3주택 이상 여부 판정에 있어 주택수에 포함되지 않는 주택이란 주거의 용도로만 쓰이는 면적이 1호 또는 1세대당 40 m2 이하인 주택으로서 해당 과세기간의 기준시가가 2억원 이하인 주택을 말한다.","해당 과세기간에 분리과세 주택임대소득이 있는 거주자(종합소득과세표준이 없거나 결손금이 있는 거주자 포함)는 그 종합소득 과세표준을 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지 신고하여야 한다."],"a":[3],"p":19,"L":"세3-3","S":[],"m":"","f":null},{"i":"33회-2차-117","r":33,"y":2022,"c":2,"g":"2교시","n":37,"q":"지방세법상 등록에 대한 등록면허세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["채권금액으로 과세액을 정하는 경우에 일정한 채권금액이 없을 때에는 채권의 목적이 된 것의 가액 또는 처분의 제한의 목적이 된 금액을 그 채권금액으로 본다.","같은 채권의 담보를 위하여 설정하는 둘 이상의 저당권을 등록하는 경우에는 이를 하나의 등록으로 보아 그 등록에 관계되는 재산을 처음 등록하는 등록관청 소재지를 납세지로 한다.","부동산 등기에 대한 등록면허세의 납세지가 분명하지 아니한 경우에는 등록관청 소재지를 납세지로 한다.","지상권 등기의 경우에는 특별징수의무자가 징수할 세액을 납부기한까지 부족하게 납부하면 특별징수의무자에게 과소납부분 세액의 100분의 1을 가산세로 부과한다.","지방자치단체의 장은 채권자대위자의 부동산의 등기에 대한 등록면허세 신고납부가 있는 경우 납세의무자에게 그 사실을 즉시 통보하여야 한다."],"a":[4],"p":33,"L":"세2-2","S":[],"m":"","f":null},{"i":"33회-2차-118","r":33,"y":2022,"c":2,"g":"2교시","n":38,"q":"소득세법상 거주자의 양도소득세 징수와 환급에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["과세기간별로 이미 납부한 확정신고세액이 관할세무서장이 결정한 양도소득 총결정세액을 초과한 경우 다른 국세에 충당할 수 없다.","양도소득과세표준과 세액을 결정 또는 경정한 경우 관할세무서장이 결정한 양도소득 총결정세액이 이미 납부한 확정신고세액을 초과할 때에는 그 초과하는 세액을 해당 거주자에게 알린 날부터 30일 이내에 징수한다.","양도소득세 과세대상 건물을 양도한 거주자는 부담부증여의 채무액을 양도로 보는 경우 예정신고 없이 확정신고를 하여야 한다.","양도소득세 납세의무의 확정은 납세의무자의 신고에 의하지 않고 관할세무서장의 결정에 의한다.","이미 납부한 확정신고세액이 관할세무서장이 결정한 양도소득 총결정세액을 초과할 때에는 해당 결정일부터 90일 이내에 환급해야 한다."],"a":[2],"p":23,"L":"세3-2","S":[],"m":"","f":null},{"i":"33회-2차-119","r":33,"y":2022,"c":2,"g":"2교시","n":39,"q":"소득세법 시행령 제155조 '1세대 1주택의 특례'에 관한 조문의 내용이다. ( )에 들어갈 숫자로 옳은 것은?","b":"○ 영농의 목적으로 취득한 귀농주택으로서 수도권 밖의 지역 중 면지역에 소재하는 주택과 일반주택을 국내에 각각 1개씩 소유하고 있는 1세대가 귀농주택을 취득한 날부터 ( ㄱ )년 이내에 일반주택을 양도하는 경우에는 국내에 1개의 주택을 소유하고 있는 것으로 보아 제154조 제1항을 적용한다.\n○ 취학 등 부득이한 사유로 취득한 수도권 밖에 소재하는 주택과 일반주택을 국내에 각각 1개씩 소유하고 있는 1세대가 부득이한 사유가 해소된 날부터 ( ㄴ )년 이내에 일반주택을 양도하는 경우에는 국내에 1개의 주택을 소유하고 있는 것으로 보아 제154조 제1항을 적용한다.\n○ 1주택을 보유하는 자가 1주택을 보유하는 자와 혼인함으로써 1세대가 2주택을 보유하게 되는 경우 혼인한 날부터 ( ㄷ )년 이내에 먼저 양도하는 주택은 이를 1세대 1주택으로 보아 제154조 제1항을 적용한다.","bs":"글자","img":[],"ch":["ㄱ: 2, ㄴ: 2, ㄷ: 5","ㄱ: 2, ㄴ: 3, ㄷ: 10","ㄱ: 3, ㄴ: 2, ㄷ: 5","ㄱ: 5, ㄴ: 3, ㄷ: 10","ㄱ: 5, ㄴ: 3, ㄷ: 5"],"a":[4],"p":32,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"혼인합가 특례기간 5년→10년(시행령 제155조제5항, 2024.11.12 개정) → 현행 정답 조합(5, 3, 10)이 기존 ⑤와 같아지므로 ④를 현행 조합으로, ⑤를 옛 조합으로 바꿔 정답 번호 ④ 유지. 귀농주택 5년(제7항 단서)·부득이한 사유 3년(제8항) 동일","수정":[{"위치":"선지4","원문":"ㄱ: 5, ㄴ: 3, ㄷ: 5","수정문":"ㄱ: 5, ㄴ: 3, ㄷ: 10","근거":"소득세법 시행령 제155조제5항·제7항·제8항","바뀐점":"혼인한 날부터 5년→10년"},{"위치":"선지5","원문":"ㄱ: 5, ㄴ: 3, ㄷ: 10","수정문":"ㄱ: 5, ㄴ: 3, ㄷ: 5","근거":"소득세법 시행령 제155조제5항","바뀐점":"현행 정답 조합이 ④로 이동했으므로 중복을 피해 오답 조합으로 교체"}],"정답변경사유":""}},{"i":"33회-2차-120","r":33,"y":2022,"c":2,"g":"2교시","n":40,"q":"지방세법상 취득세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["건축물 중 부대설비에 속하는 부분으로서 그 주체구조부와 하나가 되어 건축물로서의 효용가치를 이루고 있는 것에 대하여는 주체구조부 취득자 외의 자가 가설한 경우에도 주체구조부의 취득자가 함께 취득한 것으로 본다.","세대별 소유주택 수에 따른 중과 세율을 적용함에 있어 주택으로 재산세를 과세하는 오피스텔(2022년 취득)은 해당 오피스텔을 소유한 자의 주택 수에 가산하지 아니한다.","납세의무자가 토지의 지목을 사실상 변경한 후 산출세액에 대한 신고를 하지 아니하고 그 토지를 매각하는 경우에는 산출세액에 100분의 80을 가산한 금액을 세액으로 하여 징수한다.","공사현장사무소 등 임시건축물의 취득에 대하여는 그 존속기간에 관계없이 취득세를 부과하지 아니한다.","토지를 취득한 자가 취득한 날부터 1년 이내에 그에 인접한 토지를 취득한 경우 그 취득가액이 100만원일 때에는 취득세를 부과하지 아니한다."],"a":[1],"p":40,"L":"세2-1","S":[],"m":"","f":null},{"i":"34회-2차-105","r":34,"y":2023,"c":2,"g":"2교시","n":25,"q":"국세기본법령상 국세의 부과제척기간에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["납세자가 「조세범 처벌법」에 따른 사기나 그 밖의 부정한 행위로 종합소득세를 포탈하는 경우(역외거래 제외) 그 국세를 부과할 수 있는 날부터 15년을 부과제척기간으로 한다.","지방국세청장은 「행정소송법」에 따른 소송에 대한 판결이 확정된 경우 그 판결이 확정된 날부터 2년이 지나기전까지 경정이나 그 밖에 필요한 처분을 할 수 있다.","세무서장은 「감사원법」에 따른 심사청구에 대한 결정에 의하여 명의대여 사실이 확인되는 경우에는 당초의 부과처분을 취소하고 그 결정이 확정된 날부터 1년 이내에 실제로 사업을 경영한 자에게 경정이나 그 밖에 필요한 처분을 할 수 있다.","종합부동산세의 경우 부과제척기간의 기산일은 과세표준과 세액에 대한 신고기한의 다음 날이다.","납세자가 법정신고기한까지 과세표준신고서를 제출하지 아니한 경우(역외거래 제외)에는 해당 국세를 부과할 수 있는 날부터 10년을 부과제척기간으로 한다."],"a":[3],"p":27,"L":"세1-1","S":[],"m":"","f":null},{"i":"34회-2차-106","r":34,"y":2023,"c":2,"g":"2교시","n":26,"q":"국세 및 지방세의 연대납세의무에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공동주택의 공유물에 관계되는 지방자치단체의 징수금은 공유자가 연대하여 납부할 의무를 진다.","공동으로 소유한 자산에 대한 양도소득금액을 계산하는 경우에는 해당 자산을 공동으로 소유하는 공유자가 그 양도소득세를 연대하여 납부할 의무를 진다.","공동사업에 관한 소득금액을 계산하는 경우(주된 공동사업자에게 합산과세되는 경우 제외)에는 해당 공동사업자가 그 종합소득세를 연대하여 납부할 의무를 진다.","상속으로 인하여 단독주택을 상속인이 공동으로 취득하는 경우에는 상속인 각자가 상속받는 취득물건을 취득한 것으로 보고, 공동상속인이 그 취득세를 연대하여 납부할 의무를 진다.","어느 연대납세의무자에 대하여 소멸시효가 완성된 때에도 다른 연대납세의무자의 납세의무에는 영향을 미치지 아니한다."],"a":[4],"p":24,"L":"세1-1","S":[],"m":"","f":null},{"i":"34회-2차-107","r":34,"y":2023,"c":2,"g":"2교시","n":27,"q":"지방세법령상 취득세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["건축물 중 조작 설비에 속하는 부분으로서 그 주체구조부와 하나가 되어 건축물로서의 효용가치를 이루고 있는 것에 대하여는 주체구조부 취득자 외의 자가 가설한 경우에도 주체구조부의 취득자가 함께 취득한 것으로 본다.","「도시개발법」에 따른 환지방식에 의한 도시개발사업의 시행으로 토지의 지목이 사실상 변경됨으로써 그 가액이 증가한 경우에는 그 환지계획에 따라 공급되는 환지는 사업시행자가, 체비지 또는 보류지는 조합원이 각각 취득한 것으로 본다.","경매를 통하여 배우자의 부동산을 취득하는 경우에는 유상으로 취득한 것으로 본다.","형제자매인 증여자의 채무를 인수하는 부동산의 부담부증여의 경우에는 그 채무액에 상당하는 부분은 부동산을 유상으로 취득하는 것으로 본다.","부동산의 승계취득은 「민법」 등 관계 법령에 따른 등기를 하지 아니한 경우라도 사실상 취득하면 취득한 것으로 보고 그 부동산의 양수인을 취득자로 한다."],"a":[2],"p":32,"L":"세2-1","S":[],"m":"","f":null},{"i":"34회-2차-108","r":34,"y":2023,"c":2,"g":"2교시","n":28,"q":"지방세기본법령 및 지방세법령상 취득세 납세의무의 성립에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["상속으로 인한 취득의 경우에는 상속개시일이 납세의무의 성립시기이다.","부동산의 증여계약으로 인한 취득에 있어서 소유권이전등기를 하지 않고 계약일부터 60일 이내에 공증받은 공정증서로 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 않는다.","유상승계취득의 경우 사실상의 잔금지급일을 확인할 수 있는 때에는 사실상의 잔금지급일(그 전에 등기한 경우에는 등기일)이 납세의무의 성립시기이다.","「민법」에 따른 이혼시 재산분할로 인한 부동산 취득의 경우에는 취득물건의 등기일이 납세의무의 성립시기이다.","「도시 및 주거환경정비법」에 따른 재건축조합이 재건축사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 같은 법에 따른 준공인가 고시일의 다음 날이 납세의무의 성립시기이다."],"a":[5],"p":28,"L":"세2-1","S":[],"m":"","f":{"판정":"수정","요약":"공식 복수정답(③⑤). ③은 '사실상 잔금지급일 전에 등기한 경우 등기일'(시행령 제20조제14항)을 빠뜨린 문언 때문에 틀림 처리됐으므로 조문 문언을 넣어 옳은 문장으로 고치면 ⑤(재건축 비조합원 토지는 소유권이전 고시일 다음 날, 제20조제7항)만 틀림 → 단일정답 ⑤. ② 무상취득 해제서류 기한은 '취득일이 속하는 달의 말일부터 3개월'로 바뀌었으나 60일 이내 공증이면 충족해 옳음 유지","수정":[{"위치":"선지3","원문":"유상승계취득의 경우 사실상의 잔금지급일을 확인할 수 있는 때에는 사실상의 잔금지급일이 납세의무의 성립시기이다.","수정문":"유상승계취득의 경우 사실상의 잔금지급일을 확인할 수 있는 때에는 사실상의 잔금지급일(그 전에 등기한 경우에는 등기일)이 납세의무의 성립시기이다.","근거":"지방세법 시행령 제20조제2항·제14항","바뀐점":"잔금지급일 전 등기 시 등기일을 취득일로 보는 조문을 반영해 복수정답 원인 제거"}],"정답변경사유":"확정답안 ③⑤ 복수정답의 원인(③ 문언이 등기 선행 예외를 빠뜨림)을 현행 시행령 제20조제14항 문언으로 한 곳 보완 → 단일정답 ⑤"}},{"i":"34회-2차-109","r":34,"y":2023,"c":2,"g":"2교시","n":29,"q":"종합부동산세법령상 주택의 과세표준 계산과 관련한 내용으로 틀린 것은? (단, 2023년 납세의무 성립분임)","b":null,"bs":"없음","img":[],"ch":["대통령령으로 정하는 1세대 1주택자(공동명의 1주택자 제외)의 경우 주택에 대한 종합부동산세의 과세표준은 납세의무자별로 주택의 공시가격을 합산한 금액에서 12억원을 공제한 금액에 100분의 60을 곱한 금액으로 한다. 다만, 그 금액이 영보다 작은 경우에는 영으로 본다.","대통령령으로 정하는 다가구 임대주택으로서 임대기간, 주택의 수, 가격, 규모 등을 고려하여 대통령령으로 정하는 주택은 과세표준 합산의 대상이 되는 주택의 범위에 포함되지 아니하는 것으로 본다.","1주택(주택의 부속토지만을 소유한 경우는 제외)과 다른 주택의 부속토지(주택의 건물과 부속토지의 소유자가 다른 경우의 그 부속토지)를 함께 소유하고 있는 경우는 1세대 1주택자로 본다.","혼인으로 인한 1세대 2주택의 경우 납세의무자가 해당연도 9월 16일부터 9월 30일까지 관할세무서장에게 합산배제를 신청하면 1세대 1주택자로 본다.","2주택을 소유하여 1천분의 27의 세율이 적용되는 법인의 경우 주택에 대한 종합부동산세의 과세표준은 납세의무자별로 주택의 공시가격을 합산한 금액에서 0원을 공제한 금액에 100분의 60을 곱한 금액으로 한다. 다만, 그 금액이 영보다 작은 경우에는 영으로 본다."],"a":[4],"p":21,"L":"세3-1","S":[],"m":"","f":null},{"i":"34회-2차-110","r":34,"y":2023,"c":2,"g":"2교시","n":30,"q":"종합부동산세법령상 종합부동산세의 부과ㆍ징수에 관한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["관할세무서장은 납부하여야 할 종합부동산세의 세액을 결정하여 해당 연도 12월 1일부터 12월 15일까지 부과ㆍ징수한다.","종합부동산세를 신고납부방식으로 납부하고자 하는 납세의무자는 종합부동산세의 과세표준과 세액을 관할세무서장이 결정하기 전인 해당 연도 11월 16일부터 11월 30일까지 관할세무서장에게 신고하여야 한다.","관할세무서장은 종합부동산세로 납부하여야 할 세액이 250만원을 초과하는 경우에는 대통령령으로 정하는 바에 따라 그 세액의 일부를 납부기한이 지난 날부터 6개월 이내에 분납하게 할 수 있다.","관할세무서장은 납세의무자가 과세기준일 현재 1세대 1주택자가 아닌 경우 주택분 종합부동산세액의 납부유예를 허가할 수 없다.","관할세무서장은 주택분 종합부동산세액의 납부가 유예된 납세의무자가 해당 주택을 타인에게 양도하거나 증여하는 경우에는 그 납부유예 허가를 취소하여야 한다."],"a":[2],"p":27,"L":"세3-1","S":[],"m":"","f":null},{"i":"34회-2차-111","r":34,"y":2023,"c":2,"g":"2교시","n":31,"q":"지방세법령상 재산세의 표준세율에 관한 설명으로 틀린 것은? (단, 지방세관계법령상 감면 및 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["법령에서 정하는 고급선박 및 고급오락장용 건축물의 경우 고급선박의 표준세율이 고급오락장용 건축물의 표준세율보다 높다.","특별시 지역에서 「국토의 계획 및 이용에 관한 법률」과 그 밖의 관계 법령에 따라 지정된 주거지역 및 해당 지방자치단체의 조례로 정하는 지역의 대통령령으로 정하는 공장용 건축물의 표준세율은 과세표준의 1천분의 5이다.","주택(법령으로 정하는 1세대 1주택 아님)의 경우 표준세율은 최저 1천분의 1에서 최고 1천분의 4까지 4단계 초과누진세율로 적용한다.","항공기의 표준세율은 1천분의 3으로 법령에서 정하는 고급선박을 제외한 그 밖의 선박의 표준세율과 동일하다.","지방자치단체의 장은 특별한 재정수요나 재해 등의 발생으로 재산세의 세율 조정이 불가피하다고 인정되는 경우 조례로 정하는 바에 따라 표준세율의 100분의 50의 범위에서 가감할 수 있다. 다만, 가감한 세율은 해당연도를 포함하여 3년간 적용한다."],"a":[5],"p":25,"L":"세2-3","S":[],"m":"","f":null},{"i":"34회-2차-112","r":34,"y":2023,"c":2,"g":"2교시","n":32,"q":"지방세법령상 재산세의 부과ㆍ징수에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["주택에 대한 재산세의 경우 해당 연도에 부과ㆍ징수할 세액의 2분의 1은 매년 7월 16일부터 7월 31일까지, 나머지 2분의 1은 9월 16일부터 9월 30일까지를 납기로 한다. 다만, 해당 연도에 부과할 세액이 20만원 이하인 경우에는 조례로 정하는 바에 따라 납기를 9월 16일부터 9월 30일까지로 하여 한꺼번에 부과ㆍ징수할 수 있다.","재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다.","재산세를 징수하려면 토지, 건축물, 주택, 선박 및 항공기로 구분한 납세고지서에 과세표준과 세액을 적어 늦어도 납기개시 5일 전까지 발급하여야 한다.","재산세의 과세기준일은 매년 6월 1일로 한다.","고지서 1장당 재산세로 징수할 세액이 2천원 미만인 경우에는 해당 재산세를 징수하지 아니한다."],"a":[1],"p":31,"L":"세2-3","S":[],"m":"","f":null},{"i":"34회-2차-113","r":34,"y":2023,"c":2,"g":"2교시","n":33,"q":"지방세법령상 등록에 대한 등록면허세가 비과세되는 경우로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지방자치단체조합이 자기를 위하여 받는 등록","무덤과 이에 접속된 부속시설물의 부지로 사용되는 토지로서 지적공부상 지목이 묘지인 토지에 관한 등기","「채무자 회생 및 파산에 관한 법률」 제25조제1항에 따른 등기","대한민국 정부기관의 등록에 대하여 과세하는 외국정부의 등록","등기 담당 공무원의 착오로 인한 주소 등의 단순한 표시변경 등기"],"a":[4],"p":28,"L":"세2-2","S":[],"m":"","f":{"판정":"수정","요약":"지방세법 제26조제2항제1호가 2023.12.29 개정으로 '회사의 정리 또는 특별청산에 관한 법원 촉탁 등기'에서 「채무자 회생 및 파산에 관한 법률」 해당 조항에 따른 등기로 바뀌어 ③ 문언이 현행 비과세 사유와 맞지 않음 → 현행 조문으로 교체(비과세 유지). ④(외국정부 상호주의 과세) 틀림 동일","수정":[{"위치":"선지3","원문":"회사의 정리 또는 특별청산에 관하여 법원의 촉탁으로 인한 등기(법인의 자본금 또는 출자금의 납입, 증자 및 출자전환에 따른 등기 제외)","수정문":"「채무자 회생 및 파산에 관한 법률」 제25조제1항에 따른 등기","근거":"지방세법 제26조제2항제1호","바뀐점":"비과세 사유 문언이 '회사 정리·특별청산 법원 촉탁 등기'에서 채무자회생법 열거 조항(제6조제3항, 제25조제1항~제3항 등)에 따른 등기로 변경"}],"정답변경사유":""}},{"i":"34회-2차-114","r":34,"y":2023,"c":2,"g":"2교시","n":34,"q":"지방세법령상 등록에 대한 등록면허세에 관한 설명으로 틀린 것은? (단, 지방세관계법령상 감면 및 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["같은 등록에 관계되는 재산이 둘 이상의 지방자치단체에 걸쳐 있어 등록면허세를 지방자치단체별로 부과할 수 없을 때에는 등록관청 소재지를 납세지로 한다.","지방자치단체의 장은 조례로 정하는 바에 따라 등록면허세의 세율을 부동산 등기에 따른 표준세율의 100분의 50의 범위에서 가감할 수 있다.","주택의 토지와 건축물을 한꺼번에 평가하여 토지나 건축물에 대한 과세표준이 구분되지 아니하는 경우에는 한꺼번에 평가한 개별주택가격을 토지나 건축물의 가액비율로 나눈 금액을 각각 토지와 건축물의 과세표준으로 한다.","부동산의 등록에 대한 등록면허세의 과세표준은 등록자가 신고한 당시의 가액으로 하고, 신고가 없거나 신고가액이 시가표준액보다 많은 경우에는 시가표준액으로 한다.","채권자대위자는 납세의무자를 대위하여 부동산의 등기에 대한 등록면허세를 신고납부할 수 있다."],"a":[4],"p":28,"L":"세2-2","S":[],"m":"","f":null},{"i":"34회-2차-115","r":34,"y":2023,"c":2,"g":"2교시","n":35,"q":"주택임대사업자인 거주자 甲의 국내주택 임대현황(A, B, C 각 주택의 임대기간: 2023.1.1. ~ 2023.12.31.)을 참고하여 계산한 주택임대에 따른 2023년 귀속 사업소득의 총수입금액은? (단, 법령에 따른 적격증명서류를 수취ㆍ보관하고 있고, 재정경제부령으로 정하는 이자율은 연 4 %로 가정하며 주어진 조건 이외에는 고려하지 않음)","b":"구분(주거전용면적) | 보증금 | 월세1) | 기준시가\nA주택(85m²) | 3억원 | 5십만원 | 5억원\nB주택(40m²) | 1억원 | - | 2억원\nC주택(109m²) | 5억원 | 1백만원 | 7억원\n\n1) 월세는 매월 수령하기로 약정한 금액임","bs":"표","img":[],"ch":["0원","16,800,000원","18,000,000원","32,400,000원","54,000,000원"],"a":[3],"p":20,"L":"세3-3","S":[],"m":"","f":{"판정":"수정","요약":"간주임대료 이자율 위임 부령 명칭 기획재정부령→재정경제부령 반영. 계산: 소형주택 B(40㎡·기준시가 2억원) 주택 수 제외(소득세법 제25조제1항, 2026.12.31까지) → 2주택이라 3주택 요건 불충족, 2주택 간주임대료 요건(기준시가 12억원 초과 주택·보증금 12억원 초과)도 불충족 → 월세 600만원+1,200만원 = 1,800만원 현행 동일","수정":[{"위치":"발문","원문":"기획재정부령으로 정하는 이자율은 연 4 %로 가정하며","수정문":"재정경제부령으로 정하는 이자율은 연 4 %로 가정하며","근거":"소득세법 시행령 제53조제3항제1호","바뀐점":"부령 명칭 기획재정부령→재정경제부령"}],"정답변경사유":""}},{"i":"34회-2차-116","r":34,"y":2023,"c":2,"g":"2교시","n":36,"q":"소득세법령상 양도소득세의 양도 또는 취득시기에 관한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["대금을 청산한 날이 분명하지 아니한 경우에는 등기부ㆍ등록부 또는 명부 등에 기재된 등기ㆍ등록접수일 또는 명의개서일","상속에 의하여 취득한 자산에 대하여는 그 상속이 개시된 날","대금을 청산하기 전에 소유권이전등기를 한 경우에는 등기부에 기재된 등기접수일","자기가 건설한 건축물로서 건축허가를 받지 아니하고 건축하는 건축물에 있어서는 그 사실상의 사용일","완성되지 아니한 자산을 양도한 경우로서 해당 자산의 대금을 청산한 날까지 그 목적물이 완성되지 아니한 경우에는 해당 자산의 대금을 청산한 날"],"a":[5],"p":28,"L":"세3-2","S":[],"m":"","f":null},{"i":"34회-2차-117","r":34,"y":2023,"c":2,"g":"2교시","n":37,"q":"소득세법령상 거주자의 양도소득과세표준에 적용되는 세율에 관한 내용으로 옳은 것은? (단, 국내소재 자산을 2023년에 양도한 경우로서 주어진 자산 외에 다른 자산은 없으며, 비과세와 감면은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["보유기간이 6개월인 등기된 상가건물: 100분의 40","보유기간이 10개월인 「소득세법」에 따른 분양권: 100분 의 70","보유기간이 1년 6개월인 등기된 상가건물: 100분의 30","보유기간이 1년 10개월인 「소득세법」에 따른 조합원입주권: 100분의 70","보유기간이 2년 6개월인 「소득세법」에 따른 분양권: 100분의 50"],"a":[2],"p":25,"L":"세3-2","S":[],"m":"","f":null},{"i":"34회-2차-118","r":34,"y":2023,"c":2,"g":"2교시","n":38,"q":"소득세법령상 거주자의 양도소득세 과세대상은 모두 몇 개인가? (단, 국내소재 자산을 양도한 경우임)","b":"전세권\n등기되지 않은 부동산임차권\n사업에 사용하는 토지 및 건물과 함께 양도하는 영업권\n토지 및 건물과 함께 양도하는 개발제한구역의 지정 및 관리에 관한 특별조치법에 따른 이축권(해당 이축권의 가액을 대통령령으로 정하는 방법에 따라 별도로 평가하여 신고함)","bs":"글자","img":[],"ch":["0개","1개","2개","3개","4개"],"a":[3],"p":25,"L":"세3-2","S":[],"m":"","f":null},{"i":"34회-2차-119","r":34,"y":2023,"c":2,"g":"2교시","n":39,"q":"소득세법령상 거주자의 양도소득세 비과세에 관한 설명으로 틀린 것은? (단, 국내소재 자산을 양도한 경우임)","b":null,"bs":"없음","img":[],"ch":["파산선고에 의한 처분으로 발생하는 소득은 비과세된다.","「지적재조사에 관한 특별법」에 따른 경계의 확정으로 지적공부상의 면적이 감소되어 같은 법에 따라 지급받는 조정금은 비과세된다.","건설사업자가 「도시개발법」에 따라 공사용역 대가로 취득한 체비지를 토지구획환지처분공고 전에 양도하는 토지는 양도소득세 비과세가 배제되는 미등기양도자산에 해당하지 않는다.","「도시개발법」에 따른 도시개발사업이 종료되지 아니하여 토지 취득등기를 하지 아니하고 양도하는 토지는 양도소득세 비과세가 배제되는 미등기양도자산에 해당하지 않는다.","국가가 소유하는 토지와 분합하는 농지로서 분합하는 쌍방 토지가액의 차액이 가액이 큰 편의 4분의 1을 초과하는 경우 분합으로 발생하는 소득은 비과세된다."],"a":[5],"p":24,"L":"세3-2","S":[],"m":"","f":null},{"i":"34회-2차-120","r":34,"y":2023,"c":2,"g":"2교시","n":40,"q":"소득세법령상 1세대 1주택자인 거주자 甲이 2023년 양도한 국내소재 A주택(조정대상지역이 아니며 등기됨)에 대한 양도소득과세표준은? (단, 2023년에 A주택 외 양도한 자산은 없으며, 법령에 따른 적격증명서류를 수취ㆍ보관하고 있고 주어진 조건 이외에는 고려하지 않음)","b":"구분 기준시가 실지거래가액 양도시 18억원 25억원 취득시 13억5천만원 19억5천만원\n○ 양도비 및 자본적지출액: 5천만원 추가 ○ 보유기간 및 거주기간: 각각 5년 사항 ○ 장기보유특별공제율: 보유기간별 공제율과 거주기간별 공제율은 각각 20 %","bs":"글자","img":[],"ch":["153,500,000원","156,000,000원","195,500,000원","260,000,000원","500,000,000원"],"a":[1],"p":15,"L":"세3-2","S":[],"m":"","f":null},{"i":"35회-2차-105","r":35,"y":2024,"c":2,"g":"2교시","n":25,"q":"국세기본법령 및 지방세기본법령상 조세채권과 일반채권의 우선관계에 관한 설명으로 틀린 것은? (단, 납세의무자의 신고는 적법한 것으로 가정함)","b":null,"bs":"없음","img":[],"ch":["취득세의 법정기일은 과세표준과 세액을 신고한 경우 그 신고일이다.","토지를 양도한 거주자가 양도소득세 과세표준과 세액을 예정신고한 경우 양도소득세의 법정기일은 그 예정신고일이다.","법정기일 전에 전세권이 설정된 사실은 양도소득세의 경우 부동산등기부 등본 또는 공증인의 증명으로 증명한다.","주택의 직전 소유자가 국세의 체납 없이 전세권이 설정된 주택을 양도하였으나, 양도 후 현재 소유자의 소득세가 체납되어 해당 주택의 매각으로 그 매각금액에서 소득세를 강제징수하는 경우 그 소득세는 해당 주택의 전세권담보채권에 우선한다.","｢주택임대차보호법｣제8조가 적용되는 임대차관계에 있는 주택을 매각하여 그 매각금액에서 지방세를 강제징수하는 경우에는 임대차에 관한 보증금 중 일정액으로 서 같은 법에 따라 임차인이 우선하여 변제받을 수 있는 금액에 관한 채권이 지방세에 우선한다."],"a":[4],"p":24,"L":"세1-1","S":[],"m":"","f":null},{"i":"35회-2차-106","r":35,"y":2024,"c":2,"g":"2교시","n":26,"q":"국세기본법령 및 지방세기본법령상 국세 또는 지방세 징수권의 소멸시효에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["가산세를 제외한 국세가 10억원인 경우 국세징수권은 5년 동안 행사하지 아니하면 소멸시효가 완성된다.","가산세를 제외한 지방세가 1억원인 경우 지방세징수권은 7년 동안 행사하지 아니하면 소멸시효가 완성된다.","가산세를 제외한 지방세가 5천만원인 경우 지방세징수권은 5년 동안 행사하지 아니하면 소멸시효가 완성된다.","납세의무자가 양도소득세를 확정신고하였으나 정부가 경정하는 경우, 국세징수권을 행사할 수 있는 때는 납세의무자가 확정신고한 법정 신고납부기한의 다음 날이다.","납세의무자가 취득세를 신고하였으나 지방자치단체의장이 경정하는 경우, 납세고지한 세액에 대한 지방세징수권을 행사할 수 있는 때는 그 납세고지서에 따른 납부기한의 다음 날이다."],"a":[5],"p":12,"L":"세1-1","S":[],"m":"","f":null},{"i":"35회-2차-107","r":35,"y":2024,"c":2,"g":"2교시","n":27,"q":"종합부동산세법령상 주택에 대한 과세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["｢신탁법｣제2조에 따른 수탁자의 명의로 등기된 신탁주택의 경우에는 수탁자가 종합부동산세를 납부할 의무가 있으며, 이 경우 수탁자가 신탁주택을 소유한 것으로 본다.","법인이 2주택을 소유한 경우 종합부동산세의 세율은 1천분의 50을 적용한다.","거주자 甲이 2023년부터 보유한 3주택(주택 수 계산에서 제외되는 주택은 없음) 중 2주택을 2024.6.17.에 양도하고 동시에 소유권이전등기를 한 경우, 甲의 2024년도주택분 종합부동산세액은 3주택 이상을 소유한 경우의세율을 적용하여 계산한다.","신탁주택의 수탁자가 종합부동산세를 체납한 경우 그 수탁자의 다른 재산에 대하여 강제징수하여도 징수할 금액에 미치지 못할 때에는 해당 주택의 위탁자가 종합부동산세를 납부할 의무가 있다.","공동명의 1주택자인 경우 주택에 대한 종합부동산세의 과세표준은 주택의 시가를 합산한 금액에서 11억원을 공제한 금액에 100분의 50을 한도로 공정시장가액비율을 곱한 금액으로 한다."],"a":[3],"p":22,"L":"세3-1","S":[],"m":"","f":null},{"i":"35회-2차-108","r":35,"y":2024,"c":2,"g":"2교시","n":28,"q":"종합부동산세법령상 토지에 대한 과세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지분 재산세의 납세의무자로서 종합합산과세대상 토지의 공시가격을 합한 금액이 5억원인 자는 종합부동산세를 납부할 의무가 있다.","토지분 재산세의 납세의무자로서 별도합산과세대상 토지의 공시가격을 합한 금액이 80억원인 자는 종합부동산세를 납부할 의무가 있다.","토지에 대한 종합부동산세는 종합합산과세대상, 별도합산과세대상 그리고 분리과세대상으로 구분하여 과세한다.","종합합산과세대상인 토지에 대한 종합부동산세의 과세표준은 해당 토지의 공시가격을 합산한 금액에서 5억원을 공제한 금액에 100분의 50을 한도로 공정시장가액비율을 곱한 금액으로 한다.","별도합산과세대상인 토지의 과세표준 금액에 대하여 해당 과세대상 토지의 토지분 재산세로 부과된 세액(｢지방세법｣에 따라 가감조정된 세율이 적용된 경우에는 그 세율이 적용된 세액, 같은 법에 따라 세부담 상한을 적용받은 경우에는 그 상한을 적용받은 세액을 말한다)은 토지분 별도합산세액에서 이를 공제한다."],"a":[5],"p":22,"L":"세3-1","S":[],"m":"","f":null},{"i":"35회-2차-109","r":35,"y":2024,"c":2,"g":"2교시","n":29,"q":"지방세법령상 취득세의 취득당시가액에 관한 설명으로 옳은 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["건축물을 교환으로 취득하는 경우에는 교환으로 이전받는 건축물의 시가표준액과 이전하는 건축물의 시가표준액 중 낮은 가액을 취득당시가액으로 한다.","상속에 따른 건축물 무상취득의 경우에는 ｢지방세법｣제4조에 따른 시가표준액을 취득당시가액으로 한다.","대물변제에 따른 건축물 취득의 경우에는 대물변제액(대물변제액 외에 추가로 지급한 금액이 있는 경우에는 그 금액을 제외한다)을 취득당시가액으로 한다.","법인이 아닌 자가 건축물을 건축하여 취득하는 경우로서 사실상취득가격을 확인할 수 없는 경우에는 시가인 정액을 취득당시가액으로 한다.","법인이 아닌 자가 건축물을 매매로 승계취득하는 경우에는 그 건축물을 취득하기 위하여 ｢공인중개사법｣에 따른 공인중개사에게 지급한 중개보수를 취득당시가액에 포함한다."],"a":[2],"p":34,"L":"세2-1","S":[],"m":"","f":null},{"i":"35회-2차-110","r":35,"y":2024,"c":2,"g":"2교시","n":30,"q":"지방세법령상 취득세에 관한 설명으로 틀린 것은? (단, 지방세특례제한법령은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["대한민국 정부기관의 취득에 대하여 과세하는 외국정부의 취득에 대해서는 취득세를 부과한다.","토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다.","국가에 귀속의 반대급부로 영리법인이 국가 소유의 부동산을 무상으로 양여받는 경우에는 취득세를 부과하지 아니한다.","영리법인이 취득한 임시흥행장의 존속기간이 1년을 초과하는 경우에는 취득세를 부과한다.","신탁(｢신탁법｣에 따른 신탁으로서 신탁등기가 병행되는 것만 해당한다)으로 인한 신탁재산의 취득 중 주택조합등과 조합원 간의 부동산 취득에 대해서는 취득세를 부과한다."],"a":[3],"p":28,"L":"세2-1","S":[],"m":"","f":null},{"i":"35회-2차-111","r":35,"y":2024,"c":2,"g":"2교시","n":31,"q":"지방세법령상 부동산 취득에 대한 취득세의 표준세율로 옳은 것을 모두 고른 것은? (단, 조례에 의한 세율조정, 지방세관계법령상 특례 및 감면은 고려하지 않음)","b":"ㄱ. 상속으로 인한 농지의 취득: 1천분의 23\nㄴ. 법인의 합병으로 인한 농지 외의 토지 취득: 1천 분의 40\nㄷ. 공유물의 분할로 인한 취득: 1천분의 17\nㄹ. 매매로 인한 농지 외의 토지 취득: 1천분의 19","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ"],"a":[1],"p":34,"L":"세2-1","S":[],"m":"","f":null},{"i":"35회-2차-112","r":35,"y":2024,"c":2,"g":"2교시","n":32,"q":"소득세법령상 거주자의 부동산과 관련된 사업소득에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["해당 과세기간의 종합소득금액이 있는 거주자(종합소득과세표준이 없거나 결손금이 있는 거주자를 포함한다)는 그 종합소득 과세표준을 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 하며, 해당 과세기간에 분리과세 주택임대소득이 있는 경우에도 이를 적용한다.","공장재단을 대여하는 사업은 부동산임대업에 해당되지 않는다.","해당 과세기간의 주거용 건물 임대업을 제외한 부동산임대업에서 발생한 결손금은 그 과세기간의 종합소득과세표준을 계산할 때 공제한다.","｢공익사업을 위한 토지 등의 취득 및 보상에 관한 법률｣제4조에 따른 공익사업과 관련하여 지역권을 설정함으로써 발생하는 소득은 부동산업에서 발생하는 소득에 해당한다.","사업소득에 부동산임대업에서 발생한 소득이 포함되어 있는 사업자는 그 소득별로 구분하지 않고 회계처리하여야 한다."],"a":[1],"p":20,"L":"세3-3","S":[],"m":"","f":null},{"i":"35회-2차-113","r":35,"y":2024,"c":2,"g":"2교시","n":33,"q":"지방세법령상 재산세 과세기준일 현재 납세의무자로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 경우: 종중","상속이 개시된 재산으로서 상속등기가 이행되지 아니하고 사실상의 소유자를 신고하지 아니하였을 경우: 행정안전부령으로 정하는 주된 상속자","｢도시 및 주거환경정비법｣에 따른 정비사업(재개발사업만 해당한다)의 시행에 따른 환지계획에서 일정한 토지를 환지로 정하지 아니하고 체비지로 정한 경우: 사업시행자","｢채무자 회생 및 파산에 관한 법률｣에 따른 파산선고 이후 파산종결의 결정까지 파산재단에 속하는 재산의 경우: 공부상 소유자","지방자치단체와 재산세 과세대상 재산을 연부(年賦)로 매매계약을 체결하고 그 재산의 사용권을 무상으로 받은 경우: 그 매수계약자"],"a":[1],"p":28,"L":"세2-3","S":[],"m":"","f":null},{"i":"35회-2차-114","r":35,"y":2024,"c":2,"g":"2교시","n":34,"q":"지방세법령상 재산세의 물납에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 지방자치단체의 장은 재산세의 납부세액이 1 천만원을 초과하는 경우에는 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 대통령령으로 정하는 바에 따라 물납을 허가할 수 있다.\nㄴ. 시장ㆍ군수ㆍ구청장은 법령에 따라 불허가 통지를 받은 납세의무자가 그 통지를 받은 날부터 10일 이내에 해당 시ㆍ군ㆍ구의 관할구역에 있는 부동산으로서 관리ㆍ처분이 가능한 다른 부동산으로 변경 신청하는 경우에는 변경하여 허가할 수 있다.\nㄷ. 물납을 허가하는 부동산의 가액은 물납 허가 일 현재의 시가로 한다.","bs":"글자","img":[],"ch":["ㄱ","ㄷ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[3],"p":27,"L":"세2-3","S":[],"m":"","f":null},{"i":"35회-2차-115","r":35,"y":2024,"c":2,"g":"2교시","n":35,"q":"지방세법령상 재산세에 관한 설명으로 옳은 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["특별시 지역에서 ｢국토의 계획 및 이용에 관한 법률｣에 따라 지정된 주거지역의 대통령령으로 정하는 공장용건축물의 표준세율은 초과누진세율이다.","수탁자 명의로 등기ㆍ등록된 신탁재산의 수탁자는 과세기준일부터 15일 이내에 그 소재지를 관할하는 지방자치단체의 장에게 그 사실을 알 수 있는 증거자료를 갖추어 신고하여야 한다.","주택의 토지와 건물 소유자가 다를 경우 해당 주택에 대한 세율을 적용할 때 해당 주택의 토지와 건물의 가액을 소유자별로 구분계산한 과세표준에 세율을 적용한다.","주택의 재산세로서 해당 연도에 부과할 세액이 20만원 이하인 경우에는 납기를 9월 16일부터 9월 30일까지로 하여 한꺼번에 부과ㆍ징수할 수 있다.","지방자치단체의 장은 과세대상의 누락으로 이미 부과한 재산세액을 변경하여야 할 사유가 발생하여도 수시로 부과ㆍ징수할 수 없다."],"a":[2],"p":28,"L":"세2-3","S":[],"m":"","f":null},{"i":"35회-2차-116","r":35,"y":2024,"c":2,"g":"2교시","n":36,"q":"다음 자료를 기초로 할 때 소득세법령상 국내 토지A에 대한 양도소득세에 관한 설명으로 옳은 것은? (단, 甲, 乙, 丙은 모두 거주자임)","b":"甲은 2018.6.20. 토지A를 3억원에 취득하였으며, 2020.5.15. 토지A에 대한 자본적 지출로 5천만원을 지출하였다.\n乙은 2022.7.1. 직계존속인 甲으로부터 토지A를 증여받아 2022.7.25. 소유권이전등기를 마쳤다(토지A의 증여 당시 시가는 6억원임).\n乙은 2024.10.20. 토지A를 甲또는 乙과 특수관계가 없는 丙에게 10억원에 양도하였다.\n토지A는 법령상 협의매수 또는 수용된 적이 없으며, 소득세법 제97조의2 양도소득의 필요경비 계산 특례(이월과세)를 적용하여 계산한 양도소득 결정세액이 이를 적용하지 않고 계산한 양도소득 결정세액보다 크다고 가정한다.","bs":"글자","img":[],"ch":["양도차익 계산시 양도가액에서 공제할 취득가액은 6억원이다.","양도차익 계산시 甲이 지출한 자본적 지출액 5천만원은 양도가액에서 공제할 수 없다.","양도차익 계산시 乙이 납부하였거나 납부할 증여세 상당액이 있는 경우 양도차익을 한도로 필요경비에 산입한다.","장기보유 특별공제액 계산 및 세율 적용시 보유기간은 乙의 취득일부터 양도일까지의 기간으로 한다.","甲과 乙은 양도소득세에 대하여 연대납세의무를 진다."],"a":[3],"p":22,"L":"세3-2","S":[],"m":"","f":null},{"i":"35회-2차-117","r":35,"y":2024,"c":2,"g":"2교시","n":37,"q":"소득세법령상 다음의 국내자산 중 양도소득세 과세대상에 해당하는 것을 모두 고른 것은? (단, 비과세와 감면은 고려하지 않음)","b":"ㄱ. 토지 및 건물과 함께 양도하는 ｢개발제한구역의 지정 및 관리에 관한 특별조치법｣에 따른 이축권(해당 이축권 가액을 대통령령으로 정하는 방법에 따라 별도로 평가하여 신고하지 않음)\nㄴ. 조합원입주권\nㄷ. 지역권\nㄹ. 부동산매매계약을 체결한 자가 계약금만 지급한 상태에서 양도하는 권리","bs":"글자","img":[],"ch":["ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":[3],"p":23,"L":"세3-2","S":[],"m":"","f":null},{"i":"35회-2차-118","r":35,"y":2024,"c":2,"g":"2교시","n":38,"q":"소득세법령상 거주자의 국내자산 양도에 대한 양도소득세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["부담부증여의 채무액에 해당하는 부분으로서 양도로 보는 경우에는 그 양도일이 속하는 달의 말일부터 2개월이내에 양도소득세를 신고하여야 한다.","토지를 매매하는 거래당사자가 매매계약서의 거래가액을 실지거래가액과 다르게 적은 경우에는 해당 자산에 대하여 ｢소득세법｣에 따른 양도소득세의 비과세에 관한 규정을 적용할 때, 비과세 받을 세액에서 '비과세에 관한 규정을 적용하지 아니하였을 경우의 양도소득 산출세액'과 '매매계약서의 거래가액과 실지거래가액과의 차액' 중 큰 금액을 뺀다.","사업상의 형편으로 인하여 세대전원이 다른 시ㆍ군으로 주거를 이전하게 되어 6개월 거주한 주택을 양도하는 경우 보유기간 및 거주기간의 제한을 받지 아니하고 양도소득세가 비과세된다.","토지의 양도로 발생한 양도차손은 동일한 과세기간에 전세권의 양도로 발생한 양도소득금액에서 공제할 수 있다.","상속받은 주택과 상속개시 당시 보유한 일반주택을 국내에 각각 1개씩 소유한 1세대가 상속받은 주택을 양도하는 경우에는 국내에 1개의 주택을 소유하고 있는 것으로 보아 1세대 1주택 비과세 규정을 적용한다."],"a":[4],"p":22,"L":"세3-2","S":[],"m":"","f":null},{"i":"35회-2차-119","r":35,"y":2024,"c":2,"g":"2교시","n":39,"q":"소득세법령상 거주자가 2024년에 양도한 국외자산의 양도소득세에 관한 설명으로 틀린 것은? (단, 거주자는 해당 국외자산 양도일까지 계속 5년 이상 국내에 주소를 두고 있으며, 국외 외화차입에 의한 취득은 없음)","b":null,"bs":"없음","img":[],"ch":["국외자산의 양도에 대한 양도소득이 있는 거주자는 양도소득 기본공제는 적용받을 수 있으나 장기보유 특별공제는 적용받을 수 없다.","국외 부동산을 양도하여 발생한 양도차손은 동일한 과세기간에 국내 부동산을 양도하여 발생한 양도소득금액에서 통산할 수 있다.","국외 양도자산이 부동산임차권인 경우 등기여부와 관계없이 양도소득세가 과세된다.","국외자산의 양도가액은 그 자산의 양도 당시의 실지거래가액으로 한다. 다만, 양도 당시의 실지거래가액을 확인할 수 없는 경우에는 양도자산이 소재하는 국가의 양도 당시 현황을 반영한 시가에 따르되, 시가를 산정하기 어려울 때에는 그 자산의 종류, 규모, 거래상황 등을고려하여 대통령령으로 정하는 방법에 따른다.","국외 양도자산이 양도 당시 거주자가 소유한 유일한 주택으로서 보유기간이 2년 이상인 경우에도 1세대 1주택비과세 규정을 적용받을 수 없다."],"a":[2],"p":21,"L":"세3-2","S":[],"m":"","f":null},{"i":"35회-2차-120","r":35,"y":2024,"c":2,"g":"2교시","n":40,"q":"다음 자료를 기초로 할 때 소득세법령상 거주자 甲이 확정신고시 신고할 건물과 토지B의 양도소득과세표준을 각각 계산하면? (단, 아래 자산 외의 양도자산은 없고, 양도소득과세표준 예정신고는 모두 하지 않았으며, 감면소득금액은 없다고 가정함)","b":"구분 | 건물(주택아님) | 토지A | 토지B\n양도차익(차손) | 15,000,000원 | (20,000,000원) | 25,000,000원\n양도일자 | 2024.3.10. | 2024.5.20. | 2024.6.25.\n보유기간 | 1년 8개월 | 4년 3개월 | 3년 5개월\n* 위 자산은 모두 국내에 있으며 등기됨\n* 토지A, 토지B는 비사업용 토지 아님\n* 장기보유 특별공제율은 6%로 가정함\n\n(빈칸) | 건물 | 토지B\n① | 0원 | 16,000,000원\n② | 0원 | 18,500,000원\n③ | 11,600,000원 | 5,000,000원\n④ | 12,500,000원 | 3,500,000원\n⑤ | 12,500,000원 | 1,000,000원","bs":"표","img":[],"ch":["건물: 0원, 토지B: 16,000,000원","건물: 0원, 토지B: 18,500,000원","건물: 11,600,000원, 토지B: 5,000,000원","건물: 12,500,000원, 토지B: 3,500,000원","건물: 12,500,000원, 토지B: 1,000,000원"],"a":[4],"p":25,"L":"세3-2","S":[],"m":"","f":null},{"i":"36회-2차-105","r":36,"y":2025,"c":2,"g":"2교시","n":25,"q":"국세기본법령 및 지방세기본법령상 납세의무의 성립 시기에 관한 설명으로 틀린 것은? (단, 원천징수, 예정신고 및 수시부과의 경우는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["토지에 대한 양도소득세: 과세기간이 끝나는 때","주택에 대한 종합부동산세: 과세기준일","전세권설정등기에 대한 등록면허세: 등기하는 때","토지에 대한 재산세: 과세기준일","건축물에 대한 지역자원시설세: 취득하는 때"],"a":[5],"p":null,"L":"세1-1","S":[],"m":"","f":null},{"i":"36회-2차-106","r":36,"y":2025,"c":2,"g":"2교시","n":26,"q":"지방세기본법령상 가산세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지방세를 감면하는 경우 가산세는 감면대상에 포함하지 아니한다.","사기나 그 밖의 부정한 행위로 법정신고기한까지 과세표준 신고를 하지 아니한 경우(기한 후 신고는 하지 않음) 무신고납부세액의 100분의 40에 상당하는 금액을 무신고가산세로 부과한다.","신고 당시 소유권에 대한 소송으로 상속재산으로 확정되지 아니하여 과소신고한 경우 과소신고가산세를 부과하지 아니한다.","지방자치단체의 장은 「지방세기본법」 또는 지방세관계법에 따라 가산세를 부과하는 경우 납세자가 해당 의무를 이행하지 아니한 정당한 사유가 있을 때에는 납세자가 법령에 따른 신청을 하는 경우 가산세를 부과하지 아니한다.","법정신고기한이 지난 후 1개월 이내에 지방자치단체의 장이 과세표준과 세액을 결정할 것을 미리 알고 기한후 신고서를 제출한 경우 무신고가산세액의 100분의 50에 상당하는 금액을 감면한다."],"a":[5],"p":null,"L":"세1-1","S":[],"m":"","f":null},{"i":"36회-2차-107","r":36,"y":2025,"c":2,"g":"2교시","n":27,"q":"지방세법령상 등록면허세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["취득가액이 50만원인 토지의 소유권 이전등기를 하는 자는 등록면허세 납세의무가 없다.","부동산 등기에 대한 등록면허세의 납세지는 소유자의 주소지이다.","부동산 등기에 대한 등록면허세의 과세표준은 취득당시의 가액으로 한다.","월 임대차금액의 1천분의 2로 계산한 임차권 설정등기의 등록면허세액이 11만2천500원보다 적을 때에는 11만2천500원으로 한다.","채권자대위자는 납세의무자를 대위하여 부동산의 등기에 대한 등록면허세를 신고납부할 수 있다."],"a":[5],"p":null,"L":"세2-2","S":[],"m":"","f":null},{"i":"36회-2차-108","r":36,"y":2025,"c":2,"g":"2교시","n":28,"q":"지방세법령상 재산세 징수에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지방자치단체의 장은 재산세 납부세액이 1천만원을 초과하는 경우 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 대통령령으로 정하는 바에 따라 물납을 허가할 수 있다.","지방자치단체의 장은 재산세 납부세액이 250만원을 초과하는 경우 대통령령으로 정하는 바에 따라 납부할 세액의 일부를 납부기한이 지난 날부터 3개월 이내에 분할납부하게 할 수 있다.","「지방세법」 제118조의2에 따른 주택 재산세의 납부유예를 신청한 납세의무자는 그 유예할 주택 재산세에 상당하는 담보를 제공하여야 한다.","고지서 1장당 재산세로 징수할 세액이 2천원 미만인 경우 해당 재산세를 징수하지 아니한다.","신탁재산의 수탁자는 신탁 설정일 전에 법정기일이 도래한 위탁자의 재산세에 대하여 그 신탁재산으로써 납부할 의무가 있다."],"a":[5],"p":null,"L":"세2-3","S":[],"m":"","f":null},{"i":"36회-2차-109","r":36,"y":2025,"c":2,"g":"2교시","n":29,"q":"지방세법령상 재산세에 관한 설명으로 틀린 것은 모두 몇 개인가?","b":"○ 재산세 과세대상 중 토지란 지적공부의 등록대상이 되는 토지뿐만 아니라 그 밖에 사용되고 있는 사실상의 토지를 말하므로 「주택법」 제2조 제1호에 따른 주택의 부속토지를 포함한다.\n○ 재산세 과세기준일 현재 공부상의 소유자가 매매 등의 사유로 소유권이 변동되었는데도 신고하지 아니하여 사실상의 소유자를 알 수 없을 때에는 재산세를 부과하지 않는다.\n○ 재산세 과세기준일 현재 소유권의 귀속이 분명하지 아니하여 사실상의 소유자를 확인할 수 없는 경우에는 재산세를 부과하지 않는다.\n○ 재산세 과세대상 물건의 공부상 등재현황과 사실상의 현황이 다른 경우 공부상 등재현황에 따라 재산세를 부과하는 경우가 있다.\n○ 건축물에 대한 재산세 과세대상은 종합합산과세대상, 별도합산과세대상 및 분리과세대상으로 구분한다.","bs":"글자","img":[],"ch":["1개","2개","3개","4개","5개"],"a":[4],"p":null,"L":"세2-3","S":[],"m":"","f":null},{"i":"36회-2차-110","r":36,"y":2025,"c":2,"g":"2교시","n":30,"q":"지방세법령상 취득세에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 취득이란 매매, 교환 등 유상의 취득을 말하며 기부는 제외한다.\nㄴ. 건축물 중 조작 설비, 그 밖의 부대설비에 속하는 부분으로서 그 주체구조부와 하나가 되어 건축물로서의 효용가치를 이루고 있는 것에 대하여는 주체구조부 취득자 외의 자가 가설한 경우에도 주체구조부의 취득자가 함께 취득한 것으로 본다.\nㄷ. 토지의 지목을 사실상 변경함으로써 그 가액이 증가하거나 감소한 경우에는 취득으로 본다.\nㄹ. 피상속인이 상속인에게 한 유증은 상속으로 인하여 취득하는 경우에 포함되지 않으므로 상속인 각자가 상속받는 취득물건을 취득한 것으로 보지 않는다.\nㅁ. 「주택법」 제11조에 따른 주택조합이 해당 조합원용으로 취득하는 조합주택용 부동산 중에서 공동주택 부대시설·복리시설은 조합원에게 귀속되는 부동산이라 하더라도 그 조합원이 취득한 것으로 보지 않는다.","bs":"글자","img":[],"ch":["ㄴ","ㄱ, ㅁ","ㄴ, ㅁ","ㄷ, ㄹ","ㄷ, ㄹ, ㅁ"],"a":[1],"p":null,"L":"세2-1","S":[],"m":"","f":null},{"i":"36회-2차-111","r":36,"y":2025,"c":2,"g":"2교시","n":31,"q":"지방세법령상 2026년도에 납세의무가 성립하는 재산세의 과세표준을 산정하는 경우, 지방세법시행령 제110조의2에 따라 1세대 1주택으로 인정되는 주택 중 시가표준액이 6억원을 초과하는 주택에 적용하는 공정시장가액비율은?","b":null,"bs":"없음","img":[],"ch":["시가표준액의 100분의 43","시가표준액의 100분의 44","시가표준액의 100분의 45","시가표준액의 100분의 60","시가표준액의 100분의 70"],"a":[3],"p":null,"L":"세2-3","S":[],"m":"","f":{"판정":"수정","요약":"현행 지방세법 시행령 제109조제1항제2호 단서가 '2026년도에 납세의무가 성립하는 재산세'로 규정(2026.5.29 개정)되어 발문 연도를 현행 조문에 맞춤. 6억원 초과 1세대1주택 100분의 45 → ③ 동일","수정":[{"위치":"발문","원문":"지방세법령상 2025년도에 납세의무가 성립하는 재산세의 과세표준을 산정하는 경우,","수정문":"지방세법령상 2026년도에 납세의무가 성립하는 재산세의 과세표준을 산정하는 경우,","근거":"지방세법 시행령 제109조제1항제2호다목","바뀐점":"특례 적용연도 2025년도→2026년도(비율 100분의 43·44·45 동일)"}],"정답변경사유":""}},{"i":"36회-2차-112","r":36,"y":2025,"c":2,"g":"2교시","n":32,"q":"지방세법령상 취득세의 비과세에 관한 다음 설명에서 밑줄 친 '대통령령으로 정하는 가액 이하의 주택'이 의미하는 것은?","b":"「주택법」 제2조 제3호에 따른 공동주택의 개수(「건축법」 제2조 제1항 제9호에 따른 대수선은 제외한다)로 인한 취득 중 '대통령령으로 정하는 가액 이하의 주택'과 관련된 개수로 인한 취득에 대해서는 취득세를 부과하지 아니한다.","bs":"글자","img":[],"ch":["공동주택의 개수 이전 최초 취득 당시 「지방세법」 제4조에 따른 주택의 시가표준액이 6억원 이하인 주택","공동주택의 개수 이전 최초 취득 당시 실지거래가액이 9억원 이하인 주택","공동주택의 개수로 인한 취득 당시 「지방세법」 제4조에 따른 주택의 시가표준액이 9억원 이하인 주택","공동주택의 개수로 인한 취득 당시 주택의 실지거래가액이 6억원 이하인 주택","공동주택의 개수로 인한 취득 당시 인근 유사 주택의 부동산거래신고 내역으로 확인된 거래가액이 6억원 이하인 주택"],"a":[3],"p":null,"L":"세2-1","S":[],"m":"","f":null},{"i":"36회-2차-113","r":36,"y":2025,"c":2,"g":"2교시","n":33,"q":"종합부동산세법령상 토지에 대한 과세 및 부과·징수 등에 관한 설명으로 틀린 것은? (단, 2025년도 납세의무 성립분임)","b":null,"bs":"없음","img":[],"ch":["토지에 대한 종합부동산세는 국내에 소재하는 토지에 대하여 종합합산과세대상과 별도합산과세대상으로 구분하여 과세한다.","별도합산과세대상인 토지에 대한 종합부동산세의 과세표준은 납세의무자별로 해당 과세대상토지의 공시가격을 합산한 금액에서 80억원을 공제한 금액에 100분의 100의 공정시장가액비율을 곱한 금액(영보다 작은 경우에는 영으로 본다)으로 한다.","종합부동산세를 신고납부방식으로 납부하고자 하는 납세의무자는 종합부동산세의 과세표준과 세액을 해당 연도 12월 1일부터 12월 15일까지 대통령령으로 정하는 바에 따라 관할세무서장에게 신고하여야 한다.","납세의무자가 토지분 종합부동산세의 납부유예를 그 납부기한 만료일까지 신청하는 경우 관할세무서장은 이를 허가할 수 있다.","관할세무서장은 법령에 따른 주택분 종합부동산세의 납부유예 신청을 받은 경우 납부기한 만료일까지 대통령령으로 정하는 바에 따라 납세의무자에게 납부유예 허가 여부를 통지하여야 한다."],"a":[4],"p":null,"L":"세3-1","S":[],"m":"","f":null},{"i":"36회-2차-114","r":36,"y":2025,"c":2,"g":"2교시","n":34,"q":"종합부동산세법령상 주택에 대한 과세에 관한 설명으로 옳은 것은? (단, 2025년도 납세의무 성립분임)","b":null,"bs":"없음","img":[],"ch":["「신탁법」 제2조에 따른 수탁자의 명의로 등기된 신탁주택의 경우 그 위탁자는 종합부동산세를 납부할 의무가 없다.","과세표준 합산의 대상에 포함되지 아니하는 주택을 보유한 납세의무자는 해당 연도 10월 16일부터 10월 31일 까지 해당 주택의 보유현황을 신고하여야 한다.","공익법인등이 직접 공익목적사업에 사용하는 1주택만을 보유한 경우 종합부동산세의 세율은 1천분의 50을 적용한다.","「민간임대주택에 관한 특별법」에 따른 민간임대주택으로서 임대기간, 주택의 수, 가격, 규모 등을 고려하여 대통령령으로 정하는 주택은 법령에 따라 해당 주택의 보유현황을 신고한 경우 종합부동산세 과세표준 합산의 대상이 되는 주택의 범위에 포함되지 아니하는 것으로 본다.","2주택을 소유하여 1천분의 27의 세율이 적용되는 법인의 경우 해당 연도에 납부하여야 할 주택에 대한 총세액상당액으로서 세부담의 상한을 초과하는 세액에 대해서는 이를 없는 것으로 본다."],"a":[4],"p":null,"L":"세3-1","S":[],"m":"","f":null},{"i":"36회-2차-115","r":36,"y":2025,"c":2,"g":"2교시","n":35,"q":"소득세법령상 거주자의 양도소득세 신고 및 납부에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지거래계약에 관한 허가구역에 있는 토지를 양도할 때 토지거래계약허가를 받기 전에 대금을 청산한 경우 그 허가일이 속하는 분기의 말일부터 2개월 이내에 양도소득과세표준 예정신고를 하여야 한다.","법령에 따른 부담부증여의 채무액에 해당하는 부분으로서 양도로 보는 경우 그 양도일이 속하는 반기의 말일부터 3개월 이내에 양도소득과세표준을 신고하여야 한다.","양도차손이 발생한 경우 양도소득과세표준 예정신고를 하지 아니한다.","해당 과세기간의 양도소득금액이 있는 경우 해당 과세 기간의 과세표준이 없다면 양도소득과세표준 확정신고를 하지 아니한다.","확정신고납부를 하는 경우 「소득세법」 제107조에 따른 예정신고 산출세액이 있을 때에는 이를 공제하여 납부한다."],"a":[5],"p":null,"L":"세3-2","S":[],"m":"","f":null},{"i":"36회-2차-116","r":36,"y":2025,"c":2,"g":"2교시","n":36,"q":"소득세법령상 거주자의 부동산임대 등에 관한 설명으로 옳은 모두 고른 것은?","b":"ㄱ. 부동산임대업에서 발생하는 사업소득이 있는 자가 사업장 소재지를 납세지로 신청한 경우 국세청장 또는 관할지방국세청장은 대통령령으로 정하는 바에 따라 사업장 소재지를 납세지로 지정할 수 있다.\nㄴ. 국외에 소재하는 주택 1개만을 소유하는 자의 해당 주택 임대소득은 비과세소득이다.\nㄷ. 광업재단을 대여하는 사업은 부동산임대업에 해당되지 않는다.\nㄹ. 해당 과세기간의 주거용 건물 임대업을 제외한 부동산임대업에서 발생한 결손금은 그 과세기간의 종합소득 과세표준을 계산할 때 공제하지 아니한다.","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":[2],"p":null,"L":"세3-3","S":[],"m":"","f":null},{"i":"36회-2차-117","r":36,"y":2025,"c":2,"g":"2교시","n":37,"q":"다음은 소득세법시행령 제168조의6 '비사업용 토지의 기간기준'의 일부이다. ( )에 들어갈 숫자로 옳은 것은?","b":"○ 토지의 소유기간이 5년 이상인 경우에는 다음 각 목의 모두에 해당하는 기간\n가. 양도일 직전 5년 중 ( ㄱ )년을 초과하는 기간\n나. 양도일 직전 3년 중 ( ㄴ )년을 초과하는 기간\n다. 토지의 소유기간의 100분의 ( ㄷ )에 상당하는 기간을 초과하는 기간","bs":"글자","img":[],"ch":["ㄱ: 2, ㄴ: 1, ㄷ: 30","ㄱ: 2, ㄴ: 1, ㄷ: 40","ㄱ: 3, ㄴ: 2, ㄷ: 30","ㄱ: 3, ㄴ: 2, ㄷ: 40","ㄱ: 4, ㄴ: 2, ㄷ: 40"],"a":[2],"p":null,"L":"세3-2","S":[],"m":"","f":null},{"i":"36회-2차-118","r":36,"y":2025,"c":2,"g":"2교시","n":38,"q":"소득세법령상 거주자가 실지거래가액에 따른 양도차익을 계산할 때 양도가액에서 공제할 필요경비에 관한 설명으로 틀린 것은? (단, 자본적지출액 등 및 양도비 등은 그 지출에 관하여 법령에 따른 증명서류를 수취 ㆍ보관하거나 실제 지출사실이 금융거래 증명서류에 의하여 확인되는 경우에 한함)","b":null,"bs":"없음","img":[],"ch":["양도자산을 취득한 후 쟁송이 있는 경우에 그 소유권을 확보하기 위하여 직접 소요된 소송비용ㆍ화해비용 등의 금액으로서 그 지출한 연도의 각 소득금액의 계산에 있어서 필요경비에 산입된 금액은 자본적지출액 등에 해당한다.","「소득세법」 제94조 제1항 각 호의 자산을 양도하기 위하여 직접 지출한 비용으로서 매매계약에 따른 인도의무를 이행하기 위하여 양도자가 지출하는 명도비용은 양도비 등에 해당한다.","「소득세법시행령」 제163조 제1항 제1호를 적용할 때 당사자 약정에 의한 대금지급방법에 따라 취득원가에 이자상당액을 가산하여 거래가액을 확정하는 경우 당해 이자상당액은 취득원가에 포함한다. 다만, 당초 약정에 의한 거래가액의 지급기일의 지연으로 인하여 추가로 발생하는 이자상당액은 취득원가에 포함하지 아니한다.","「재건축초과이익 환수에 관한 법률」에 따른 재건축부담금(재건축부담금의 납부의무자와 양도자가 서로 다른 경우에는 양도자에게 사실상 배분될 재건축부담금상당액)은 자본적지출액 등에 해당한다.","「소득세법」 제94조 제1항 제1호의 토지를 취득함에 있어서 법령 등의 규정에 따라 매입한 토지개발채권을 만기전에 재정경제부령으로 정하는 금융기관에 양도함으로써 발생하는 매각차손은 양도비 등에 해당한다."],"a":[1],"p":null,"L":"세3-2","S":[],"m":"","f":{"판정":"수정","요약":"시행령 제163조제5항제1호 매각차손 규정의 부령 명칭 기획재정부령→재정경제부령 반영. ①(필요경비 산입된 소송비용은 '제외', 시행령 제163조제3항제2호) 틀림 동일","수정":[{"위치":"선지5","원문":"「소득세법」 제94조 제1항 제1호의 토지를 취득함에 있어서 법령 등의 규정에 따라 매입한 토지개발채권을 만기전에 기획재정부령으로 정하는 금융기관에 양도함으로써 발생하는 매각차손은 양도비 등에 해당한다.","수정문":"「소득세법」 제94조 제1항 제1호의 토지를 취득함에 있어서 법령 등의 규정에 따라 매입한 토지개발채권을 만기전에 재정경제부령으로 정하는 금융기관에 양도함으로써 발생하는 매각차손은 양도비 등에 해당한다.","근거":"소득세법 시행령 제163조제5항제1호나목","바뀐점":"부령 명칭 기획재정부령→재정경제부령"}],"정답변경사유":""}},{"i":"36회-2차-119","r":36,"y":2025,"c":2,"g":"2교시","n":39,"q":"소득세법령상 양도소득세 비과세의 배제와 관련하여 미등기양도제외 자산에 해당하는 것을 모두 고른 것은?","b":"ㄱ. 법원의 결정에 의하여 양도 당시 그 자산의 취득에 관한 등기가 불가능한 자산\nㄴ. 장기할부조건으로 취득한 자산으로서 그 계약조건에 의하여 양도 당시 그 자산의 취득에 관한 등기가 불가능한 자산\nㄷ. 「도시개발법」에 따른 도시개발사업이 종료되지 아니하여 토지 취득등기를 하지 아니하고 양도하는 토지\nㄹ. 건설사업자가 「도시개발법」에 따라 공사용역 대가로 취득한 체비지를 토지구획환지처분공고 후에 양도하는 토지","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄴ, ㄹ","ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":[3],"p":null,"L":"세3-2","S":[],"m":"","f":null},{"i":"36회-2차-120","r":36,"y":2025,"c":2,"g":"2교시","n":40,"q":"다음 자료를 바탕으로 소득세법령상 甲의 토지A에 대한 양도소득세를 계산할 때 양도차익은? (단, 양도차익 계산시 공제할 자본적지출액 등과 양도비 등은 없는 것으로 가정하고. 주어진 조건 이외에는 고려하지 않음)","b":"○ 거주자 甲은 2010. 1. 10. 甲과 특수관계가 없는 자로부터 국내소재 토지A를 5억원에 매입하여 등기한 후, 2025. 5. 3. 은행B에게 토지A에 근저당권을 설정해주고 2억원을 차입하였다.\n○ 甲은 2025. 8. 5. 甲의 동생인 거주자 乙에게 상기 차입금 2억원을 인수하는 조건으로 토지A를 증여(「상속세 및 증여세법」에 따른 시가 및 증여가액 10억원)하였고, 乙은 상기 차입금 전부를 인수하였다.","bs":"글자","img":[],"ch":["0원","1억원","2억원","4억원","5억원"],"a":[2],"p":null,"L":"세3-2","S":[],"m":"","f":null}];